import{a as e}from"./jsx-runtime-Bzw2jH9X.js";var t=e({default:()=>n}),n=JSON.parse(`[{"id":"qx-f-001","clusterId":"F","werkstueckRef":"F.0","stufe":1,"question":"Ein Forschungsteam testet eine kühne, noch unbewiesene Hypothese. Der entscheidende Versuch fällt negativ aus. Woran erkennst du, dass das Team trotz der gewagten Idee ehrlich wissenschaftlich arbeitet und nicht nur den Anschein davon erzeugt?","options":["Es erklärt das Ergebnis zur bloßen Anomalie und hält die Hypothese weiter für unwiderlegt.","Es verlangt von den Kritikern den Nachweis, dass beim Versuch wirklich kein Fehler passiert ist.","Es erkennt das Scheitern des Tests an und passt die Hypothese an oder gibt sie auf.","Es wiederholt den Versuch, bis ein passendes Ergebnis erscheint, und berichtet dann nur dieses."],"correctIndex":2,"explanation":"Eine kühne Hypothese ist noch kein Warnsignal: Spekulation ist legitim, solange sie prüfbar bleibt. Entscheidend ist der Umgang mit dem Scheitern: In ehrlicher Forschung an der Grenze des Wissens wird ein gescheiterter Test anerkannt und führt dazu, dass die Hypothese angepasst oder aufgegeben wird. In der Pseudowissenschaft werden widersprechende Befunde dagegen oft ignoriert, wegerklärt oder umgedeutet, Versuche so lange wiederholt, bis das Ergebnis passt, oder die Beweislast den Kritikern zugeschoben, obwohl sie beim Behauptenden liegt. Wer ein negatives Ergebnis ernst nimmt, zeigt, dass die Idee an der Wirklichkeit scheitern kann, und genau das unterscheidet ehrliche Forschung von bloßer Imitation.","coreRule":"⚡ Eine Idee darf kühn sein und scheitern; verdächtig wird sie, wenn jedes Scheitern wegerklärt wird.","beleg":"Werkstück F.0 (Kontext & Tiefe, Abschnitte II und III)","status":"entwurf","kurz":"Ehrliche Forschung nimmt das Scheitern des Tests ernst und ändert oder verwirft die Hypothese. Kühnheit ist kein Warnsignal, solange die Idee an der Wirklichkeit scheitern kann. Wer Negatives wegerklärt oder umdeutet, schützt die Idee vor jeder Prüfung.","prueffrage":"Welches Ergebnis hätte das Team vorab als Scheitern seiner Hypothese gelten lassen, und gilt das jetzt noch?","rueckmeldung":[{"option":0,"text":"Einzelne Ausreißer gibt es in der Forschung wirklich. Hier aber war der entscheidende Versuch negativ; ihn zur Anomalie zu erklären, schützt die Hypothese davor, je widerlegt zu werden."},{"option":1,"text":"Die Frage nach Fehlern im Versuch ist berechtigt. Doch die Beweislast liegt beim Behauptenden, und wer sie auf die Kritiker abschiebt, weicht dem negativen Ergebnis nur aus."},{"option":3,"text":"Eine Wiederholung kann sinnvoll sein, etwa um Messfehler auszuschließen. Wer aber so lange wiederholt, bis das Ergebnis passt, und nur dieses meldet, unterdrückt den negativen Befund, statt ihn ernst zu nehmen."}],"familie":"immunisierung-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: „Science and Pseudo-Science“","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","seite":"Abschn. 5.1","abruf":"2026-10-12"},{"typ":"url","kurz":"Feynman, R. P. (1974): „Cargo Cult Science“, Engineering and Science 37(7), Caltech-Scan","oeffentlich":true,"url":"https://calteches.library.caltech.edu/51/2/CargoCult.pdf","seite":"S. 11","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft"},{"id":"qx-f-002","clusterId":"F","werkstueckRef":"F.0","stufe":2,"question":"Was ist an dieser Reaktion auf die Pressemitteilung der Denkfehler?","scenario":"Eine Pressemitteilung meldet ein unerwartetes Signal im Detektor: „Es könnte auf neue Physik hindeuten. Messfehler können wir noch nicht ausschließen, deshalb planen wir unabhängige Wiederholungen.“ Ein Kollege winkt ab: „Unbewiesen heißt unwissenschaftlich. Das ist doch genauso Quatsch wie Astrologie.“","options":["Er setzt „noch nicht bewiesen“ mit „unwissenschaftlich“ gleich, obwohl die Mitteilung Unsicherheiten benennt und prüfbare Wiederholungen ankündigt.","Er verlangt zu viel Skepsis, denn ein Signal, das auf neue Physik hindeuten könnte, muss schon vor der Wiederholung als gesichert gelten.","Er urteilt zu vorschnell, denn solange Messfehler nicht ausgeschlossen sind, lässt sich der Status des Signals grundsätzlich nicht beurteilen.","Er prüft die falsche Instanz, denn entscheidend ist, ob die Messung an einer Universität stattfand, und nicht die Frage der Prüfbarkeit."],"correctIndex":0,"explanation":"„Nicht bewiesen“ und „widerlegt“ sind verschiedene Zustände. Eine spekulative, aber prüfbare Hypothese, deren Urheber ihre Unsicherheit offen benennen und weitere Tests planen, verhält sich methodisch wie seriöse Forschung am Rand des Wissens, nicht wie Pseudowissenschaft. Was Pseudowissenschaft (etwa Astrologie) auszeichnet, ist nicht, dass sie unbewiesen wäre, sondern dass sie widersprüchliche Beweise ignoriert oder wegerklärt und die Beweislast systematisch umkehrt. Entscheidend ist die Methode, nicht die Seltsamkeit oder der noch ausstehende Beweis. Wer jede unbestätigte Idee pauschal als Pseudowissenschaft ablehnt, riskiert, potenziell revolutionäre, aber noch unbewiesene Konzepte zu verpassen. Umgekehrt gibt es auch die Falle des Naiven, der jede als „alternativ“ dargestellte Idee für legitime Grenzwissenschaft hält.","coreRule":"⚡ Maßstab ist die Methode, nicht die Seltsamkeit: „noch nicht bewiesen“ ist nicht „widerlegt“.","beleg":"Werkstück F.0 (Anwendung & Relevanz; Red Flags; Werkbank-Frage)","status":"entwurf","kurz":"„Nicht bewiesen“ heißt nicht „unwissenschaftlich“: Die Mitteilung nennt ihre Unsicherheit offen und plant unabhängige Wiederholungen, wie seriöse Forschung am Rand des Wissens. Der Fehler ist, den fehlenden Beweis mit Pseudowissenschaft gleichzusetzen, obwohl die Methode zählt.","prueffrage":"Was haben das Signal im Detektor und die Astrologie gemeinsam, und worin unterscheiden sie sich?","rueckmeldung":[{"option":1,"text":"Die Hoffnung auf neue Physik macht Lust, das Signal ernst zu nehmen, und ernst nehmen darf man es auch. Gesichert ist es aber nicht, solange Messfehler nicht ausgeschlossen sind; genau dafür sind die Wiederholungen da."},{"option":2,"text":"Voreilig urteilt der Kollege tatsächlich; dass sich der Status gar nicht beurteilen ließe, geht aber zu weit. Ob die Methode seriös ist, zeigen die offen benannte Unsicherheit und die geplanten Tests, offen bleibt nur, ob das Signal real ist."},{"option":3,"text":"Eine Universität als Ort wirkt wie ein Gütesiegel, und solche Siegel führen oft zu schnellen Urteilen. Hier zählt aber nicht, wo gemessen wurde, sondern ob die Behauptung prüfbar ist und die Urheber ihre Unsicherheit offenlegen."}],"familie":"wissenschaft-abgrenzen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: „Science and Pseudo-Science“","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","seite":"Abschn. 4.5, 5.1","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft"},{"id":"qx-f-003","clusterId":"F","werkstueckRef":"F.0","stufe":3,"question":"Eine Anbieterin wirbt für ihre Lehre als „mutige Grenzwissenschaft, die von der dogmatischen Schulwissenschaft unterdrückt wird“. Du willst herausfinden, ob die Lehre ernsthafte Forschung am Rand des Wissens oder Pseudowissenschaft ist. Welche Prüfung bringt dich am sichersten weiter?","options":["Du fragst, wie viele Fachleute die Lehre bisher abgelehnt haben, denn je mehr Ablehnung, desto radikaler und damit ernsthafter ist die Idee.","Du fragst, welchen Test die Anbieterin vorschlägt und was für sie als Scheitern der Idee gälte, denn daran zeigt sich, ob sie sich überprüfen lässt.","Du prüfst, wie ungewöhnlich die Behauptung klingt, denn je seltsamer sie ist, desto eher steckt Pseudowissenschaft dahinter.","Du prüfst, ob die Lehre schon in Lehrbüchern steht, denn nur was dort steht, darf überhaupt als ernsthafte Forschung gelten."],"correctIndex":1,"explanation":"Ob eine Idee ernsthafte Erkundung oder Pseudowissenschaft ist, entscheidet sich an der Methode, nicht am Etikett und nicht an der Reaktion der anderen. Wer ehrlich am Rand des Wissens forscht, legt offen, wie man seine Idee testen kann, und akzeptiert, dass ein Scheitern des Tests die Idee widerlegt. Die Kombination aus Selbstlob als „mutig“ und dem Vorwurf, unterdrückt zu werden, ist dagegen ein Warnsignal: Sie erklärt Kritik im Voraus zum Beweis für die eigene Richtigkeit und macht die Lehre damit unangreifbar. Ablehnung durch Fachleute sagt für sich nichts über Radikalität oder Wahrheit, denn auch falsche Ideen werden abgelehnt. Die Seltsamkeit einer Behauptung taugt ebenfalls nicht als Maßstab: Manche seltsam klingende Ideen sind gut testbar, manche harmlos klingende nicht. Und wer nur Lehrbuchwissen gelten lässt, würde jede neue Idee von vornherein aussortieren, auch die, die sich später bewähren.","coreRule":"⚡ Frag nicht „Wie seltsam?“, sondern „Wo ist der Test, und was gälte als Scheitern?“","quote":"","quoteLabel":"","beleg":"Werkstück F.0 (Red Flags; Anwendung & Relevanz; Das Härten im Feuer, Aktivierungs-Frage)","status":"entwurf","scenario":"","kurz":"Ernsthafte Forschung am Rand des Wissens nennt einen Test und akzeptiert, dass sein Scheitern die Idee widerlegt. Wer Kritik dagegen im Voraus zum Beweis erklärt („unterdrückt“), macht sich unangreifbar, und das ist das Warnsignal.","prueffrage":"Was weißt du über die Lehre selbst, nachdem die Anbieterin sie „mutig“ und „unterdrückt“ genannt hat?","rueckmeldung":[{"option":0,"text":"Dass Fachleute auch einmal irren können, macht Ablehnung noch nicht zum Gütesiegel. Auch falsche Ideen werden abgelehnt, die Zahl der Gegner sagt also weder etwas über Radikalität noch über Wahrheit."},{"option":2,"text":"Seltsam klingende Behauptungen wecken schnell Misstrauen. Über ihren Rang entscheidet das aber nicht: Manche kühne Idee ist gut testbar, manche harmlos klingende lässt sich nie überprüfen."},{"option":3,"text":"Was im Lehrbuch steht, ist meist gut geprüft. Als Eintrittskarte taugt das aber nicht, denn neue Forschung steht dort noch nicht: Nach diesem Maßstab fiele jede neue Idee durch, auch die, die sich später bewährt."}],"familie":"wissenschaft-abgrenzen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: „Science and Pseudo-Science“","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","seite":"Abschn. 4.3, 5.1","abruf":"2026-10-12"},{"typ":"url","kurz":"Dowden, B.: „Fallacies“, Internet Encyclopedia of Philosophy","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","seite":"Einträge „Appeal to Ignorance“, „Misplaced Burden of Proof“","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft"},{"id":"qx-f-004","clusterId":"F","werkstueckRef":"F.0","stufe":4,"question":"Ein Bekannter wirft Skeptikern vor: „Ihr lehnt einfach alles Neue ab. Früher hat man auch über Ideen gelacht, die später stimmten.“ Welche Antwort geht auf den Einwand am besten ein?","options":["Neues darf auch ohne Test ernst genommen werden, denn Außenseiter lagen in der Geschichte oft richtig und verdienen deshalb denselben Vertrauensvorschuss.","Neue Ideen sind von vornherein verdächtig, denn wer etablierte Erkenntnisse infrage stellt, liegt fast immer falsch und braucht daher gar nicht erst geprüft zu werden.","Da sich vorher nie sagen lässt, welche Idee sich später bestätigt, sollte man gar keine Einschätzung abgeben und jede neue Idee unbewertet stehen lassen.","Neues ist willkommen, wenn es sich prüfen lässt, doch die meisten solcher Ideen scheitern am Test, und nur wenige setzen sich am Ende als gesichertes Wissen durch."],"correctIndex":3,"explanation":"Der Einwand verwechselt zwei Dinge: ob eine Idee neu oder ungewöhnlich ist und ob sie sich prüfen lässt. Entscheidend ist die Methode, nicht die Seltsamkeit der Behauptung. Zwei Fallen liegen nah. In die Falle des Dogmatikers tappt, wer jede neue, seltsam klingende Idee pauschal ablehnt und so potenziell revolutionäre Konzepte verpasst. In die Falle des Naiven tappt, wer jede als „alternativ“ oder „unterdrückt“ dargestellte Idee für legitim hält und so Scharlatanen auf den Leim geht. Die angemessene Haltung gegenüber spekulativen Ideen ist offene, aber kritische Neugier („Wie können wir sie testen?“). Ob eine Idee sich lohnt, zeigt der Test: Die meisten Ideen am Rand des gesicherten Wissens scheitern und verschwinden, nur wenige entwickeln sich zu etablierter Wissenschaft.","coreRule":"⚡ Offen für Neues, aber nur nach Methode: Prüfbarkeit zählt, nicht Außenseiterstatus. Die meisten Randideen scheitern, einige wenige werden Wissen.","beleg":"Werkstück F.0 (Anwendung & Relevanz: Falle des Dogmatikers und des Naiven; Kontext & Tiefe, Abschnitt II „Fortschritt“)","status":"entwurf","kurz":"Entscheidend ist nicht, ob eine Idee neu klingt, sondern ob sie sich prüfen lässt: Wer Neues pauschal ablehnt oder pauschal begrüßt, ersetzt den Test durch ein Gefühl. Die meisten solcher Ideen scheitern am Test, nur wenige setzen sich durch.","prueffrage":"Wie viele der Ideen, über die früher gelacht wurde, stellten sich später als richtig heraus, und wie viele nicht?","rueckmeldung":[{"option":0,"text":"Dass Außenseiter manchmal recht hatten, stimmt. Im Gedächtnis bleiben aber vor allem die bestätigten Fälle, die vielen gescheiterten fehlen im Bild; ernst nehmen heißt deshalb prüfen, nicht vorab vertrauen."},{"option":1,"text":"Viele Ideen am Rand des Etablierten scheitern, das trifft zu. Ob eine bestimmte dazugehört, zeigt aber erst die Prüfung; wer sie vorab verwirft, verpasst die seltenen Fälle, in denen sie sich bewährt."},{"option":2,"text":"Es stimmt, dass sich vorab selten sicher sagen lässt, welche Idee sich bestätigt. Daraus folgt aber nicht, jede Einschätzung zu unterlassen: Man kann fragen, ob und wie sich die Idee testen lässt, und danach vorläufig urteilen."}],"familie":"wissenschaft-abgrenzen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: „Science and Pseudo-Science“","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","seite":"Abschn. 4.5, 5.1","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft"},{"id":"qx-f-005","clusterId":"F","werkstueckRef":"F.1.1","stufe":1,"question":"Eine Prüferin stellt bei einer Heilmethode fest: Die Beweislast wird umgekehrt, die Aussagen sind nicht widerlegbar, es gibt fast nur Erfolgsgeschichten statt kontrollierter Studien, kritische Studien werden ignoriert, die Grundlehre ist seit Jahrhunderten unverändert und mit der Methode lassen sich teure Seminare verkaufen. Was darfst du daraus am vernünftigsten schließen?","options":["Die Methode imitiert sehr wahrscheinlich nur den Anschein von Wissenschaft, auch wenn nicht jedes denkbare Warnzeichen vorliegt.","Es folgt nichts, denn von Pseudowissenschaft darf man erst sprechen, wenn wirklich jedes denkbare Warnzeichen vorliegt.","Die Methode ist damit endgültig widerlegt, denn jedes einzelne Warnzeichen gilt als eigenständiger Gegenbeweis.","Ein Urteil ist erst zulässig, wenn jede einzelne Behauptung der Methode inhaltlich geprüft wurde."],"correctIndex":0,"explanation":"Die Warnzeichen betreffen Methode und Verhalten, nicht den Inhalt jeder Einzelbehauptung. Eine Disziplin muss nicht alle denkbaren Kriterien erfüllen, damit das Muster aussagekräftig ist: Je mehr davon zutreffen, desto wahrscheinlicher ist es, dass nur die äußere Form von Wissenschaft nachgeahmt wird, ohne ihre Prinzipien (Prüfbarkeit, Selbstkorrektur, Offenheit für Gegenbeweise) zu befolgen. Das ist ein Wahrscheinlichkeitsurteil über die Methode, kein Beweis gegen jede einzelne Aussage. Wer ein vollständiges Kriterienset verlangt, setzt die Messlatte so hoch, dass kaum etwas durchfiele. Wer jedes Warnzeichen als Gegenbeweis wertet, verwechselt Indiz mit Beweis. Und wer erst alle Einzelbehauptungen prüfen will, übersieht, dass sich ein methodisches Muster auch ohne diese Mammutaufgabe erkennen lässt.","coreRule":"⚡ Methodische Warnzeichen sind ein Scanner für Verhalten: Je mehr Treffer, desto wahrscheinlicher Imitation von Wissenschaft, aber nie ein Beweis.","beleg":"Werkstück F.1.1 (Kontext & Tiefe: 10-Punkte-Checkliste, Schlusssatz)","status":"entwurf","scenario":"","kurz":"Mehrere Warnzeichen zusammen machen es wahrscheinlich, dass hier nur die Form von Wissenschaft nachgeahmt wird. Der Fehler wäre, ein vollständiges Set zu verlangen oder aus Indizien einen Beweis zu machen: Es bleibt ein Wahrscheinlichkeitsurteil über die Methode.","prueffrage":"Wie viele der aufgezählten Auffälligkeiten treffen bei dieser Heilmethode zugleich zu?","rueckmeldung":[{"option":1,"text":"Vorsicht vor vorschnellen Urteilen ist sinnvoll. Wer aber alle denkbaren Warnzeichen verlangt, setzt die Messlatte so hoch, dass kaum etwas durchfiele; je mehr Zeichen zutreffen, desto wahrscheinlicher ist das Muster, und hier sind es viele."},{"option":2,"text":"Warnzeichen sind aussagekräftig, aber Indizien, keine Beweise. Sie stützen ein Wahrscheinlichkeitsurteil über die Methode, widerlegen sie aber nicht endgültig; sonst würde schon ein einzelnes Zeichen wie ein Geschäftsinteresse genügen."},{"option":3,"text":"Eine inhaltliche Prüfung aller Einzelbehauptungen wäre gründlich, ist aber keine Voraussetzung für ein Urteil. Die Warnzeichen betreffen Methode und Verhalten, deshalb lässt sich das Muster auch ohne diese Mammutaufgabe erkennen."}],"familie":"wissenschaft-abgrenzen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: „Science and Pseudo-Science“","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","seite":"Abschn. 5.1, 5.2","abruf":"2026-10-12"}],"thema":"Gesundheit"},{"id":"qx-f-006","clusterId":"F","werkstueckRef":"F.1.1","stufe":2,"question":"Was ist an dieser Aussage aus Sicht der wissenschaftlichen Methode das Kernproblem?","scenario":"In einem Reiki-Kurs sagt der Leiter: „Wenn die Energieheilung bei dir nicht gewirkt hat, hat deine Skepsis den Energiefluss blockiert.“","options":["Sie verlangt vom Skeptiker, die Nichtexistenz der Energie zu beweisen, statt selbst Belege zu liefern.","Sie macht die Behauptung unwiderlegbar, weil jedes Scheitern dem Prüfenden angelastet werden kann.","Sie stützt sich auf einzelne Erfolgsgeschichten, statt auf kontrollierte Studien zu verweisen.","Sie greift nur die günstigen Ergebnisse heraus und übergeht die Studien, die dagegensprechen."],"correctIndex":1,"explanation":"Eine Behauptung, die jedes Scheitern auf den Prüfenden abwälzt, kann durch kein Experiment widerlegt werden: Wirkt die Behandlung, gilt sie als bestätigt; wirkt sie nicht, war der Zweifler schuld. Eine Aussage, die mit keinem denkbaren Ergebnis unvereinbar ist, sagt nichts Prüfbares über die Welt. Die anderen drei Fehler gibt es zwar, sie kommen in der Aussage aber nicht vor: Der Leiter verlangt keinen Gegenbeweis, beruft sich auf keine Einzelfälle und wählt keine Studien aus.","coreRule":"⚡ Wenn der Zweifler am Misserfolg schuld sein soll, ist die Behauptung nicht mehr prüfbar.","beleg":"Werkstück F.1.1 (Checkliste Punkt 2, mit Beispiel zur Energieheilung)","status":"entwurf","kurz":"Die Aussage lässt sich nie widerlegen: Wirkt die Behandlung, gilt sie als bestätigt, wirkt sie nicht, war der Zweifler schuld. Eine Behauptung, die mit keinem denkbaren Ergebnis unvereinbar ist, sagt nichts Prüfbares über die Welt.","prueffrage":"Welche Belege, Einzelfälle oder Studien führt der Leiter in seinem Satz überhaupt an?","rueckmeldung":[{"option":0,"text":"Die Umkehr der Beweislast ist ein bekannter Fehler und wirkt hier naheliegend. Der Leiter verlangt aber von niemandem einen Gegenbeweis, sondern erklärt im Nachhinein, warum ein Misserfolg nichts gegen seine Behauptung zeigt."},{"option":2,"text":"Einzelne Erfolgsgeschichten sind tatsächlich ein schwacher Beleg und bei Heilversprechen häufig. Im Satz des Leiters kommen aber weder Erfolgsgeschichten noch Studien vor, er beruft sich auf gar keine Fälle."},{"option":3,"text":"Das Herauspicken günstiger Studien ist ein echter Denkfehler und passt zu vielen Heilversprechen. Der Leiter nennt hier jedoch überhaupt keine Studien, weder günstige noch ungünstige. Sein Problem liegt in der Konstruktion des Satzes selbst."}],"familie":"immunisierung-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: „Science and Pseudo-Science“","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","seite":"Abschn. 4.3, 5.1","abruf":"2026-10-12"}],"thema":"Gesundheit"},{"id":"qx-f-007","clusterId":"F","werkstueckRef":"F.1.1","stufe":3,"question":"Woran würdest du erkennen, dass aus dieser Hypothese eine Pseudowissenschaft geworden ist?","options":["Sie bleibt so lange unbewiesen, dass die Fachwelt das Interesse verliert und nicht mehr widerspricht.","Sie benutzt Begriffe, die nur Eingeweihte verstehen, und wirkt dadurch für Außenstehende unprüfbar.","Sie ist nicht mehr testbar und bestätigt sich selbst, weil jedes denkbare Ergebnis zu ihren Gunsten ausgelegt wird.","Die Mehrheit der Fachleute lehnt sie ab, denn eine Ablehnung durch viele macht eine Prüfung überflüssig."],"correctIndex":2,"explanation":"Spekulative, seltsame oder lange unbestätigte Ideen können Wissenschaft bleiben, solange ein Test sie widerlegen könnte. Kippen tut sie, wenn sie sich der Prüfung entzieht: Wer Fehlschläge mit Ausreden auffängt und jedes Ergebnis als Bestätigung liest, hat aus der Hypothese ein Glaubenssystem gemacht, das nichts mehr widerlegen kann. Die Dauer der Unbestätigtheit, eine schwer verständliche Fachsprache oder die Ablehnung durch viele sagen dagegen nichts darüber, ob die Idee noch scheitern darf. Eine Mehrheitsmeinung kann auch irren. Entscheidend ist die Prüfbarkeit selbst.","coreRule":"⚡ Nicht die Dauer oder die Seltsamkeit entscheidet, sondern ob die Idee noch scheitern darf.","beleg":"Werkstück F.1.1 (Der Kipppunkt)","status":"entwurf","scenario":"Eine Forscherin vertritt seit 20 Jahren eine ungewöhnliche Hypothese, die bisher niemand bestätigen konnte. In den vergangenen Jahren sind mehrere Experimente zur Hypothese gescheitert. Ihre Reaktion: Die Experimente seien nicht empfindlich genug gewesen, denn die Wirkung zeige sich nur, wenn niemand sie zu messen versucht. Jedes weitere Ergebnis deutet sie als Bestätigung.","kurz":"Eine Hypothese kippt zur Pseudowissenschaft, wenn kein denkbares Ergebnis sie mehr widerlegen könnte: Hier wird jeder Fehlschlag mit Ausreden aufgefangen und jedes Ergebnis als Bestätigung gelesen. Wie lange sie unbestätigt bleibt, entscheidet dagegen nicht.","prueffrage":"Wie viele Experimente sind bisher gescheitert, und was folgerte die Forscherin jeweils daraus?","rueckmeldung":[{"option":0,"text":"Dass eine Idee lange unbestätigt bleibt und die Fachwelt weiterzieht, sagt über ihre Prüfbarkeit nichts. Auch lange unbestätigte Ideen bleiben Wissenschaft, solange ein Test sie widerlegen könnte."},{"option":1,"text":"Schwer verständliche Begriffe gibt es auch in solider Forschung, daher taugen sie nicht als Merkmal. Entscheidend ist, ob ein Test die Hypothese noch zu Fall bringen könnte, nicht, wie zugänglich ihre Sprache ist."},{"option":3,"text":"Eine Ablehnung durch viele kann ein Anlass sein, genauer hinzusehen. Sie ersetzt aber keine Prüfung, denn auch eine Mehrheit kann irren. Ob eine Idee Wissenschaft bleibt, hängt an ihrer Widerlegbarkeit, nicht an der Zahl ihrer Gegner."}],"familie":"wissenschaft-abgrenzen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: „Science and Pseudo-Science“","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","seite":"Abschn. 3.6, 4.3, 5.1","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft"},{"id":"qx-f-008","clusterId":"F","werkstueckRef":"F.1.1","stufe":4,"question":"Wie solltest du auf dieses Seminarversprechen reagieren, wenn du seine Stichhaltigkeit prüfen willst?","options":["Du fragst, was „Quantenheilung“ und „biologische Schwingung“ genau bedeuten und wie man ihre Wirkung testen könnte. Bleibt die Antwort vage, ist der Anspruch nicht prüfbar.","Du wartest ab, ob jemand das Gegenteil beweist. Solange niemand zeigt, dass es nicht wirkt, darfst du das Versprechen als vorläufig plausibel ansehen.","Du sammelst Erfahrungsberichte von Teilnehmenden. Fallen sie überwiegend positiv aus, ist das ein belastbarer Hinweis auf eine echte Wirkung der Methode.","Du prüfst, ob die Kritik an der etablierten Wissenschaft berechtigt ist. Gibt es dort Streit oder Lücken, spricht das für die Alternative des Seminars."],"correctIndex":0,"explanation":"Wissenschaftlich klingende Wörter beweisen nichts; entscheidend ist, ob eine Behauptung etwas Bestimmtes aussagt, das sich testen lässt. „Quantenheilung“ und „biologische Schwingung“ klingen nach Physik, ohne eine nachprüfbare Bedeutung zu haben, und der Verweis auf „Ganzheitlichkeit“ verlegt den Anspruch dorthin, wo ihn angeblich keine Prüfung erreicht. Die Rückfrage nach Bedeutung und Prüfbarkeit deckt genau das auf. Ein Versprechen gelten zu lassen, solange niemand das Gegenteil beweist, kehrt die Beweislast um: Wer etwas behauptet, muss es belegen. Erfahrungsberichte sind Anekdoten ohne Vergleich, und „Die Wissenschaft hat Lücken, also stimmt die Alternative“ ist ein Argument aus Unwissenheit.","coreRule":"⚡ Klingt eine Behauptung wissenschaftlich und beruft sich auf „Ganzheitlichkeit“, frag zuerst nach Bedeutung und Prüfbarkeit, bevor du Belege würdigst.","beleg":"Werkstück F.1.1 (Checkliste Punkte 8 und 9)","status":"entwurf","scenario":"Ein Seminar verspricht „Quantenheilung durch biologische Schwingung“. Auf Nachfrage heißt es, das sei „ganzheitlicher“, als es die „reduktionistische“ Wissenschaft je erfassen könne. Studien oder Messwerte werden nicht genannt.","kurz":"Wissenschaftlich klingende Wörter beweisen nichts. Die Rückfrage nach Bedeutung und Prüfbarkeit zeigt, ob überhaupt etwas Bestimmtes behauptet wird, und das Berufen auf „Ganzheitlichkeit“ entzieht den Anspruch jeder Widerlegung.","prueffrage":"Was genau soll bei Teilnehmenden nach dem Seminar anders sein als vorher?","rueckmeldung":[{"option":1,"text":"Dass bisher niemand das Gegenteil bewiesen hat, wirkt wie ein Pluspunkt. Wer etwas verspricht, muss es aber belegen; und ein Versprechen, das sich nicht prüfen lässt, ist auch nicht widerlegbar. Das macht es nicht plausibel."},{"option":2,"text":"Positive Berichte können echt und ehrlich sein, doch ohne Vergleichsgruppe zeigen sie nicht, ob die Methode etwas bewirkt hat. Wer bleibt und erzählt, ist zudem eine Auswahl, und Besserung kann auch andere Gründe haben."},{"option":3,"text":"Streit und Lücken in der Wissenschaft gibt es tatsächlich. Sie sind aber noch kein Beleg für eine Alternative, die selbst nichts Prüfbares behauptet. „Die anderen können es nicht erklären“ ersetzt nicht den eigenen Nachweis."}],"familie":"wissenschaft-abgrenzen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Dowden, B.: „Fallacies“, Internet Encyclopedia of Philosophy","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","seite":"Einträge „Appeal to Ignorance“, „Misplaced Burden of Proof“","abruf":"2026-10-12"},{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: „Science and Pseudo-Science“","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","seite":"Abschn. 4.3, 5.1","abruf":"2026-10-12"}],"thema":"Gesundheit"},{"id":"qx-f-009","clusterId":"F","werkstueckRef":"F.1.2","stufe":1,"question":"Ein Sportler trägt seit Jahren vor jedem Spiel seine Glückssocken, obwohl er weiß, dass sie nichts bewirken. Ein Kollege fragt ihn: „Warum machst du das dann?“ Welche Antwort ist die sinnvollste Erklärung für sein Verhalten?","options":["Das Ritual verbessert nachweislich seine Leistung, sonst hätte es sich nicht über Jahre gehalten.","Das Ritual kann seine Anspannung dämpfen und ihm ein Gefühl von Kontrolle geben, auch wenn offen bleibt, ob er dadurch besser spielt.","Das Ritual zeigt, dass zwischen Socken und Ergebnis doch ein kausaler Zusammenhang besteht, den die Wissenschaft noch nicht kennt.","Das Ritual schützt ihn vor Misserfolg, weil er bei einer Niederlage die Socken als Ursache ausschließen kann."],"correctIndex":1,"explanation":"Wer sich einer Situation mit unsicherem Ausgang gegenübersieht, kann durch ein Ritual das Gefühl gewinnen, den Ausgang irgendwie zu beeinflussen. Dieses Gefühl von Kontrolle kann Angst dämpfen, auch wenn der Sportler rational weiß, dass die Socken nichts bewirken. Ein Feldexperiment mit religiösen Tempelritualen (Lang, Krátký und Xygalatas, 2020) deutet auf weniger berichtete Angst und weniger körperliche Anspannung nach einer Stressaufgabe hin (nach Angabe der Autoren erste, nicht laborgenau kontrollierte Belege); ob dasselbe für private Glücksrituale gilt, ist damit nicht gezeigt. Dass ein Ritual lange überdauert, beweist keine Wirkung auf das Ergebnis: Ein vielzitierter Leistungsbefund ließ sich in größeren Wiederholungen nicht bestätigen. Dass das Ritual vor Misserfolg schützt oder ihn als Ursache ausschließt, ist nicht belegt; der psychologische Gewinn solcher Rituale liegt im Gefühl von Kontrolle und in gedämpfter Angst, nicht in einer Entlastung bei Niederlagen.","coreRule":"⚡ Ein Ritual kann beruhigen, ohne das Ergebnis zu beeinflussen: Trenne das Gefühl von Kontrolle von der tatsächlichen Wirkung.","beleg":"Werkstück F.1.2 (Kontext & Tiefe; Fn. gl-f-ritual-angst: Lang, Krátký, Xygalatas 2020, Abschn. 3 und 4)","status":"entwurf","scenario":"","kurz":"Das Ritual kann Anspannung dämpfen und ein Gefühl von Kontrolle geben, auch wenn der Sportler weiß, dass die Socken den Ausgang nicht beeinflussen. Ob er dadurch besser spielt, bleibt offen: Ein Gefühl zu erklären heißt nicht, eine Wirkung auf das Ergebnis zu belegen.","prueffrage":"Was ließe sich beim Sportler vor einem Spiel mit und ohne Socken tatsächlich beobachten oder messen?","rueckmeldung":[{"option":0,"text":"Dass sich ein Ritual über Jahre hält, wirkt wie ein Beweis, ist aber keiner: Auch wirkungslose Gewohnheiten bleiben bestehen. Ein vielzitierter Leistungsbefund ließ sich in größeren Wiederholungen nicht bestätigen."},{"option":2,"text":"Ein unbekannter Zusammenhang lässt sich nie ganz ausschließen, doch nichts deutet hier auf einen hin: Gefühl von Kontrolle und gedämpfte Angst erklären das Verhalten schon, und der Sportler weiß selbst, dass die Socken nichts bewirken."},{"option":3,"text":"Sich vor dem Scheitern schützen zu wollen, ist ein nachvollziehbares Motiv, doch dass Rituale so funktionieren, ist nicht belegt. Besser gestützt ist ein anderer Gewinn: gedämpfte Angst und ein Gefühl von Kontrolle vor dem Spiel."}],"familie":"was-waere-ohne","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Lang, M.; Krátký, J.; Xygalatas, D. (2020): „The role of ritual behaviour in anxiety reduction“, Philosophical Transactions of the Royal Society B 375(1805)","oeffentlich":true,"doi":"10.1098/rstb.2019.0431","abruf":"2026-10-12"},{"typ":"doi","kurz":"Calin-Jageman, R. J.; Caldwell, T. L. (2014): „Replication of the Superstition and Performance Study by Damisch, Stoberock, and Mussweiler (2010)“, Social Psychology 45(3)","oeffentlich":false,"doi":"10.1027/1864-9335/a000190"}],"thema":"Psychologie"},{"id":"qx-f-010","clusterId":"F","werkstueckRef":"F.1.2","stufe":2,"question":"Was ist an dieser Deutung das eigentliche Problem?","scenario":"Dein Kollege trägt zur Prüfung immer dieselbe Glückskette. Besteht er, sagt er: „Siehst du, sie wirkt.“ Fällt er durch, sagt er: „Ich habe sie zu spät angezogen.“","options":["Er hat nur wenige bestandene Prüfungen mit der Kette erlebt; erst nach vielen weiteren Erfolgen wäre ihre Wirkung belegt.","Er trägt die Kette überhaupt; schon dass er ein Ritual braucht, ist der Denkfehler, egal wie er die Ergebnisse deutet.","Er hat die Kette noch nicht lange genug ausprobiert; erst nach vielen Misserfolgen ließe sich ihre Wirkung beurteilen.","Er wertet Erfolg als Beweis für die Kette und Misserfolg als eigenen Fehler; so kann nichts die Kette widerlegen."],"correctIndex":3,"explanation":"Entscheidend ist die ungleiche Auswertung: Ein Treffer bestätigt das Ritual, ein Fehlschlag wird dem Anwender angelastet. Damit gibt es kein denkbares Ergebnis, das gegen die Kette sprechen würde, die Behauptung ist nicht widerlegbar und sagt deshalb auch nichts aus. Mehr Durchgänge allein ändern daran nichts, solange jedes Ergebnis in dieselbe Richtung gedeutet wird. Ob ein Ritual wirkt, ließe sich nur in einem kontrollierten Vergleich mit und ohne Ritual prüfen. Ein kleines Ritual selbst ist dagegen nicht das Problem: Es kann beruhigen und ist harmlos, solange man ihm keine Wirkung auf das Ergebnis zuschreibt, die es nicht belegt hat.","coreRule":"⚡ Wenn nur Erfolge dem Ritual zählen und Misserfolge dem Menschen, ist das Ritual immun gegen Widerlegung.","beleg":"Werkstück F.1.2 (Red Flags: asymmetrische Erklärung; Der Kipppunkt)","status":"entwurf","kurz":"Die Deutung ist so gebaut, dass jedes Ergebnis die Kette stützt: Erfolg gilt als Wirkung, Misserfolg als Anwenderfehler. Der naheliegende Fehler ist, so ein Erlebnis für einen Beleg zu halten, obwohl nichts die Kette je widerlegen könnte.","prueffrage":"Was würde sich an seiner Deutung ändern, wenn er die Kette noch zwanzig weitere Prüfungen lang trägt?","rueckmeldung":[{"option":0,"text":"Wenige Erfolge belegen tatsächlich wenig. Aber auch viele weitere würden daran nichts ändern, solange Misserfolge stets weggedeutet werden: Die Schwäche liegt in der Auswertung, nicht in der Zahl der Fälle."},{"option":1,"text":"Ein kleines Ritual kann beruhigen und schadet nicht. Fragwürdig wird es erst, wenn man ihm eine Wirkung auf das Ergebnis zuschreibt, die nie belegt wurde; und selbst das liegt an der Deutung, nicht am Tragen der Kette."},{"option":2,"text":"Auch viele Misserfolge würden hier nichts klären, denn jeder würde als „zu spät angezogen“ verbucht. Mehr Zeit hilft nicht, solange kein denkbares Ergebnis gegen die Kette zählen darf; prüfbar wäre sie nur im Vergleich mit und ohne Kette."}],"familie":"immunisierung-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Skinner, B. F. (1948): „'Superstition' in the Pigeon“, Journal of Experimental Psychology 38 (Nachdruck Classics in the History of Psychology)","oeffentlich":true,"url":"https://psychclassics.yorku.ca/Skinner/Pigeon/","abruf":"2026-10-12"},{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: „Science and Pseudo-Science“","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","seite":"Abschn. 4.3, 5.1","abruf":"2026-10-12"}],"thema":"Psychologie"},{"id":"qx-f-011","clusterId":"F","werkstueckRef":"F.1.2","stufe":3,"question":"Bei welcher Person ist die Grenze vom harmlosen Ritual zum echten Problem überschritten?","options":["Ein Student klopft vor der Klausur dreimal auf Holz und lernt trotzdem wie geplant.","Eine Torfrau zieht vor jedem Spiel zuerst den linken Handschuh an, weil es sie beruhigt.","Eine Unternehmerin sagt eine gut vorbereitete Geschäftsentscheidung ab, weil ihr Tageshoroskop davon abrät.","Eine Familie meidet aus Gewohnheit Reisen am Freitag, dem 13., und wählt sonst nach Sachlage."],"correctIndex":2,"explanation":"Ein Aberglaube ist dann ein Problem, wenn er echte, kostspielige Entscheidungen steuert, wenn er zwanghaft wird, wenn er wirksames Handeln ersetzt oder wenn er bei Misserfolg zu Selbstvorwürfen führt. Ein Horoskop, das darüber entscheidet, ob eine wichtige Geschäftsentscheidung fällt, hat mit dem Erfolg des Geschäfts nichts zu tun, kann aber viel Geld kosten. Die anderen drei Rituale sind klein, werden bewusst gehandhabt und steuern keine kostspielige Entscheidung. Sie können sogar beruhigen, weil sie ein Gefühl von Kontrolle geben, ohne den Ausgang zu beeinflussen.","coreRule":"⚡ Harmlos ist das Ritual, das beruhigt; gefährlich wird es, wenn es Entscheidungen steuert.","beleg":"Werkstück F.1.2 (Der Kipppunkt, Punkt 1 bis 4)","status":"entwurf","scenario":"Vier Personen pflegen jeweils einen kleinen Aberglauben. Alle vier wissen, dass ihr Ritual keine nachweisbare Wirkung hat; es geht darum, was das Ritual im Alltag tatsächlich anrichtet.","kurz":"Problematisch wird ein Aberglaube, sobald er eine kostspielige Sachentscheidung steuert. Ein Horoskop hat mit dem Erfolg eines Geschäfts nichts zu tun, kann die Entscheidung aber verhindern. Kleine Rituale, die nichts verdrängen, können sogar beruhigen.","prueffrage":"Welche der vier Personen ändert wegen ihres Rituals überhaupt etwas an einer Entscheidung?","rueckmeldung":[{"option":0,"text":"Dreimal Holz zu klopfen wirkt wie ein Aberglaube, der ins Handeln eingreift. Der Student lernt aber wie geplant weiter, das Ritual ersetzt also nichts und kann höchstens beruhigen."},{"option":1,"text":"Dass ein Brauch rational nicht zu begründen ist, macht ihn noch nicht problematisch. Der Handschuh gibt der Torfrau ein Gefühl von Kontrolle, entscheidet aber nichts und verdrängt keine Vorbereitung."},{"option":3,"text":"Reisen am Freitag, dem 13., zu meiden, hat tatsächlich keinen sachlichen Grund. Die Familie verschiebt damit aber höchstens einen Reisetag und wählt sonst nach Sachlage; eine kostspielige Entscheidung steuert der Brauch nicht."}],"familie":"ergaenzen-oder-ersetzen","fertigkeit":"F4","quellen":[{"typ":"doi","kurz":"Lang, M.; Krátký, J.; Xygalatas, D. (2020): „The role of ritual behaviour in anxiety reduction“, Philosophical Transactions of the Royal Society B 375(1805)","oeffentlich":true,"doi":"10.1098/rstb.2019.0431","abruf":"2026-10-12"},{"typ":"doi","kurz":"Carlson, S. (1985): „A double-blind test of astrology“, Nature 318","oeffentlich":false,"doi":"10.1038/318419a0"}],"thema":"Psychologie"},{"id":"qx-f-012","clusterId":"F","werkstueckRef":"F.1.2","stufe":4,"question":"Eine Freundin zündet eine Kerze an, um „Reichtum anzuziehen“, und bekommt drei Wochen später eine Gehaltserhöhung. Sie sagt: „Siehst du, es hat funktioniert!“ Warum ist das noch kein Beleg dafür, dass die Kerze gewirkt hat?","options":["Dass etwas danach geschah, zeigt nicht, dass es deswegen geschah; erst der Vergleich mit und ohne Kerze würde eine Wirkung zeigen.","Gehaltserhöhungen entstehen ausschließlich durch Leistung, deshalb kann kein äußeres Ereignis dazu beitragen oder sie beeinflussen.","Drei Wochen sind für die Beurteilung zu kurz, denn erst über mehrere Monate lässt sich eine mögliche Wirkung sicher einschätzen.","Rituale wirken nur bei Menschen, die fest daran glauben, und die Freundin hat vermutlich Zweifel an der Wirkung der Kerze."],"correctIndex":0,"explanation":"Die Kerze steht vor der Gehaltserhöhung, aber zeitliche Abfolge ist keine Ursache. Das ist der Fehlschluss „danach, also deswegen“. Es gibt keine plausible Verbindung zwischen einer brennenden Kerze und dem Gehalt, und ein einzelner Treffer ist mit Zufall bestens erklärbar: Gehaltserhöhungen kommen auch ohne Kerzen vor. Erst ein Vergleich würde zeigen, ob Menschen mit Kerze häufiger eine Erhöhung bekommen als Menschen ohne. Die Ausrede, das Ritual wirke nur bei Gläubigen, wäre dagegen genau die Absicherung, die eine Behauptung unprüfbar macht: Gelingt es, gilt es als Beweis, gelingt es nicht, hat der Anwender angeblich nicht genug geglaubt. Und mehr Wartezeit löst das Problem nicht, denn auch nach Monaten bleibt eine bloße Abfolge ohne Vergleich nur eine Abfolge.","coreRule":"⚡ Wer von „danach“ auf „deswegen“ schließt, braucht einen Vergleich mit und ohne die vermutete Ursache; die bloße Reihenfolge reicht nie.","beleg":"Werkstück F.1.2 (Kontext & Tiefe: Post hoc; Anwendung & Relevanz: In der Esoterik & New Age)","status":"entwurf","scenario":"","quote":"","quoteLabel":"","kurz":"Die Kerze stand vor der Erhöhung, doch Abfolge ist keine Ursache, und ein einzelner Treffer lässt sich mit Zufall erklären. Erst ein Vergleich mit und ohne Kerze würde zeigen, ob sie etwas bewirkt.","prueffrage":"Was ist in den drei Wochen zwischen Kerze und Gehaltserhöhung sonst noch geschehen, etwa bei ihrer Arbeit oder im Betrieb?","rueckmeldung":[{"option":1,"text":"Leistung spielt bei Gehaltserhöhungen eine große Rolle, aber „ausschließlich“ ist zu absolut: Auch Budget, Tarif oder Zeitpunkt wirken mit. Entscheidend ist ohnehin, dass ein einzelnes Ereignis nach der Kerze noch keine Wirkung belegt."},{"option":2,"text":"Eine einzelne Beobachtung nach drei Wochen ist tatsächlich dünn. Mehr Wartezeit würde das Problem aber nicht lösen: Auch nach Monaten bliebe es eine bloße Abfolge ohne Vergleich, und der fehlt hier."},{"option":3,"text":"Erwartungen können beeinflussen, wie wir etwas erleben. Doch „wirkt nur bei Gläubigen“ macht die Behauptung unprüfbar, denn klappt es nicht, hat man angeblich zu wenig geglaubt; zudem glaubt die Freundin offenbar daran."}],"familie":"was-waere-ohne","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: „Fallacies“, Internet Encyclopedia of Philosophy","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","seite":"Eintrag „Post Hoc“","abruf":"2026-10-12"},{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: „Science and Pseudo-Science“","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","seite":"Abschn. 4.3, 5.1","abruf":"2026-10-12"}],"thema":"Psychologie"},{"id":"qx-f-013","clusterId":"F","werkstueckRef":"F.1.3","stufe":1,"question":"Ein Online-Beitrag behauptet: „Eine geheime Elite steuert seit Jahrzehnten die Weltpolitik, ohne dass je ein Mitwisser geplaudert hat. Dass sie ständig verräterische Symbole in Filmen und Logos versteckt, beweist: Sie ist so sicher, dass sie sich nicht verstecken muss.“ Welcher Widerspruch macht diese Erzählung unglaubwürdig?","options":["Dieselbe Gruppe soll so umsichtig sein, dass sie ein Geheimnis jahrzehntelang perfekt wahrt, und so nachlässig, dass jeder Hobbydetektiv ihre Spuren findet.","Dieselbe Gruppe soll im Verborgenen sehr klein sein und zugleich in ihrer Wirkung weltumspannend, obwohl kleine Gruppen immer nur lokal wirken können.","Dieselbe Gruppe soll böswillig handeln und trotzdem von ihren Opfern ausdrücklich gelobt werden, weil sie deren Interessen vertritt.","Dieselbe Gruppe soll allmächtig sein und wird dennoch von den Verfassern der Erzählung nicht ernsthaft bekämpft, sondern nur beschrieben."],"correctIndex":0,"explanation":"Die Erzählung braucht einen Feind, der zwei Dinge zugleich sein muss: übermenschlich kompetent (er hält eine globale Verschwörung jahrzehntelang geheim) und unfassbar dumm (er hinterlässt „Hinweise“, die jeder YouTube-Detektiv finden kann). Beides gleichzeitig ist kaum plausibel. Wenn eine Erklärung nur funktioniert, indem sie ihrem Feind widersprüchliche Eigenschaften zuschreibt, ist das ein Warnsignal.","coreRule":"⚡ Allmächtig und doch schlampig: Wenn der Feind beides zugleich sein muss, trägt die Erzählung nicht.","beleg":"Werkstück F.1.3 (Kontext & Tiefe, Anatomie, Punkt 1: Ein allmächtiger, böswilliger Feind)","status":"entwurf","scenario":"","kurz":"Die Gruppe soll zugleich so perfekt sein, dass nie jemand plaudert, und so nachlässig, dass jeder ihre Symbole findet. Wenn ein Feind widersprüchliche Eigenschaften braucht, damit die Erzählung aufgeht, ist das ein Warnsignal.","prueffrage":"Wie erklärt der Beitrag, dass die angeblichen Symbole offen in Filmen und Logos zu sehen sind?","rueckmeldung":[{"option":1,"text":"Dass die Gruppe klein, aber weltumspannend wirken soll, hat man oft bei solchen Erzählungen im Ohr. Der Beitrag sagt über ihre Größe aber nichts, und kleine Gruppen können durchaus weit wirken. Der Widerspruch liegt woanders."},{"option":2,"text":"Ein Widerspruch zwischen Absicht und Wirkung klingt plausibel, doch von einem Lob durch die Opfer ist im Beitrag keine Rede. Die Unstimmigkeit steckt in den Eigenschaften, die der Gruppe selbst zugeschrieben werden."},{"option":3,"text":"Was die Verfasser selbst tun, sagt etwas über sie, aber nichts über die innere Stimmigkeit ihrer Behauptung. Der Widerspruch steckt in dem, was der Beitrag der Gruppe zuschreibt, nicht darin, wie die Verfasser auf sie reagieren."}],"familie":"verschwoerung-pruefen","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Grimes, D. R. (2016): „On the Viability of Conspiratorial Beliefs“, PLOS ONE 11(1), e0147905","oeffentlich":true,"doi":"10.1371/journal.pone.0147905","abruf":"2026-10-12"},{"typ":"url","kurz":"Lewandowsky, S.; Cook, J. (2020): The Conspiracy Theory Handbook","oeffentlich":true,"url":"https://skepticalscience.com/docs/ConspiracyTheoryHandbook.pdf","seite":"Abschnitt CONSPIR, „Contradictory“","abruf":"2026-10-12"}],"thema":"Netz und Medien"},{"id":"qx-f-014","clusterId":"F","werkstueckRef":"F.1.3","stufe":2,"question":"Wie erklärst du am besten, dass dir die Saboteur-Geschichte verführerischer vorkommt, obwohl sie kaum belegt ist?","scenario":"In deinem Haus zeigen sich Risse in der Wand, und die Tür klemmt. Ein Gutachter nennt instabilen Baugrund: ein komplexes, teures Problem, das ein aufwendiges Stabilisieren des Fundaments verlangt. Dein Nachbar flüstert dagegen, eine geheime Immobilien-Lobby wolle das Viertel billig aufkaufen und schlage nachts mit dem Hammer gegen dein Fundament. Der klemmende Türrahmen sei der Beweis.","options":["Sie kommt mit weniger Annahmen aus als die Erklärung des Gutachters und ist deshalb nach dem Prinzip der Sparsamkeit die bessere Erklärung.","Sie ist einfach und dramatisch und bietet einen Feind, gegen den man kämpfen kann; sie erfüllt das Bedürfnis nach Sinn und Kontrolle, ohne mehr Belege zu liefern.","Sie ist am Ende billiger, weil sie dem Hausbesitzer eine aufwendige Sanierung des Fundaments erspart und ihn damit entlastet.","Sie wird durch den Zusammenhang von Rissen und klemmender Tür belegt, den der Gutachter in seiner Erklärung nicht berücksichtigt hat."],"correctIndex":1,"explanation":"Wie verführerisch eine Erklärung wirkt, sagt nichts darüber, wie gut sie belegt ist. Die Saboteur-Geschichte bietet einen klaren Bösewicht, einen einfachen Plan und das Gefühl, Bescheid zu wissen und handeln zu können. Die Erklärung des Gutachters ist dagegen kompliziert, beängstigend und teuer, obwohl sie die Risse und die klemmende Tür ebenfalls erklärt. Dass eine Geschichte emotional befriedigt, ist kein Beleg für ihre Wahrheit. Der „Beweis“ klemmende Tür passt zu beiden Erklärungen und trennt sie deshalb nicht. Ein Saboteur mit Hammer müsste zudem zusätzliche Annahmen tragen (eine geheime Lobby, nächtliche Einbrüche, ein Motiv), sodass auch das Argument der Sparsamkeit gegen ihn spricht. Die Forschung zu Verschwörungsglauben zeigt außerdem: Er wird von Bedürfnissen nach Sinn, Kontrolle und Zugehörigkeit getrieben, erfüllt sie aber meist nicht.","coreRule":"⚡ Eine Erklärung kann sich gut anfühlen und trotzdem schlecht belegt sein: Prüfe Belege, nicht den Gefühlswert.","beleg":"Werkstück F.1.3 (Das rissige Fundament; Kernidee; Anatomie, Punkt 2: Apophenie)","status":"entwurf","quote":"","quoteLabel":"","kurz":"Wie verführerisch eine Geschichte wirkt, sagt nichts über ihre Belege. Die Saboteur-Version liefert einen Feind und das Gefühl, handeln zu können; der Fehler wäre, aus diesem Gefühl auf Wahrheit zu schließen. Die klemmende Tür passt zu beiden Erklärungen.","prueffrage":"Was bietet die Geschichte des Nachbarn dem Hausbesitzer, das ihm das Gutachten nicht bietet?","rueckmeldung":[{"option":0,"text":"Sparsamkeit ist ein gutes Prinzip, aber hier spricht es gegen den Saboteur: Eine geheime Lobby, nächtliche Hammerschläge und ein Motiv sind viele Zusatzannahmen, der Baugrund des Gutachters ist nur eine."},{"option":2,"text":"Die Aussicht, sich die teure Sanierung zu sparen, kann die Geschichte attraktiv machen. Billiger wird es dadurch aber nicht, denn die Risse bleiben; überzeugend wirkt die Geschichte eher durch Feindbild, Sinn und Kontrolle."},{"option":3,"text":"Risse und klemmende Tür passen zum Saboteur, aber ebenso zum instabilen Baugrund, den der Gutachter nennt. Eine Beobachtung, die beide Erklärungen gleich gut erklärt, spricht für keine von beiden."}],"familie":"verschwoerung-pruefen","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Douglas, K. M.; Sutton, R. M.; Cichocka, A. (2017): „The Psychology of Conspiracy Theories“, Current Directions in Psychological Science 26(6)","oeffentlich":true,"doi":"10.1177/0963721417718261","abruf":"2026-10-12"},{"typ":"url","kurz":"Lewandowsky, S.; Cook, J. (2020): The Conspiracy Theory Handbook","oeffentlich":true,"url":"https://skepticalscience.com/docs/ConspiracyTheoryHandbook.pdf","abruf":"2026-10-12"}],"thema":"Zusammenleben"},{"id":"qx-f-015","clusterId":"F","werkstueckRef":"F.1.3","stufe":3,"question":"Er sagt: „Seit ich die Verschwörung durchschaue, habe ich endlich Kontrolle in einer chaotischen Welt.“ Wie solltest du diese Aussage einordnen?","options":["Das Gefühl ist verständlich, denn Sinn und Kontrolle sind genau die Motive, die solchen Glauben antreiben. Dass er sie auch erfüllt, ist aber unbelegt; in Experimenten schwächte schon das Lesen solcher Erzählungen das Kontrollgefühl.","Das Gefühl ist verständlich, denn Sinn und Kontrolle sind genau die Motive, die solchen Glauben antreiben. Dass er sie auch erfüllt, gilt als gesichert; Anhänger berichten durchweg von mehr Kontrolle und Zuversicht als vorher.","Das Gefühl ist verständlich, denn Sinn und Kontrolle sind genau die Motive, die solchen Glauben antreiben. Erfüllt werden sie meist tatsächlich, nur das Bedürfnis nach Gemeinschaft bleibt offen, weil sich Anhänger zurückziehen.","Das Gefühl ist verständlich, denn Sinn und Kontrolle sind genau die Motive, die solchen Glauben antreiben. Ob der Glaube sie erfüllt, lässt sich nicht beurteilen, weil das bisher nie untersucht oder gemessen wurde."],"correctIndex":0,"explanation":"Es ist wichtig, zwei Fragen zu trennen: Warum glaubt jemand? Und: Bekommt er, was er sich davon verspricht? Die Forschung (Douglas, Sutton und Cichocka 2017) führt den Glauben auf epistemische, existenzielle und soziale Motive zurück, etwa das Bedürfnis nach Sinn, Kontrolle und Zugehörigkeit. Einen Beleg, dass der Glaube diese Bedürfnisse erfüllt, gibt es aber nicht. In Experimenten schwächte schon das Lesen von Verschwörungserzählungen das Gefühl von Kontrolle. Das Gefühl deines Freundes ist real, belegt aber nicht, dass die Erzählung ihm tatsächlich Kontrolle verschafft. Die Aussage „Es fühlt sich nach Kontrolle an“ ist etwas anderes als „Ich habe Kontrolle“.","coreRule":"⚡ Wer fragt, ob ein Glaube ein Bedürfnis erfüllt, darf das Versprechen nicht mit dem Befund verwechseln: Verschwörungsglaube verspricht Halt, löst ihn aber meist nicht ein.","beleg":"Werkstück F.1.3 (Das Adaptive Talent); Fn. gl-f-douglas (Douglas, Sutton, Cichocka 2017, S. 538 f.)","status":"entwurf","scenario":"Ein Freund beschäftigt sich seit Monaten mit einer Verschwörungserzählung. Du erinnerst dich an psychologische Experimente, in denen untersucht wurde, wie sich das Lesen von Verschwörungserzählungen auf das Gefühl von Kontrolle auswirkt.","kurz":"Warum jemand glaubt, und ob der Glaube ihm gibt, was er sucht, sind zwei verschiedene Fragen. Dass es sich nach Kontrolle anfühlt, belegt keine Kontrolle; in Experimenten schwächte schon das Lesen solcher Erzählungen das Kontrollgefühl.","prueffrage":"Wie ließe sich beobachten, ob sich sein Kontrollgefühl im Alltag tatsächlich verändert hat, seit er sich damit beschäftigt?","rueckmeldung":[{"option":1,"text":"Dass sich dein Freund sicherer fühlt, glaubt man ihm gern. Mit „durchweg“ und „gesichert“ geht die Aussage aber zu weit: Ein Beleg für mehr Kontrolle fehlt, und in Experimenten schwächte schon das Lesen solcher Erzählungen das Kontrollgefühl."},{"option":2,"text":"Der Hinweis auf Rückzug und fehlende Gemeinschaft wirkt wie eine ausgewogene Einschränkung. Doch schon die Annahme, Sinn und Kontrolle würden meist erfüllt, ist unbelegt: Das Kontrollgefühl sank in Experimenten schon beim Lesen solcher Erzählungen."},{"option":3,"text":"Vorsicht ist angebracht, denn dass der Glaube das Bedürfnis erfüllt, ist nicht belegt. „Nie untersucht“ stimmt aber nicht: Es gibt Experimente zu dieser Frage, und sie sprechen eher gegen einen Gewinn an Kontrolle."}],"familie":"wohlwollend-verstehen","fertigkeit":"F3","quellen":[{"typ":"doi","kurz":"Douglas, K. M.; Sutton, R. M.; Cichocka, A. (2017): „The Psychology of Conspiracy Theories“, Current Directions in Psychological Science 26(6)","oeffentlich":true,"doi":"10.1177/0963721417718261","abruf":"2026-10-12"}],"thema":"Psychologie"},{"id":"qx-f-016","clusterId":"F","werkstueckRef":"F.1.3","stufe":4,"question":"Welcher der beiden Beiträge gibt mehr Grund zur Sorge, und warum?","scenario":"Zwei Beiträge kursieren im Netz. Der erste scherzt, die Stadt Bielefeld existiere gar nicht und sei eine Erfindung. Der zweite behauptet, eine bestimmte Bevölkerungsgruppe steuere insgeheim die Wirtschaft und sei an Krisen schuld. Beide Beiträge bekommen viele Likes. Eine Freundin sagt: „Sind doch beides Verschwörungsgeschichten, also gleich harmlos oder gleich schlimm.“","options":["Beide sind gleich zu bewerten, denn beide behaupten ein geheimes Werk Einzelner und lassen sich nicht widerlegen; der Inhalt spielt keine Rolle.","Der zweite Beitrag ist ernster, weil er mehr Zustimmung bekommt; entscheidend ist allein, wie viele Menschen daran glauben.","Der erste Beitrag ist ernster, weil er sich ausdrücklich als Tatsache ausgibt, während der zweite nur eine Meinung über Politik äußert.","Der zweite Beitrag ist ernster, weil er reale Menschen zum Feind erklärt und damit Ausgrenzung und Gewalt den Boden bereiten kann."],"correctIndex":3,"explanation":"Beide Beiträge haben die Form einer Verschwörungserzählung: ein verborgener Plan, bei dem Zufall keine Rolle spielt. Den entscheidenden Unterschied macht das Ziel. Ein Scherz über eine Stadt, die es angeblich nicht gibt, bleibt ein Gedankenspiel, das niemandem schadet. Wird dagegen eine reale Gruppe von Menschen zum geheimen Drahtzieher erklärt, entsteht ein Feindbild, und aus Feindbildern können Ausgrenzung, Hass und im schlimmsten Fall Gewalt entstehen. Historisch zeigt das der Vorwurf der Brunnenvergiftung, mit dem 1348 beim Herannahen der Pest jüdische Gemeinden ermordet wurden, oder die gefälschten „Protokolle der Weisen von Zion“, die dem modernen Antisemitismus als angeblicher Beweis dienten. Die Zahl der Anhänger oder die Frage, ob sich etwas widerlegen lässt, trennt die beiden Fälle nicht; entscheidend ist, wer als Feind benannt wird.","coreRule":"⚡ Gefährlich wird ein Mythos dort, wo er reale Menschen zum Feind erklärt.","beleg":"Werkstück F.1.3 (Der Kipppunkt; Anwendung & Relevanz: Historische Verschwörungsmythen)","status":"entwurf","kurz":"Beide Beiträge folgen dem Muster der Verschwörungserzählung, aber nur der zweite erklärt reale Menschen zum geheimen Drahtzieher. Daraus können Ausgrenzung und Gewalt entstehen; das gleiche Muster macht beide Beiträge noch nicht gleich gefährlich.","prueffrage":"Worin unterscheiden sich die beiden Beiträge bei den Likes, und worin bei dem, was sie behaupten?","rueckmeldung":[{"option":0,"text":"Die Form ist tatsächlich gleich: Hier wie dort wird ein verborgener Plan behauptet. Aber „der Inhalt spielt keine Rolle“ trägt nicht, denn das Ziel macht den Unterschied: Eine Stadt trifft kein Vorwurf, eine reale Gruppe von Menschen schon."},{"option":1,"text":"Viele Likes zeigen Reichweite, aber nicht, wie gefährlich eine Behauptung ist. Hier haben zudem beide Beiträge viele Likes, die Zustimmung trennt die Fälle also gar nicht; wichtiger ist, wen ein Beitrag zum Feind erklärt."},{"option":2,"text":"Der erste Beitrag ist ausdrücklich ein Scherz, der zweite dagegen keine bloße Meinung über Politik: Er gibt als Tatsache aus, eine reale Gruppe sei an Krisen schuld. Ernster macht ihn, dass er damit Menschen zum Feind erklärt."}],"familie":"wir-und-die-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"United States Holocaust Memorial Museum, Holocaust Encyclopedia: „Protocols of the Elders of Zion“","oeffentlich":true,"url":"https://encyclopedia.ushmm.org/content/en/article/protocols-of-the-elders-of-zion","abruf":"2026-10-12"},{"typ":"url","kurz":"Cohn, S. K. (2007): „The Black Death and the Burning of Jews“, Past and Present 196 (Einleitung bei Medievalists.net)","oeffentlich":true,"url":"https://www.medievalists.net/2011/01/the-black-death-and-the-burning-of-jews/","abruf":"2026-10-12"}],"thema":"Netz und Medien"},{"id":"qx-f-017","clusterId":"F","werkstueckRef":"F.1.3.1","stufe":1,"question":"Was ist ein sinnvoller erster Schritt?","options":["Die Argumentationsstruktur prüfen: Wird fehlender Beleg als Beleg gewertet, wird die Beweislast umgekehrt und lässt sich überhaupt etwas denken, das die Behauptung widerlegen würde?","Zunächst jede einzelne Behauptung des Videos gründlich nachrecherchieren, denn ohne vollständige Faktenkenntnis ist keine Einschätzung der Erzählung möglich.","Herausfinden, wie viele Menschen das Video geteilt haben, denn eine große Verbreitung spricht für die Glaubwürdigkeit der Erzählung.","Nach Lücken in der offiziellen Darstellung des Ereignisses suchen, denn jede ungeklärte Stelle macht die alternative Erzählung wahrscheinlicher."],"correctIndex":0,"explanation":"Ob eine Erzählung trägt, zeigt sich oft schon an ihrer Bauweise, noch bevor du ein einziges Detail geprüft hast. Hier gibt es mehrere Alarmzeichen: Das Fehlen von Beweisen wird selbst als Beweis gewertet (Argument aus Unwissenheit), die Beweislast wird umgedreht, und die Erzählung ist unfalsifizierbar, weil jeder Gegenbeweis zur Vertuschung erklärt wird. Eine Behauptung, die durch nichts widerlegt werden kann, ist keine robuste Hypothese, sondern eine uneinnehmbare Festung. Deshalb ist es klüger, zuerst die Struktur zu prüfen, statt endlos die „Fakten“ zu recherchieren. Beliebtheit und Lücken in der offiziellen Darstellung sind keine tragfähigen Belege für die Erzählung.","coreRule":"⚡ Erst die Struktur prüfen, dann die Details: Wird fehlender Beweis als Beweis gewertet, die Beweislast umgekehrt und jeder Gegenbeweis eingemeindet, ist Vorsicht angebracht.","beleg":"Werkstück F.1.3.1 (Kernidee; Die 7 Warnsignale, Nr. 2–4; Werkbank-Frage)","status":"entwurf","scenario":"Eine Freundin schickt dir ein Video über ein Unglück. Es erklärt das chaotische Ereignis zum Werk einer kleinen, mächtigen Gruppe, verbindet viele Einzelheiten zu einer geraden Linie und spricht vor allem Angst und Wut an. Gegenargumente deutet es vorab als Teil der Vertuschung um, und es heißt: „Dass keine Beweise auftauchen, zeigt nur, wie perfekt sie alles vertuscht. Beweise du mir erst mal, dass es nicht stimmt.“ Du kannst die Einzelheiten nicht überprüfen.","kurz":"Schon die Bauweise verrät viel: Fehlende Beweise gelten als Beweis, die Beweislast ist umgedreht, und jeder Einwand wird zur Vertuschung erklärt. Eine so gebaute Behauptung lässt sich nie widerlegen und ist deshalb keine tragfähige Hypothese.","prueffrage":"Wie viele einzelne Behauptungen enthält das Video, und welche davon könntest du heute selbst nachprüfen?","rueckmeldung":[{"option":1,"text":"Nachrecherchieren klingt gründlich, bringt hier aber wenig: Eine Erzählung, die jeden Gegenbeweis zur Vertuschung erklärt, lässt sich mit Fakten kaum erledigen. Ihre Bauweise lässt sich zudem prüfen, bevor alle Einzelheiten bekannt sind."},{"option":2,"text":"Viele Teilungen wirken wie ein Qualitätssiegel, zeigen aber nur, dass der Inhalt Aufmerksamkeit erregt, gerade durch Angst und Wut. Verbreitung sagt nichts darüber, ob die Erzählung stimmt."},{"option":3,"text":"Offene Stellen in der offiziellen Darstellung sind bei chaotischen Ereignissen normal, weil Aufklärung Zeit braucht. Aus einer Lücke folgt nicht, dass die Gegenerzählung stimmt; das wäre dieselbe Schlussweise, mit der das Video selbst arbeitet."}],"familie":"immunisierung-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Lewandowsky, S.; Cook, J. (2020): The Conspiracy Theory Handbook","oeffentlich":true,"url":"https://skepticalscience.com/docs/ConspiracyTheoryHandbook.pdf","seite":"Abschnitt CONSPIR","abruf":"2026-10-12"},{"typ":"url","kurz":"Dowden, B.: „Fallacies“, Internet Encyclopedia of Philosophy","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","seite":"Einträge „Appeal to Ignorance“, „Misplaced Burden of Proof“","abruf":"2026-10-12"}],"thema":"Netz und Medien"},{"id":"qx-f-018","clusterId":"F","werkstueckRef":"F.1.3.1","stufe":2,"question":"In einem Online-Video heißt es: „Wer das noch nicht durchschaut hat, schläft noch. Du gehörst zu den wenigen, die endlich aufgewacht sind und hinter die Kulissen blicken.“ Welche Wirkung hat diese Rahmung auf das Denken des Publikums?","options":["Sie schmeichelt den Zuschauern mit einem Überlegenheitsgefühl; wer sich zu den „Wissenden“ zählt, fühlt sich den „Schlafenden“ überlegen und ist für die Erzählung eingenommen.","Sie verlagert die Beweislast auf die Zuschauer; wer die Behauptung nicht widerlegen kann, muss sie vorläufig als wahr akzeptieren.","Sie benennt eine kleine, allmächtige Gruppe als Urheber des Geschehens; wer dagegen argumentiert, gilt als Teil dieser Gruppe.","Sie versetzt die Zuschauer in Angst und Wut; wer sich bedroht fühlt, hinterfragt die Behauptungen nicht mehr."],"correctIndex":0,"explanation":"Die Einteilung in „Erwachte“ und „Schlafschafe“ befriedigt das Bedürfnis nach Überlegenheit: Wer sich zu den Wissenden zählt, fühlt sich den anderen überlegen und wird für die Erzählung eingenommen. Die anderen Optionen beschreiben andere Warnsignale: Beweislastumkehr, Feindbild und Gefühlsappell kommen in Verschwörungserzählungen häufig vor, aber in diesem Satz geht es um etwas anderes, nämlich um das Selbstbild des Publikums.","coreRule":"⚡ Wo die Welt in Erwachte und Schlafende zerfällt, wirkt das Überlegenheitsgefühl als Bindemittel und ersetzt die Prüfung durch Zugehörigkeit.","beleg":"Werkstück F.1.3.1 (Die 7 Warnsignale, Punkt 7)","status":"entwurf","scenario":"","kurz":"Der Satz teilt das Publikum in „Wissende“ und „Schlafende“ und schmeichelt so dem Selbstbild: Wer sich überlegen fühlt, ist für die Erzählung eingenommen. Der naheliegende Fehler ist, nur auf den Inhalt zu achten und die Wirkung der Rahmung zu übersehen.","prueffrage":"Wen teilt der Satz in welche zwei Gruppen ein, und zu welcher soll sich das Publikum zählen?","rueckmeldung":[{"option":1,"text":"Beweislastumkehr ist ein verbreitetes Warnsignal. In diesem Satz wird aber niemand aufgefordert, etwas zu widerlegen; er arbeitet mit dem Selbstbild des Publikums, das sich zu den „Wissenden“ zählen soll."},{"option":2,"text":"Ein Feindbild aus einer kleinen, allmächtigen Gruppe kommt in solchen Erzählungen tatsächlich oft vor. Hier wird aber keine Gruppe als Urheber benannt und niemand als ihr Teil abgestempelt; der Satz zielt auf das Selbstbild der Zuschauer."},{"option":3,"text":"Angst und Wut sind häufige Mittel, um Zweifel auszuschalten. Dieser Satz droht aber nichts an, er schmeichelt: Er weckt Stolz, nicht Furcht. Die Wirkung kommt aus dem guten Gefühl, zu den Wenigen zu gehören."}],"familie":"wir-und-die-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Lewandowsky, S.; Cook, J. (2020): The Conspiracy Theory Handbook","oeffentlich":true,"url":"https://skepticalscience.com/docs/ConspiracyTheoryHandbook.pdf","seite":"Abschnitt CONSPIR, „Persecuted victim“","abruf":"2026-10-12"},{"typ":"doi","kurz":"Douglas, K. M.; Sutton, R. M.; Cichocka, A. (2017): „The Psychology of Conspiracy Theories“, Current Directions in Psychological Science 26(6)","oeffentlich":true,"doi":"10.1177/0963721417718261","abruf":"2026-10-12"}],"thema":"Netz und Medien"},{"id":"qx-f-019","clusterId":"F","werkstueckRef":"F.1.3.1","stufe":3,"question":"Wie antwortest du deinem Freund?","options":["Misstrauen kann nützlich sein, solange es sich durch Belege korrigieren lässt; problematisch wird es erst, wenn jeder Gegenbeweis als Teil der Verschwörung umgedeutet wird.","Misstrauen gegenüber Autoritäten ist an sich schon ein Warnsignal; wer Behörden vertraut, ist auf der sicheren Seite und muss nichts mehr prüfen.","Misstrauen ist nur dann nützlich, wenn es sich gegen Medien richtet; Kritik an Behörden oder Wissenschaft gilt dagegen immer als bedenklich.","Jede Kritik an Institutionen führt unweigerlich in einen geschlossenen Denkkreis; deshalb ist es sicherer, grundsätzlich auf Misstrauen zu verzichten."],"correctIndex":0,"explanation":"Entscheidend ist nicht, ob jemand misstraut, sondern was aus dem Misstrauen wird. Ein gesundes Misstrauen gegenüber Autoritäten ist nützlich. Der Kipppunkt ist erreicht, wenn es zu einem geschlossenen Weltbild wird, das keinen Gegenbeweis mehr zulässt: Jeder Widerspruch gilt dann als Teil der Verschwörung. Ein zweites Kriterium kommt hinzu: wenn der Glaube an die Verschwörung wichtiger wird als persönliche Beziehungen und die eigene Sicherheit. Die Antwort „Misstrauen ist per se verdächtig“ verwechselt das Merkmal mit dem Muster und verlangt blindes Vertrauen statt Prüfung.","coreRule":"⚡ Misstrauen darf prüfen; es darf nur nicht jeden Gegenbeweis ausschließen.","beleg":"Werkstück F.1.3.1 (Der Kipppunkt)","status":"entwurf","scenario":"Ein Freund sagt: „Wer Behörden und Institutionen misstraut, steckt doch schon halb im Kaninchenbau. Misstrauen gegenüber Autoritäten ist an sich verdächtig.“ Du kennst Fälle, in denen Skepsis gegenüber Behörden berechtigt war, weil sich Angaben später als falsch herausstellten.","kurz":"Entscheidend ist, was aus dem Misstrauen wird: Es bleibt nützlich, solange Belege es korrigieren können. Der Denkfehler ist, schon das Misstrauen selbst zu verdächtigen, statt auf das Muster zu achten, dass kein Gegenbeweis mehr zählt.","prueffrage":"Wie hätte man in den Fällen, in denen Behördenangaben falsch waren, ohne Misstrauen davon erfahren?","rueckmeldung":[{"option":1,"text":"Dass Misstrauen kippen kann, stimmt. Verdächtig ist aber nicht das Misstrauen selbst, sondern erst ein Muster, in dem kein Gegenbeweis mehr zählt. Und wer nur vertraut, ersetzt Prüfung durch Hoffnung, wie die später widerlegten Angaben zeigen."},{"option":2,"text":"Auch Medien dürfen kritisch geprüft werden, doch eine Trennlinie nach Adressat trägt nicht: Berechtigte Skepsis gab es gerade gegenüber Behörden. Ob Misstrauen gesund ist, hängt davon ab, ob Belege es korrigieren können, nicht davon, wem es gilt."},{"option":3,"text":"Ein geschlossener Denkkreis ist eine echte Gefahr, aber kein unvermeidliches Ziel jeder Kritik. Gesundes Misstrauen bleibt für Belege offen. Wer ganz darauf verzichtet, ist nicht sicherer, sondern vertraut blind, wo Prüfung nötig wäre."}],"familie":"immunisierung-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Lewandowsky, S.; Cook, J. (2020): The Conspiracy Theory Handbook","oeffentlich":true,"url":"https://skepticalscience.com/docs/ConspiracyTheoryHandbook.pdf","seite":"Kasten „Conventional vs. Conspiratorial Thinking“; Abschnitt CONSPIR","abruf":"2026-10-12"}],"thema":"Zusammenleben"},{"id":"qx-f-020","clusterId":"F","werkstueckRef":"F.1.3.1","stufe":4,"question":"Welche Antwort wird der Lage am besten gerecht?","scenario":"Ein Bekannter erzählt dir, seine Schwägerin sei „komplett paranoid“, nur weil sie eine bekannte Online-Verschwörungserzählung glaubt. Du hast die Erzählung mit einer Liste typischer Warnsignale geprüft (allmächtiger Feind, Beweislastumkehr, Unfalsifizierbarkeit und weitere) und festgestellt, dass sie mehrere davon erfüllt.","options":["Die Erzählung erfüllt mehrere Warnsignale, aber das ist ein Befund über die Erzählung und ihren Denkstil, nicht über den seelischen Gesundheitszustand der Schwägerin.","Wer an eine Erzählung mit vielen Warnsignalen glaubt, ist damit nachweislich wahnhaft, denn mehr Warnsignale bedeuten eine schwerere Störung.","Wer eine Erzählung mit vielen Warnsignalen glaubt, hat im Grunde dasselbe Problem wie ein Mensch mit Wahn; man sollte das Wort nur nicht laut aussprechen.","Über die Struktur einer Erzählung darf kein Laie urteilen; ohne Fachausbildung sollte man jede Einschätzung der Argumentation unterlassen."],"correctIndex":0,"explanation":"Die Warnsignale (allmächtiger Feind, Beweislastumkehr, Unfalsifizierbarkeit und ähnliche) beschreiben Eigenschaften einer Erzählung: Wie ist sie gebaut, und lässt sie sich überhaupt prüfen? Daraus folgt nichts über den Gesundheitszustand eines Menschen, der sie glaubt. Auch die Fachwelt trennt hier: Psychiater müssen Überzeugungen aus Verschwörungserzählungen erst von Wahn und wahnähnlichen Überzeugungen unterscheiden (Holoyda 2022, Journal of the American Academy of Psychiatry and the Law); meist ist Verschwörungsglaube ein Denkstil und kein Wahn, und ob im Einzelfall mehr dahintersteckt, kann nur eine fachliche Untersuchung klären. Die Struktur einer Erzählung zu prüfen, kann dagegen jeder, denn dafür braucht es Logik, keine Ausbildung. Wer aus „glaubt eine unbelegbare Geschichte“ auf „ist krank“ schließt, springt von einer Eigenschaft der Erzählung auf eine Eigenschaft der Person und etikettiert, statt zu prüfen.","coreRule":"⚡ Wir sezieren die Erzählung und ihren Denkstil, wir stellen keine Diagnosen über Menschen.","beleg":"Werkstück F.1.3.1 (Der Kipppunkt); Fn. gl-f-wahn (Holoyda 2022, JAAPL 50(1), S. 124--135)","status":"entwurf","kurz":"Die Warnsignale beschreiben, wie die Erzählung gebaut ist und ob sie sich prüfen lässt. Von dieser Eigenschaft der Erzählung auf die Gesundheit eines Menschen zu schließen, ist ein Sprung: Verschwörungsglaube ist meist ein Denkstil, keine Diagnose.","prueffrage":"Was weißt du über die Schwägerin außer der Tatsache, dass sie diese Erzählung glaubt?","rueckmeldung":[{"option":1,"text":"Eine Zählung der Warnsignale wirkt wie ein Messwert, doch sie beschreibt nur, wie die Geschichte gebaut ist. Eine Skala für die Schwere einer Störung ergibt sie nicht, und „nachweislich wahnhaft“ wäre eine Diagnose ohne Grundlage."},{"option":2,"text":"Mit Wörtern wie „Wahn“ vorsichtig zu sein, ist richtig, doch hier wird das Etikett nur verschwiegen, nicht aufgegeben. Verschwörungsglaube ist meist ein Denkstil; Fachleute müssen ihn erst von Wahn unterscheiden, statt beides gleichzusetzen."},{"option":3,"text":"Diagnosen gehören tatsächlich nicht in Laienhand. Die Argumentation einer Erzählung zu prüfen, ist aber etwas anderes und erfordert Logik, keine Fachausbildung; auf jede Einschätzung zu verzichten, geht deshalb zu weit."}],"familie":"immunisierung-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Holoyda, B. J. (2022): „The QAnon Conspiracy Theory and the Assessment of Its Believers“, Journal of the American Academy of Psychiatry and the Law 50(1)","oeffentlich":true,"url":"https://jaapl.org/content/50/1/124","abruf":"2026-10-12"}],"thema":"Zusammenleben"},{"id":"qx-f-021","clusterId":"F","werkstueckRef":"F.1.4","stufe":1,"question":"Ein Freund nennt eine Gruppe einen Kult, weil sie an Engel glaubt. Woran würdest du stattdessen prüfen, ob die Gruppe ihre Mitglieder manipulativ kontrolliert?","options":["Daran, wie die Gruppe mit ihren Mitgliedern umgeht: ob sie deren Kontakte, Informationen, Denken und Gefühle steuert.","Daran, ob die Glaubenslehre der Gruppe belegbar ist, denn unbelegbare Lehren sind ein sicheres Kennzeichen eines Kults.","Daran, wie groß die Gruppe ist, denn kleine Gruppen mit starker Bindung sind besonders anfällig für Kontrolle.","Daran, wie ungewöhnlich die Rituale der Gruppe wirken, denn Seltsamkeit zeigt den Grad der Kontrolle."],"correctIndex":0,"explanation":"Ob eine Gruppe ihre Mitglieder manipulativ kontrolliert, zeigt sich nicht an dem, was sie glaubt, sondern an dem, was sie mit ihren Mitgliedern macht. Geprüft werden Struktur und Verhalten: Wird bestimmt, mit wem man Umgang haben darf? Werden kritische Informationen abgeschnitten? Wird Zweifel bestraft? Werden Angst und Schuld als Druckmittel eingesetzt? Der Glaube an Engel sagt darüber nichts, denn auch viele unbedenkliche Gemeinschaften glauben Dinge, die sich nicht belegen lassen. Dasselbe gilt für Größe und Ungewöhnlichkeit der Rituale: Sie sind Äußerlichkeiten, die weder Kontrolle beweisen noch ausschließen. Und selbst wenn einzelne Merkmale zutreffen, ist nicht jede enge Gemeinschaft ein Kult: Je mehr Kontrollmerkmale in hoher Intensität zusammenkommen, desto eher ist der Einfluss manipulativ.","coreRule":"⚡ Nicht was eine Gruppe glaubt, sondern wie sie ihre Mitglieder kontrolliert, entscheidet über den Kultverdacht.","beleg":"Werkstück F.1.4 (Kontext & Tiefe: Das BITE-Modell der Gedankenkontrolle)","status":"entwurf","scenario":"Im Gespräch fällt der Satz: „Die glauben an Engel, das ist doch ein Kult!“ Über das Verhalten der Gruppe gegenüber ihren Mitgliedern weißt du noch nichts.","quote":"","quoteLabel":"","kurz":"Ob eine Gruppe manipuliert, zeigt sich daran, was sie mit ihren Mitgliedern tut, etwa bei Kontakten, Informationen und Druck. Der Fehler: aus einem seltsam wirkenden Glauben auf Kontrolle zu schließen, obwohl er darüber nichts sagt.","prueffrage":"Welche anderen, als harmlos geltenden Gemeinschaften glauben ebenfalls an Engel?","rueckmeldung":[{"option":1,"text":"Dass sich die Lehre nicht belegen lässt, stimmt vermutlich. Das trifft aber auch auf viele unbedenkliche Gemeinschaften zu und sagt daher nichts über Kontrolle. Entscheidend ist, wie die Gruppe ihre Mitglieder behandelt, nicht was sie glaubt."},{"option":2,"text":"Enge Bindung kann Kontrolle erleichtern, doch die Größe selbst beweist sie nicht. Auch kleine Gemeinschaften sind oft harmlos, große können Druck ausüben. Größe bleibt eine Äußerlichkeit und zeigt nicht, wie mit Mitgliedern umgegangen wird."},{"option":3,"text":"Seltsame Rituale fallen auf und wirken schnell verdächtig. Wie ungewöhnlich etwas aussieht, sagt aber nichts über den Umgang mit Mitgliedern: Harmlose Gruppen können fremd wirken, kontrollierende unauffällig."}],"familie":"kontrolle-statt-bekenntnis","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Freedom of Mind Resource Center (S. Hassan): „Undoing Undue Influence and the BITE Model of Authoritarian Control“ (Handout)","oeffentlich":true,"url":"https://freedomofmind.com/wp-content/uploads/2024/04/BITE-Model-of-Authoritarian-Control-Handout.pdf","abruf":"2026-10-12"},{"typ":"url","kurz":"Deutscher Bundestag (1998): Endbericht der Enquete-Kommission „Sogenannte Sekten und Psychogruppen“, Drucksache 13/10950","oeffentlich":true,"url":"https://dserver.bundestag.de/btd/13/109/1310950.pdf","abruf":"2026-10-12"}],"thema":"Zusammenleben"},{"id":"qx-f-022","clusterId":"F","werkstueckRef":"F.1.4","stufe":2,"question":"Was ist an diesem Verhalten der Gruppe das eigentlich Auffällige und Prüfenswerte?","scenario":"Du gehst zu einem Vertriebsevent, weil dich eine Bekannte eingeladen hat. Dort wirst du mit Aufmerksamkeit und Lob überschüttet. Ein paar Wochen später heißt es, deine skeptischen Freunde „gönnen dir deinen Erfolg nicht“, und du solltest den Kontakt zu ihnen herunterfahren.","options":["Die Gruppe bindet dich zuerst mit viel Zuwendung und wertet dann kritische Außenstehende ab, sodass du von deren Einwänden abgeschnitten wirst.","Die Gruppe nimmt dich ernst und möchte dir mit ihrem Rat helfen, dein Umfeld auf deine neuen Ziele auszurichten.","Die Gruppe prüft, ob du wirklich zu ihr passt, und lässt deshalb nur Menschen mit derselben Haltung an dich heran.","Die Gruppe schützt dich vor Neid, der bei Erfolg ganz natürlich auftritt, und gibt dir einen guten Hinweis."],"correctIndex":0,"explanation":"Auffällig ist die Kombination aus „Love Bombing“ und der Isolation von kritischen Freunden: Erst gibt es überschwängliche Zuwendung, dann heißt es „Die gönnen dir deinen Erfolg nicht“. Genau dadurch fehlen dir die Menschen, die Einwände äußern würden. Das ist ein Kontrollmuster, kein Zufall: Wer Bindung durch Zuwendung aufbaut und zugleich Kritiker abwertet, macht dich von der Gruppe abhängig. Ob eine Gruppe dir guttut, erkennst du daran, ob sie dein unabhängiges Denken und deine Beziehungen stärkt oder ob sie verlangt, beides zurückzufahren. Das ist mehr als bloßer Rat oder Auswahl: Hier werden systematisch Außenkontakte abgewertet.","coreRule":"⚡ Überschwängliche Zuwendung plus Abkopplung von Kritikern ist ein Kontrollmuster, kein Zufall.","beleg":"Werkstück F.1.4 (Anwendung & Relevanz: Kommerzielle Kulte; BITE: Emotional Control)","status":"entwurf","kurz":"Auffällig ist, dass erst viel Zuwendung bindet und dann die Skeptiker als neidisch abgewertet werden. So fehlen dir genau die Stimmen, die Einwände äußern würden, und das kann dich von der Gruppe abhängig machen.","prueffrage":"Woher weiß die Gruppe, warum deine Freunde skeptisch sind, und hat sie je mit ihnen gesprochen?","rueckmeldung":[{"option":1,"text":"Ernst genommen zu werden fühlt sich gut an, und ein Rat kann nützlich sein. Dieser Rat verengt dein Umfeld aber: Er wertet gerade die Freunde ab, die kritisch nachfragen, statt dein Denken und deine Beziehungen zu stärken."},{"option":2,"text":"Gruppen wählen manchmal tatsächlich aus, wen sie nah an sich heranlassen. Hier geht es aber nicht um eine Prüfung deiner Eignung, sondern darum, dass Außenstehende systematisch schlechtgemacht und dir ferngehalten werden."},{"option":3,"text":"Neid kann bei Erfolg vorkommen, und manchmal trifft die Deutung zu. Hier wird sie aber pauschal gegen jede Skepsis eingesetzt, ohne dass es Hinweise auf Neid gibt, und sie dient dazu, dich von Kritikern zu trennen."}],"familie":"kontrolle-statt-bekenntnis","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Freedom of Mind Resource Center (S. Hassan): „Undoing Undue Influence and the BITE Model of Authoritarian Control“ (Handout)","oeffentlich":true,"url":"https://freedomofmind.com/wp-content/uploads/2024/04/BITE-Model-of-Authoritarian-Control-Handout.pdf","abruf":"2026-10-12"}],"thema":"Zusammenleben"},{"id":"qx-f-023","clusterId":"F","werkstueckRef":"F.1.4","stufe":3,"question":"Eine Behörde möchte eine Merkmalsliste, die ein früherer Sektenaussteiger und heutiger Berater entwickelt hat, als verbindliches Messinstrument verwenden, um Gruppen amtlich als manipulativ einzustufen. Die Liste fragt Kontrolle über Verhalten, Information, Gedanken und Gefühle ab. Als Beleg für ihre Zuverlässigkeit führt der Entwickler eine eigene Fragebogenstudie an, nach der die Punkte der Liste in sich stimmig sind. Was spricht am stärksten gegen diesen Plan?","options":["Die Liste wurde nur für religiöse Gruppen entworfen und lässt sich deshalb nicht auf andere Bereiche übertragen.","Eine nützliche Beratungs-Checkliste ist noch kein geprüftes Messinstrument, und eine Studie des Entwicklers ist keine unabhängige Prüfung.","Die Liste wurde von einem Fachgremium geprüft und als wissenschaftlich unhaltbar zurückgewiesen, daher ist sie wertlos.","Die vier Kontrollbereiche treten in der Praxis nie gemeinsam auf, deshalb erfasst die Liste so gut wie keine Gruppe."],"correctIndex":1,"explanation":"Wer ein Instrument selbst entwickelt und selbst prüft, kann Schwächen übersehen; dass die Punkte einer Liste in sich stimmig sind, zeigt nur, dass sie zusammenpassen, nicht dass sie das Gemeinte zuverlässig messen. Dafür braucht es eine unabhängige Prüfung. Hinzu kommt: Ein Teil der beschriebenen Kontrolle gehört unvermeidlich zu jeder Gemeinschaft (so die Enquete-Kommission des Bundestages 1998), entscheidend sind Intensität und Verlust der Selbstbestimmung; ein Ja bei einzelnen Punkten beweist deshalb noch keine Manipulation. Als Orientierungshilfe in der Beratung kann die Liste nützlich sein, als verbindliche amtliche Messlatte reicht sie nicht. Die anderen Antworten verfehlen den Kern: Die abgefragten Kontrollbereiche sind nicht an Religion gebunden, und ein Nie-gemeinsam-Auftreten der Bereiche oder eine eindeutige Widerlegung ist so nicht belegt.","coreRule":"⚡ Als Checkliste brauchbar, als Messlatte ungeeignet: Wer das eigene Instrument selbst prüft, liefert keine unabhängige Prüfung, und entscheidend sind Intensität und Verlust der Selbstbestimmung.","beleg":"Werkstück F.1.4 (Das BITE-Modell); Fn. gl-f-6; Fn. gl-f-enquete (Bundestag 1998, Drucksache 13/10950, S. 77)","status":"entwurf","scenario":"","kurz":"Wer ein Instrument selbst entwickelt und selbst prüft, kann Schwächen übersehen; stimmige Punkte zeigen nur, dass sie zusammenpassen, nicht dass sie das Gemeinte messen. Eine nützliche Beratungshilfe wird so noch keine amtliche Messlatte.","prueffrage":"Würden auch Sportvereine, Klöster oder Firmen bei einzelnen Punkten der Liste ein Ja bekommen, und was hieße das für eine amtliche Einstufung?","rueckmeldung":[{"option":0,"text":"Nach dem Anwendungsbereich zu fragen, ist bei jedem Instrument berechtigt. Kontrolle über Verhalten, Information, Gedanken und Gefühle ist aber nicht an Religion gebunden, und der Kern liegt anderswo: wer die Liste geprüft hat und wie."},{"option":2,"text":"Schwache Belege sind ein berechtigter Einwand. Von einem Gremium, das die Liste verworfen hätte, ist aber nichts bekannt, und „wertlos“ geht zu weit: In der Beratung kann sie nützen, als amtliche Messlatte reicht sie nicht."},{"option":3,"text":"Das trifft ein Problem von der falschen Seite: Ein Teil dieser Kontrolle gehört unvermeidlich zu jeder Gemeinschaft, die Liste fände also eher zu viel als zu wenig. Das eigentliche Problem ist die fehlende unabhängige Prüfung."}],"familie":"kontrolle-statt-bekenntnis","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Deutscher Bundestag (1998): Endbericht der Enquete-Kommission „Sogenannte Sekten und Psychogruppen“, Drucksache 13/10950","oeffentlich":true,"url":"https://dserver.bundestag.de/btd/13/109/1310950.pdf","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Hassan, S. A. (2020): The BITE Model of Authoritarian Control. Diss. Fielding Graduate University","oeffentlich":false}],"thema":"Zusammenleben"},{"id":"qx-f-024","clusterId":"F","werkstueckRef":"F.1.4","stufe":4,"question":"Eine Person bestimmt, mit wem ihr Partner Umgang hat, verwaltet dessen Geld allein und macht dessen Freunde schlecht. Eine Bekannte meint: „Kontrolle in dieser Form gibt es nur in Sekten, in einer Zweierbeziehung kann das gar nicht passieren.“ Welche Antwort trifft den Denkfehler am besten?","options":["Ob Kontrolle problematisch ist, hängt nicht von der Gruppengröße ab, sondern davon, ob Umgang, Geld und Information gezielt gelenkt werden, um den anderen abhängig zu machen.","Ob Kontrolle problematisch ist, hängt davon ab, ob eine Gruppe mit einem Anführer beteiligt ist, weil nur Gruppen systematisch Druck ausüben können.","Ob Kontrolle problematisch ist, hängt davon ab, ob der Kontrollierende Mitglied einer organisierten Bewegung ist, weil Kontrollmuster dort gelernt werden.","Ob Kontrolle problematisch ist, hängt davon ab, dass jede enge Beziehung als kleiner Kult gelten muss, weil Nähe immer Kontrolle einschließt."],"correctIndex":0,"explanation":"Die Bekannte schließt von der bekanntesten Form (Sekte) auf die einzige Form. Entscheidend ist aber die Struktur: Wer Kontakte einschränkt, finanzielle Abhängigkeit schafft und Freunde abwertet, isoliert den anderen und entzieht ihm andere Informations- und Rückhalt-Quellen. Das sind dieselben Kontrollmechanismen, die man bei manipulativen Gruppen beobachtet, nur im Format einer Zweierbeziehung. Dafür braucht es weder einen Anführer noch eine Gruppe. Umgekehrt ist nicht jede enge Beziehung ein Kult: Ein gewisses Maß an Einfluss gehört zu jeder Gemeinschaft, problematisch wird es erst bei systematischer Isolation, Abhängigkeit und Manipulation.","coreRule":"⚡ Prüfe die Struktur der Kontrolle (Umgang, Geld, Information, Gefühle), nicht die Größe oder das Etikett der Gruppe.","beleg":"Werkstück F.1.4 (Anwendung & Relevanz: Missbräuchliche Beziehungen)","status":"entwurf","scenario":"","kurz":"Entscheidend ist die Struktur, nicht die Größe: Wer Kontakte einschränkt, Geld allein verwaltet und Freunde abwertet, isoliert den anderen und macht ihn abhängig. Das geht auch zu zweit; die bekannteste Form (Sekte) ist nicht die einzige.","prueffrage":"Welcher der drei Schritte, die die Person unternimmt, wäre ohne eine Gruppe im Hintergrund nicht möglich?","rueckmeldung":[{"option":1,"text":"Gruppen mit Anführer sind das bekannteste Beispiel für Druck, deshalb wirkt das einleuchtend. Es wiederholt aber genau die Verengung der Bekannten: Isolation und Abhängigkeit funktionieren auch ohne Gruppe, schon zwischen zwei Menschen."},{"option":2,"text":"Dass Kontrollmuster irgendwo gelernt werden, ist denkbar. Eine organisierte Bewegung ist dafür aber keine Voraussetzung: Kontakte einschränken, Geld an sich ziehen und Freunde abwerten geht auch in einer Beziehung ganz ohne Organisation."},{"option":3,"text":"Hier kippt der Gedanke ins andere Extrem. Nicht jede enge Beziehung ist ein Kult, und ein gewisses Maß an Einfluss gehört zu jeder Gemeinschaft. Problematisch wird es erst bei systematischer Isolation, Abhängigkeit und Manipulation."}],"familie":"kontrolle-statt-bekenntnis","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Crown Prosecution Service: „Controlling or Coercive Behaviour in an Intimate or Family Relationship“ (Leitlinie, Stand 07.02.2025)","oeffentlich":true,"url":"https://www.cps.gov.uk/legal-guidance/controlling-or-coercive-behaviour-intimate-or-family-relationship","abruf":"2026-10-12"},{"typ":"url","kurz":"Freedom of Mind Resource Center (S. Hassan): „Undoing Undue Influence and the BITE Model of Authoritarian Control“ (Handout)","oeffentlich":true,"url":"https://freedomofmind.com/wp-content/uploads/2024/04/BITE-Model-of-Authoritarian-Control-Handout.pdf","abruf":"2026-10-12"}],"thema":"Zusammenleben"},{"id":"qx-f-025","clusterId":"F","werkstueckRef":"F.1.5","stufe":1,"question":"Welche Frage hilft dir am besten, bei einer beeindruckend aussehenden „Studie“ zu prüfen, ob sie echte Forschung ist oder nur deren äußere Form nachahmt?","options":["Wie viele Seiten der Bericht hat und wie professionell die Grafiken gestaltet sind","Wie viele Titel und Auszeichnungen die Autoren haben und wie bekannt das Institut ist","Ob der Bericht auch Ergebnisse nennt, die der Behauptung widersprechen, und ob andere Forscher sie wiederholen konnten","Wie neu und überraschend die Behauptung ist und wie stark sie von bisherigem Wissen abweicht"],"correctIndex":2,"explanation":"Jargon, Grafiken, Titel und Institutsnamen lassen sich leicht nachahmen, sie sagen nichts darüber, ob die Methode taugt. Entscheidend ist die selbstkritische Redlichkeit: Echte Forschung berichtet auch Belege, die der eigenen Theorie widersprechen, und sucht aktiv nach Wegen, sie zu widerlegen. Ob unabhängige Forscher das Ergebnis wiederholen können, zeigt, ob mehr dahintersteckt als eine schön gebaute Hülle. Der Physiker Richard Feynman nannte dieses Muster „Cargo-Kult-Wissenschaft“: Inselbewohner bauten nach dem Zweiten Weltkrieg Landebahnen, Feuer und Holz-Kopfhörer nach, um Flugzeuge zurückzulocken. Die Form stimmte, das Verständnis fehlte, und die Flugzeuge blieben aus.","coreRule":"⚡ Nicht das Aussehen, sondern die Redlichkeit macht Wissenschaft aus: Frag nach Gegenbelegen und Wiederholbarkeit, nicht nach Jargon und Titeln.","beleg":"Werkstück F.1.5 (Kernidee; Kontext & Tiefe); Fn. gl-f-7 (Feynman 1974, Caltech-Rede)","status":"entwurf","scenario":"Ein Institut, das du nicht kennst, veröffentlicht einen Bericht mit Fachjargon, vielen Grafiken und Titeln wie „Dr.“. Der Bericht stützt eine Behauptung, die dir zweifelhaft vorkommt.","kurz":"Echte Forschung zeigt sich daran, dass sie auch Widersprechendes berichtet und andere ihre Ergebnisse wiederholen können. Jargon, Grafiken und Titel lassen sich dagegen leicht nachahmen: Die Form kann stimmen, während die Substanz fehlt.","prueffrage":"Welche der Merkmale, die dich an dem Bericht beeindrucken, könnte auch jemand ohne echte Daten herstellen?","rueckmeldung":[{"option":0,"text":"Ein sorgfältig gestalteter, langer Bericht wirkt nach viel Arbeit. Aber Umfang und Grafiken lassen sich beliebig nachbauen und sagen nichts darüber, ob die Methode taugt oder ob widersprechende Befunde verschwiegen wurden."},{"option":1,"text":"Titel und ein bekannter Institutsname können ein erster Hinweis auf Seriosität sein. Sie lassen sich aber nachahmen oder vortäuschen und zeigen nicht, ob in diesem konkreten Bericht redlich gearbeitet wurde."},{"option":3,"text":"Bei einer überraschenden Behauptung ist Skepsis berechtigt, und sie verlangt starke Belege. Wie neu etwas ist, sagt aber nicht, ob eine Studie echte Forschung ist: Auch Unsinn klingt oft sensationell, und echte Forschung kann durchaus überraschen."}],"familie":"wissenschaft-abgrenzen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Feynman, R. P. (1974): „Cargo Cult Science“, Engineering and Science 37(7), Caltech-Scan","oeffentlich":true,"url":"https://calteches.library.caltech.edu/51/2/CargoCult.pdf","seite":"S. 11, 13","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft"},{"id":"qx-f-026","clusterId":"F","werkstueckRef":"F.1.5","stufe":2,"question":"Wie bewertest du das Vorgehen der Gruppe?","scenario":"Eine Forschungsgruppe testet Telepathie in 40 Versuchsreihen. Veröffentlicht werden die drei Reihen mit auffälligem Treffer, die übrigen 37 verschwinden in der Schublade. Ein Kollege sagt: „Drei klare Treffer sind doch ein Ergebnis. Es steht ja alles korrekt in der Veröffentlichung.“","options":["Als solide Forschung, denn drei auffällige Treffer sind ein Ergebnis, das für sich steht, und fehlgeschlagene Reihen müssen nicht veröffentlicht werden.","Als legitime Grenzforschung, denn jede Gruppe darf selbst entscheiden, welche Ergebnisse für die Fachwelt relevant sind.","Als Nachahmung von Forschung ohne ihren Kern, denn wer nur die Treffer zeigt und die 37 Fehlschläge verschweigt, täuscht ein Ergebnis vor, das die Gesamtlage nicht trägt.","Als unbedenklich, denn solange die Gruppe nicht behauptet, die Telepathie sei bewiesen, gibt es an der Veröffentlichung nichts zu beanstanden."],"correctIndex":2,"explanation":"Aussagekraft hat erst das Gesamtbild aller Versuche, nicht die herausgepickten Treffer. Wer nur die drei Treffer zeigt und die 37 Fehlschläge verschweigt, erzeugt den Eindruck eines Effekts, den die Daten insgesamt nicht hergeben. Redliche Forschung berichtet auch über alles, was der eigenen Hypothese widerspricht. Fachsprache, Versuchsaufbau und Veröffentlichung können dann perfekt aussehen, und trotzdem fehlt der Kern der Wissenschaft: die Bereitschaft, die eigene Idee scheitern zu sehen. Feynman nannte das Cargo-Kult-Wissenschaft: Die Landebahn steht, aber die Flugzeuge der Erkenntnis landen dort nicht. Dass die Gruppe Telepathie nicht ausdrücklich als bewiesen bezeichnet, ändert nichts: Die Pflicht, auch widersprechende Ergebnisse zu berichten, bleibt bestehen.","coreRule":"⚡ Wer Fehlschläge verschweigt, baut nur die Landebahn, aber keine Wissenschaft.","beleg":"Werkstück F.1.5 (Anwendung & Relevanz: In der Parapsychologie)","status":"entwurf","kurz":"Aussagekraft hat nur das Gesamtbild aller 40 Reihen. Wer nur die drei Treffer zeigt und 37 Fehlschläge verschweigt, erzeugt den Eindruck eines Effekts, den die Daten insgesamt nicht hergeben, auch wenn jede einzelne Angabe stimmt.","prueffrage":"Wie viele auffällige Treffer würde man bei 40 Versuchsreihen allein durch Zufall erwarten?","rueckmeldung":[{"option":0,"text":"Drei auffällige Treffer sind tatsächlich ein Ergebnis, aber eines ohne Bezugsgröße. Ob sie etwas bedeuten, zeigt sich erst im Vergleich mit den 37 Reihen ohne Treffer, und genau die gehören zur Berichtspflicht."},{"option":1,"text":"Die Freiheit, Forschungsfragen zu wählen, ist echt. Hier wird aber nicht über Relevanz entschieden, sondern nach dem Ausgang der Reihen aussortiert. Gerade das Ergebnis, das der eigenen Idee widerspricht, gehört in den Bericht."},{"option":3,"text":"Auch wenn die Gruppe Telepathie nicht ausdrücklich für bewiesen erklärt, ändert das wenig. Schon die Auswahl der Treffer erzeugt den Eindruck eines Effekts, und die Pflicht, Widersprechendes zu berichten, hängt nicht davon ab, was behauptet wird."}],"familie":"wissenschaft-abgrenzen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Feynman, R. P. (1974): „Cargo Cult Science“, Engineering and Science 37(7), Caltech-Scan","oeffentlich":true,"url":"https://calteches.library.caltech.edu/51/2/CargoCult.pdf","seite":"S. 11–12","abruf":"2026-10-12"},{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: „Science and Pseudo-Science“","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","seite":"Abschn. 5.1","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft"},{"id":"qx-f-027","clusterId":"F","werkstueckRef":"F.1.5","stufe":3,"question":"Dein Kollege sagt dazu: „Unseriöse Forschung gibt es nur bei Homöopathen und Parapsychologen. Was an einer Hochschule veröffentlicht wird, hat Institut, Fachjargon und Peer-Review, also ist es automatisch Wissenschaft.“ Was ist an diesem Schluss fehlerhaft?","options":["Er schließt von der äußeren Form auf die Qualität: Institut, Jargon und Veröffentlichung sagen nichts darüber, ob die Forschenden ihre eigenen Ideen ernsthaft scheitern lassen wollten.","Er schließt von einer Ausnahme auf die Regel: Weil einzelne Hochschulstudien fehlerhaft sind, müsste jede Hochschulforschung grundsätzlich unseriös sein.","Er schließt vom Ergebnis auf die Methode: Weil die Studie eine überraschende Behauptung aufstellt, muss sie zwangsläufig mit unsauberen Methoden entstanden sein.","Er schließt von der Quelle auf die Absicht: Weil Hochschulen Drittmittel einwerben, müssen ihre Studien zwangsläufig im Interesse der Geldgeber verfälscht sein."],"correctIndex":0,"explanation":"Der Kollege verwechselt die äußere Form der Wissenschaft mit ihrer Substanz. Ob Forschung trägt, entscheidet sich an der selbstkritischen Redlichkeit: Werden Gegenbelege gesucht und berichtet, gibt es Kontrollgruppen, ist das Ergebnis wiederholbar? Das gilt überall, auch an Hochschulen. Richard Feynman nannte in seiner Rede „Cargo Cult Science“ (1974) ausdrücklich auch Studien zu Lesemethoden und Rattenversuche der Psychologie, die die sorgfältigen Kontrollen eines vorbildlichen Vorgängers nicht beachteten, als Beispiele für Forschung, die nur die Form der Wissenschaft wahrt. Die drei anderen Schlüsse beschreiben Fehlschlüsse, die der Kollege gar nicht begeht: Er verallgemeinert nicht von einzelnen fehlerhaften Studien auf alle Hochschulforschung, er schließt nicht aus einer überraschenden Behauptung auf schlechte Methoden, und er spricht nicht über Geldgeber. Sein Fehler ist, die Form als Beweis der Substanz zu nehmen.","coreRule":"⚡ Ein Titel, ein Institut und Fachjargon beweisen keine Redlichkeit: Prüfe die Methode, nicht das Etikett.","beleg":"Werkstück F.1.5 (Kernidee); Fn. gl-f-7 (Quelle der Feynman-Rede „Cargo Cult Science“, 1974)","status":"entwurf","scenario":"Ihr sprecht über eine Schlagzeile zu einer neuen Studie, die an einer Universität entstanden ist.","kurz":"Institut, Fachjargon und Veröffentlichung sind nur die äußere Form von Wissenschaft. Ob eine Studie trägt, zeigt sich daran, ob die Forschenden Gegenbelege suchen und ihre eigene Idee wirklich scheitern lassen wollten.","prueffrage":"Ist schon einmal eine Hochschulstudie mit Peer-Review später zurückgezogen worden oder bei der Wiederholung gescheitert?","rueckmeldung":[{"option":1,"text":"Dass einzelne Hochschulstudien Mängel haben, stimmt. Der Kollege behauptet aber das Gegenteil: Hochschulforschung sei automatisch Wissenschaft. Sein Fehler ist keine Verallgemeinerung von Einzelfällen, sondern die Form als Beweis zu nehmen."},{"option":2,"text":"Eine überraschende Behauptung macht eine Studie nicht automatisch methodisch schlecht, und davon spricht der Kollege auch nicht. Er stützt sich auf äußere Merkmale wie Institut, Fachjargon und Peer-Review, nicht auf Ergebnis oder Methode."},{"option":3,"text":"Über Geldgeber und Drittmittel sagt der Kollege kein Wort, ihm geht es um Institut, Jargon und Veröffentlichung. Finanzierung kann Studien beeinflussen, eine Verfälschung folgt daraus aber nicht zwangsläufig."}],"familie":"wissenschaft-abgrenzen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Feynman, R. P. (1974): „Cargo Cult Science“, Engineering and Science 37(7), Caltech-Scan","oeffentlich":true,"url":"https://calteches.library.caltech.edu/51/2/CargoCult.pdf","seite":"S. 10, 13","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft"},{"id":"qx-f-028","clusterId":"F","werkstueckRef":"F.1.6","stufe":1,"question":"Ein Bekannter sagt: „Meine Schwester ist Ärztin und gewohnt, Behauptungen kritisch zu prüfen. Seit dem Tod ihres Mannes schwört sie auf einen Heiler, der angeblich Kontakt zu Verstorbenen herstellt. Ausgerechnet sie fällt auf so etwas nie herein, da muss etwas dran sein.“ Welcher Schluss ist am besten begründet?","options":["Gerade weil sie so geübt im Prüfen ist, spricht ihre Überzeugung stark dafür, dass der Heiler wirklich etwas kann.","Ihre Überzeugung beweist wenig, denn auch geübte Skeptiker prüfen Behauptungen nicht mehr, die ein tiefes Bedürfnis berühren.","Sie hat ihre Ausbildung offenbar nie wirklich verstanden, denn wer kritisch denken kann, lässt sich in der Trauer nicht täuschen.","Ihr Fall ist ein seltener Sonderfall, der nichts darüber verrät, wie Trauer das Urteil anderer klarer Denker beeinflusst."],"correctIndex":1,"explanation":"Intelligenz oder Fachkompetenz belegen nicht, dass eine Überzeugung stimmt. Das zeigt der Fall des Schriftstellers Arthur Conan Doyle: Der Schöpfer des kühlen Logikers Sherlock Holmes hielt nach den Verlusten im Ersten Weltkrieg die inszenierten „Cottingley Fairies“-Fotos trotz ihrer Fälschung für Zeugnisse einer unsichtbaren Lebensform, öffentlich vorsichtig als starken ersten Anschein, privat als erwiesen. Kritisches Denken ist keine feste Eigenschaft, sondern eine Praxis, die bewusst angewendet werden muss. Ein überwältigendes Bedürfnis nach Trost oder Hoffnung kann sie ausgerechnet bei der eigenen Überzeugung abschalten, und dann dient der Verstand als Anwalt für den Glauben statt als Prüfer. Der Verweis auf ihre Kompetenz hilft also nicht weiter; entscheidend ist, ob die Behauptung selbst einer Prüfung standhält. Dass ihre Ausbildung wertlos sei, folgt ebenso wenig, denn niemand ist durch Intelligenz oder Skepsis dauerhaft immun. Und ein seltener Sonderfall ist das auch nicht: Das Muster ist erklärbar und tritt auf, sobald eine Behauptung ein tiefes persönliches Bedürfnis berührt.","coreRule":"⚡ Skepsis ist eine Praxis, keine Eigenschaft: Sie muss gerade dort angewendet werden, wo es weh tut.","beleg":"Werkstück F.1.6 (Kernidee; Anwendung & Relevanz)","status":"entwurf","scenario":"Ein Bekannter erzählt dir von seiner Schwester, einer erfahrenen Ärztin. Sie ist es gewohnt, Behauptungen kritisch zu prüfen, glaubt aber seit dem Tod ihres Mannes fest an einen Heiler, der angeblich Kontakt zu Verstorbenen herstellt.","quote":"","quoteLabel":"","kurz":"Fachkompetenz belegt nicht, dass eine Überzeugung stimmt: Auch geübte Skeptiker können aufhören zu prüfen, wenn eine Behauptung ein tiefes Bedürfnis nach Trost berührt. Entscheidend ist, ob die Behauptung selbst einer Prüfung standhält.","prueffrage":"Welche Belege für die Fähigkeiten des Heilers gibt es außer der Überzeugung der Ärztin selbst?","rueckmeldung":[{"option":0,"text":"Ihre Erfahrung im Prüfen macht ihr Urteil verlockend gewichtig. Doch auch die feste Überzeugung einer Fachfrau belegt noch nicht, dass die Behauptung stimmt; gerade ein Herzensanliegen kann die Prüfung ausschalten."},{"option":2,"text":"Dass ihr Urteil hier nicht trägt, stimmt wahrscheinlich. Daraus folgt aber nicht, dass ihre Ausbildung wertlos wäre: Kritisches Denken ist eine Praxis, und niemand ist durch Intelligenz oder Skepsis dauerhaft gegen Täuschung gefeit."},{"option":3,"text":"Ein außergewöhnlicher Fall wirkt so, als läge die Erklärung nur bei ihr. Das Muster ist aber nicht selten: Es tritt immer wieder auf, wenn eine Behauptung ein tiefes persönliches Bedürfnis berührt, auch bei anderen klaren Denkern."}],"familie":"werkzeuge-gegen-sich-selbst","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Doyle, A. C. (1922): The Coming of the Fairies, Kap. II (Strand-Artikel: „strong prima facie case“) und Kap. IV (Brief an Gardner: „You and I needed no confirmation“) (Project Gutenberg Nr. 47506)","oeffentlich":true,"url":"https://www.gutenberg.org/files/47506/47506-0.txt","abruf":"2026-10-12"},{"typ":"url","kurz":"University of Leeds Library, Special Collections: Katalogeintrag Cottingley Fairies","oeffentlich":true,"url":"https://explore.library.leeds.ac.uk/special-collections-explore/8705","abruf":"2026-10-12"},{"typ":"url","kurz":"Internet Encyclopedia of Philosophy: Fallacies, Art. „Appeal to Authority“","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Psychologie"},{"id":"qx-f-029","clusterId":"F","werkstueckRef":"F.1.6","stufe":2,"question":"Was zeigt dieser Unterschied am ehesten?","options":["Er zweifelt privat stärker als öffentlich und fürchtet insgeheim, dass die Belege gefälscht sind.","Er ist sich öffentlich wie privat gleich sicher und nennt die Belege überall den endgültigen Beweis.","Er hat die Überzeugung längst gefasst und gibt sich nach außen nur vorsichtig, statt die Belege ergebnisoffen zu prüfen.","Er hat die Belege inzwischen gründlich widerlegt und gibt sich nach außen nur aus Höflichkeit vorsichtig."],"correctIndex":2,"explanation":"Die vorsichtige öffentliche Formulierung und die private Gewissheit passen nicht zusammen. Das spricht dafür, dass die Überzeugung innerlich schon feststeht und die Vorsicht nach außen eher Zurückhaltung oder Taktik ist. Die Belege werden dann eher verteidigt als ergebnisoffen geprüft. Hohe Intelligenz schützt davor nicht: Sie liefert dann bloß bessere Argumente für das, was man ohnehin glauben will. Gerade bei Behauptungen, die ein tiefes persönliches Bedürfnis berühren, lohnt es sich daher, genau auf diese Diskrepanz zu achten. Ein Beispiel ist Arthur Conan Doyle, der Schöpfer von Sherlock Holmes: Öffentlich sprach er von einem „starken ersten Anschein“ der Cottingley-Feenfotos (Strand-Artikel vom Dezember 1920), im Brief an seinen Mitstreiter E. L. Gardner vom Oktober 1920 hielt er die Sache dagegen für erwiesen.","coreRule":"⚡ Wer privat schon überzeugt ist, prüft öffentlich nur noch pro forma: Der Wunsch regiert.","beleg":"Werkstück F.1.6 (Der Riss in der Festung); Fn. gl-f-doyle (Doyle 1922, Kap. I, II und IV)","status":"entwurf","scenario":"Ein sehr kluger, öffentlich bekannter Mann verteidigt eine Behauptung, die ihm seit einem schweren Verlust sehr wichtig ist. Der Verlust liegt kurz zurück, die Behauptung verspricht ihm Trost, und die Belege sind dünn. Öffentlich schreibt er, die Belege sprächen für einen „starken ersten Anschein“, mehr nicht; in einem privaten Brief an einen Gleichgesinnten nennt er die Sache längst erwiesen.","kurz":"Wer öffentlich nur von einem „starken ersten Anschein“ spricht, privat aber von „längst erwiesen“, hat sich vermutlich schon festgelegt. Die Vorsicht nach außen ist dann eher Zurückhaltung oder Taktik, und die Belege werden verteidigt statt ergebnisoffen geprüft.","prueffrage":"Wie stark sind die Belege, und welche der beiden Äußerungen geht über das hinaus, was sie hergeben?","rueckmeldung":[{"option":0,"text":"Der Unterschied springt ins Auge, und man liest ihn schnell als verborgenen Zweifel. Der Brief nennt die Sache aber „längst erwiesen“: Das zeigt private Gewissheit, nicht Unsicherheit, und von gefälschten Belegen ist nirgends die Rede."},{"option":1,"text":"Privat ist er tatsächlich sehr sicher. Öffentlich spricht er aber nur von einem „starken ersten Anschein“, mehr nicht. Die beiden Aussagen sind gerade nicht gleich, und genau dieser Unterschied ist das Auffällige."},{"option":3,"text":"Höfliche Zurückhaltung wäre eine freundliche Lesart. Wer die Belege aber widerlegt hätte, würde die Sache privat nicht „längst erwiesen“ nennen. Von einer Widerlegung ist nirgends die Rede, die Belege sind nur dünn."}],"familie":"werkzeuge-gegen-sich-selbst","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Doyle, A. C. (1922): The Coming of the Fairies, Kap. II und IV (Project Gutenberg Nr. 47506)","oeffentlich":true,"url":"https://www.gutenberg.org/files/47506/47506-0.txt","abruf":"2026-10-12"},{"typ":"url","kurz":"Kahan, D. M. u. a. (2013): Motivated Numeracy and Enlightened Self-Government (Working Paper)","oeffentlich":true,"url":"https://scholarsbank.uoregon.edu/items/e034d504-ed17-4e0c-a713-ac3f85a8187a/full","abruf":"2026-10-12"}],"thema":"Psychologie"},{"id":"qx-f-030","clusterId":"F","werkstueckRef":"F.1.6","stufe":3,"question":"Was ändert sich am Wechsel vom Freundeskreis zur Kolumne am stärksten?","options":["Sie setzt ihren guten Ruf ein, um eine unbewiesene Behauptung zu verbreiten, sodass andere ihr vertrauen, ohne selbst zu prüfen.","Sie sucht überhaupt Trost in einem Glauben, den sie nicht belegen kann, obwohl sie es besser wissen müsste.","Sie hält ihre Überzeugung für gewiss, obwohl sie sich nur schwer in Worte fassen und begründen lässt.","Sie verteidigt ihre Überzeugung gegenüber Zweiflern im Freundeskreis eifriger, als es ihrer Sachlage entspricht."],"correctIndex":0,"explanation":"Ein privater Glaube, der Trost spendet, betrifft vor allem die Person selbst. Problematisch wird es, wenn Ansehen und Reichweite eingesetzt werden, um eine ungeprüfte Behauptung zu verbreiten: Andere vertrauen ihr womöglich, weil der Name der Person dem Unsinn den „Stempel der Genialität“ verleiht, statt selbst zu prüfen (Appell an die falsche Autorität). Genau das tat Arthur Conan Doyle, als er die Cottingley-Feen-Fotos mit seinem Ruf als Denker adelte; sie waren, wie die Mädchen später zugaben, mit Papierfiguren und Nadeln inszeniert. Dass jemand Trost sucht, ist menschlich; zur Gefahr wird es, wenn das Vertrauen in einen Namen an die Stelle der Prüfung tritt und andere in die Irre führt.","coreRule":"⚡ Privater Trost ist Privatsache; zur Gefahr wird er, wenn berühmte Autorität ihn in die Öffentlichkeit trägt und andere das Prüfen ersetzen lässt.","beleg":"Werkstück F.1.6 (Der Kipppunkt)","status":"entwurf","scenario":"Eine für ihren scharfen Verstand berühmte Wissenschaftsjournalistin hat ihren Bruder verloren. Seitdem ist sie überzeugt, dass sich Verstorbene über ein bestimmtes Gerät melden, und ist dafür bisher keiner Prüfung begegnet, die sie nicht mit immer neuen Ausreden entkräftet hätte. Zunächst erzählt sie nur Freunden davon. Dann beginnt sie, das Gerät in einer reichweitenstarken Kolumne als gut belegt zu empfehlen.","kurz":"Im Freundeskreis betrifft ihr Glaube vor allem sie selbst. In der Kolumne leiht ihr guter Ruf der unbewiesenen Behauptung Gewicht, und Leser vertrauen womöglich dem Namen, statt selbst zu prüfen: ein Appell an die falsche Autorität.","prueffrage":"Was an ihrer Überzeugung und an ihrem Umgang mit Prüfungen ist vor und nach dem Wechsel gleich geblieben?","rueckmeldung":[{"option":1,"text":"Dass sie Trost sucht, wirkt wie der Kern des Problems, ist aber menschlich und betrifft vor allem sie selbst. Das war schon im Freundeskreis so; neu ist erst, dass andere durch ihre Reichweite beeinflusst werden."},{"option":2,"text":"Davon, dass sie ihre Überzeugung nicht in Worte fassen kann, ist keine Rede; eine Kolumne darüber schreibt sie ja. Gewiss war sie sich auch schon vorher; was sich ändert, ist die Wirkung auf andere."},{"option":3,"text":"Von eifrigem Verteidigen gegen Zweifler im Freundeskreis ist keine Rede, dort erzählt sie nur davon. Ihr Umgang mit Prüfungen bleibt gleich; neu ist, dass ihr Name vielen Lesern als Gütesiegel dient."}],"familie":"ergaenzen-oder-ersetzen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Internet Encyclopedia of Philosophy: Fallacies, Art. „Appeal to Authority“","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"url","kurz":"University of Leeds Library, Special Collections: Katalogeintrag Cottingley Fairies (Veröffentlichung im Strand Magazine 1920/1921, Papierfiguren mit Hutnadeln, Geständnis 1983)","oeffentlich":true,"url":"https://explore.library.leeds.ac.uk/special-collections-explore/8705","abruf":"2026-10-12"},{"typ":"url","kurz":"Doyle, A. C. (1922): The Coming of the Fairies (Project Gutenberg Nr. 47506)","oeffentlich":true,"url":"https://www.gutenberg.org/files/47506/47506-0.txt","abruf":"2026-10-12"}],"thema":"Psychologie"},{"id":"qx-f-031","clusterId":"F","werkstueckRef":"F.1.6","stufe":4,"question":"Wie gehst du mit ihr am sinnvollsten um?","scenario":"Eine kluge Bekannte vertraut seit dem Tod ihres Mannes den Botschaften eines Mediums. Wenn du Widersprüche ansprichst, findet sie jedes Mal eine neue, geschickte Begründung, warum die Botschaften trotzdem stimmen. Du möchtest ihr helfen und dabei nicht überheblich wirken.","options":["Ihre Klugheit als Hinweis werten, dass am Medium etwas dran sein muss, denn kluge Menschen irren sich in solchen Dingen selten.","Ihren Glauben auf mangelnde Intelligenz zurückführen und ihr das offen sagen, denn so etwas lässt sich nur durch Dummheit erklären.","Nach dem Bedürfnis fragen, das der Glaube für sie erfüllt, denn Intelligenz schützt nicht vor Selbsttäuschung, wenn ein Wunsch im Spiel ist.","Das Thema künftig meiden und keine Prüfung mehr ansprechen, denn Trauer macht Kritik an einer Überzeugung in aller Regel unpassend."],"correctIndex":2,"explanation":"Zwei Fehler liegen nahe. Der erste ist, aus ihrer Klugheit auf die Richtigkeit ihrer Überzeugung zu schließen: Intelligenz ist kein Gütesiegel für einzelne Behauptungen, und wer in einem Gebiet brillant ist, kann in einem anderen völlig danebenliegen (Appell an die falsche Autorität). Der zweite Fehler ist die Gegenrichtung, ihren Glauben auf Dummheit zu schieben. Das erklärt nichts, denn kein Mensch ist immun gegen Selbsttäuschung, egal wie intelligent oder skeptisch er sonst ist. Auffällig ist hier das Muster: Eine intelligente Person verteidigt eine unbewiesene Behauptung, die ein tiefes persönliches Bedürfnis berührt, wendet ihre kritischen Fähigkeiten nicht auf die eigene, liebgewonnene Überzeugung an und erfindet für widersprüchliche Beweise immer neue Rationalisierungen. Der Schlüssel liegt also im Bedürfnis dahinter (Trost, Hoffnung, Sinn). Die Frage, welches tiefe emotionale Bedürfnis dieser Glaube für sie erfüllt, nimmt sie ernst und zeigt, warum die Prüfung bei ihr aussetzt. Das schafft die Grundlage für ein Gespräch. Völliges Schweigen wäre dagegen keine Rücksicht, sondern Verzicht auf jede Prüfung.","coreRule":"⚡ Erst fragen, was ein Glaube leistet, dann prüfen, was er behauptet.","beleg":"Werkstück F.1.6 (Das Härten im Feuer: Schmiede-Übung; Anwendung & Relevanz: Lektion in Demut; Red Flags)","status":"entwurf","kurz":"Wer fragt, welches Bedürfnis der Glaube für sie erfüllt, nimmt sie ernst und trifft den Kern: Klugheit schützt nicht vor Selbsttäuschung, wenn ein tiefer Wunsch im Spiel ist, und genau dort setzt ihre Prüfung aus.","prueffrage":"Wendet sie ihre kritische Schärfe, die sie sonst zeigt, auch auf die Botschaften des Mediums an?","rueckmeldung":[{"option":0,"text":"Klugheit wirkt wie ein Gütesiegel, ist aber keines für einzelne Behauptungen. Wer in einem Gebiet brillant ist, kann bei einer liebgewonnenen Überzeugung trotzdem danebenliegen, denn gegen Selbsttäuschung ist niemand immun."},{"option":1,"text":"Ihre Hartnäckigkeit verlangt nach einer Erklärung, und Dummheit liegt scheinbar nahe. Sie erklärt aber nichts, denn Selbsttäuschung trifft auch kluge Menschen, und der Vorwurf wäre genau die Überheblichkeit, die du vermeiden willst."},{"option":3,"text":"Rücksicht in der Trauer ist wichtig, und Takt gehört dazu. Gar nicht mehr zu prüfen, macht daraus aber einen Verzicht auf jedes Gespräch. Ein ruhiges Nachfragen nach dem Bedürfnis dahinter ist rücksichtsvoller, als alles unausgesprochen zu lassen."}],"familie":"wohlwollend-verstehen","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Internet Encyclopedia of Philosophy: Fallacies, Art. „Appeal to Authority“","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"url","kurz":"Kahan, D. M. u. a. (2013): Motivated Numeracy and Enlightened Self-Government (Working Paper)","oeffentlich":true,"url":"https://scholarsbank.uoregon.edu/items/e034d504-ed17-4e0c-a713-ac3f85a8187a/full","abruf":"2026-10-12"}],"thema":"Psychologie"},{"id":"qx-f-032","clusterId":"F","werkstueckRef":"F.1.7","stufe":1,"question":"In einer Diskussion sagt jemand: „Eine Taschenuhr hat offensichtlich einen Uhrmacher. Lebewesen sind noch viel komplexer, also muss es auch für sie einen Designer geben.“ Welcher Einwand trifft den Schwachpunkt dieses Vergleichs am besten?","options":["Eine Uhr wird in einer einzigen Herstellungsphase fertig gebaut, Lebewesen entstehen dagegen über lange Zeiträume schrittweise durch Variation und Selektion; der Vergleich überträgt also die Entstehungsweise eines Objekts auf einen ganz anders ablaufenden Prozess.","Eine Uhr besteht aus Metall, Lebewesen bestehen dagegen aus organischen Stoffen; wer beide vergleicht, mischt also zwei Materialklassen, die sich grundsätzlich nicht gegenüberstellen lassen.","Eine Uhr erfüllt erkennbar einen Zweck, Lebewesen dagegen nicht; wer ihnen eine Funktion zuschreibt, deutet also menschliche Absichten in die Natur hinein, die dort gar nicht vorkommen.","Eine Uhr braucht einen Hersteller, weil sie eine Ursache haben muss; Lebewesen sind dagegen unverursacht und entstehen aus reinem Zufall, ohne dass irgendein Mechanismus wirkt."],"correctIndex":0,"explanation":"Eine Analogie trägt nur so weit, wie die verglichenen Dinge in dem Punkt übereinstimmen, auf den der Schluss sich stützt. Hier ist der entscheidende Punkt die Entstehungsweise: Eine Taschenuhr könnte in ihrer heutigen Form nicht aus winzigen, funktionsfähigen Vorformen herauswachsen, sie wird in einer Herstellungsphase fertig gebaut. Lebewesen entstehen dagegen über viele Generationen, weil zufällige Mutationen auftreten und die Selektion nicht-zufällig diejenigen bevorzugt, die sich besser fortpflanzen. Teilstrukturen können dabei zunächst andere Vorteile bieten und später in neue Funktionen eingebunden werden (Exaptation). Der Uhrmacher-Schluss setzt also stillschweigend voraus, dass Komplexität nur durch fertige Planung entsteht, und genau das ist der unbelegte Schritt. Die anderen Einwände greifen daneben: Der Materialunterschied ist für den Schluss unerheblich, Funktionen lassen sich an Organen sehr wohl feststellen, und Evolution ist gerade nicht reiner Zufall, denn Selektion ist nicht zufällig.","coreRule":"⚡ Prüfe bei jeder Analogie, ob die verglichenen Dinge in dem Punkt übereinstimmen, auf den der Schluss sich stützt.","beleg":"Werkstück F.1.7 (Kontext & Tiefe, Punkt 4; Abschnitt „Die Uhr im Garten“); Fn. gl-f-8 nur für Paleys Uhr-Analogie (Paley 1802, Kap. 1 und 3)","status":"entwurf","scenario":"","kurz":"Der Vergleich trägt nur, wenn Uhr und Lebewesen auf gleiche Weise entstehen: Eine Uhr wird fertig gebaut, Lebewesen haben sich über viele Generationen schrittweise entwickelt. Dass Komplexität nur durch Planung entstehen kann, setzt der Schluss stillschweigend voraus.","prueffrage":"Woran erkennt man bei einer Taschenuhr, dass ein Uhrmacher sie gebaut hat, und trifft dasselbe auf eine Katze zu?","rueckmeldung":[{"option":1,"text":"Metall und organische Stoffe unterscheiden sich tatsächlich, nur hängt der Schluss nicht am Material. Entscheidend ist, wie etwas entsteht, und dazu sagt der Stoffunterschied nichts. Verglichen werden kann auch über Materialgrenzen hinweg."},{"option":2,"text":"Wer Funktionen in der Natur sieht, deutet leicht Absichten hinein, das ist eine bekannte Gefahr. Die Funktion eines Organs lässt sich aber feststellen, und die Selektion erklärt sie ohne Absicht. Das Problem des Vergleichs liegt woanders."},{"option":3,"text":"Mutationen sind zwar zufällig, die Selektion ist es nicht: Sie bevorzugt, wer sich besser fortpflanzt. Von „unverursacht“ kann also keine Rede sein. Der Vergleich scheitert nicht an fehlender Ursache, sondern an der Art der Entstehung."}],"familie":"schluss-pruefen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Kitzmiller v. Dover Area School District, Memorandum Opinion vom 20.12.2005","oeffentlich":true,"url":"https://www.pamd.uscourts.gov/sites/pamd/files/opinions/04v2688d.pdf","seite":"S. 74–75, 80–81","abruf":"2026-10-12"},{"typ":"url","kurz":"University of California Museum of Paleontology: Understanding Evolution, „Misconceptions about evolution“","oeffentlich":true,"url":"https://evolution.berkeley.edu/teach-evolution/misconceptions-about-evolution/","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft"},{"id":"qx-f-033","clusterId":"F","werkstueckRef":"F.1.7","stufe":2,"question":"Was ist an der Aussage sachlich falsch?","scenario":"Ein Mitschüler behauptet im Biologieunterricht: „Evolution ist doch reiner Zufall. So etwas Komplexes wie ein Auge kann nicht zufällig entstehen.“ Du willst herausfinden, ob die Behauptung überhaupt auf den tatsächlichen Mechanismus zielt.","options":["Evolution wird von einem Plan gelenkt und ist deshalb so wenig Zufall wie ein von Ingenieuren konstruiertes Gerät.","Mutationen sind gezielte Reaktionen auf den Bedarf des Organismus, und die Auslese wirkt nur auf bereits fertige Strukturen.","Evolution ist nicht reiner Zufall: Zufällige Mutationen treffen auf eine nicht-zufällige Auslese, die vorteilhafte Veränderungen anhäuft.","Die Auslese sortiert zwar Mutationen aus, bringt aber nur kleine Veränderungen hervor und nie komplexe Strukturen."],"correctIndex":2,"explanation":"Der Fehler liegt in der Gleichsetzung von „Evolution“ mit „Zufall“. Der Prozess kombiniert zwei Teile: zufällige Mutation und nicht-zufällige Selektion. Natürliche Selektion filtert aus unzähligen Mutationen beständig diejenigen heraus, die den Fortpflanzungserfolg steigern. Über Millionen von Generationen entstehen so komplexe Anpassungen, ohne dass ein bewusster Designer nötig wäre. Biologische Systeme entstehen über lange Zeiträume und vielfältige Zwischenstufen, nicht in einem einzigen Schritt. Wer die Frage stellt, wie wahrscheinlich es ist, dass ein Auge rein zufällig entsteht, bekämpft daher ein Zerrbild der Evolution. Die Alternativen scheitern an anderen Punkten: Die Behauptung, ein Plan lenke die Evolution, müsste erst belegt werden, statt einfach vorausgesetzt zu werden. Die Behauptung, Selektion liefere nur Kleinschritte, übersieht, dass sich kumulative Anpassungen über lange Zeiträume zu komplexen Systemen summieren. Und die Behauptung, Mutationen träten genau bei Bedarf auf, passt nicht zum tatsächlichen Mechanismus: Mutationen sind zufällig, erst die Selektion wirkt nicht-zufällig.","coreRule":"⚡ Mutation würfelt, Selektion sortiert: Das Ergebnis ist alles andere als Zufall.","beleg":"Werkstück F.1.7 (Kontext & Tiefe, Punkt 2: Zufällige Mutation, nicht-zufällige Selektion)","status":"entwurf","kurz":"Evolution ist nicht reiner Zufall: Mutationen sind zufällig, die Auslese danach ist es nicht. Sie häuft vorteilhafte Veränderungen über viele Zwischenstufen an. Wer fragt, ob ein Auge rein zufällig entsteht, bekämpft ein Zerrbild.","prueffrage":"Hat ein Tier mit einer schädlichen Veränderung dieselben Chancen auf Nachwuchs wie eines mit einer nützlichen?","rueckmeldung":[{"option":0,"text":"Der Zufallsvorwurf greift tatsächlich zu kurz, weil die Auslese nicht zufällig wirkt. Dafür braucht es aber keinen Plan, und ein lenkender Plan wäre erst zu belegen, statt ihn bloß vorauszusetzen."},{"option":1,"text":"Mutationen entstehen nicht gezielt nach Bedarf, sie sind zufällig; nicht-zufällig wirkt erst die Auslese. Und die wirkt auf vorhandene Varianten über viele Zwischenstufen, nicht erst auf fertige Strukturen."},{"option":3,"text":"Dass Auslese Mutationen aussortiert, stimmt. Kleine Schritte bleiben aber nicht klein: Über sehr lange Zeiträume und viele Zwischenstufen summieren sie sich zu komplexen Strukturen wie dem Auge."}],"familie":"auslese-statt-plan","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"University of California Museum of Paleontology: Understanding Evolution, „Misconceptions about evolution“ (Abschnitt „Evolution happens by chance“)","oeffentlich":true,"url":"https://evolution.berkeley.edu/teach-evolution/misconceptions-about-evolution/","abruf":"2026-10-12"}],"thema":"Natur und Klima"},{"id":"qx-f-034","clusterId":"F","werkstueckRef":"F.1.7","stufe":3,"question":"Ein Podiumsredner sagt: „Wissenschaftliche Methodik hin oder her – ob eine Idee in den Biologieunterricht gehört, ist reine Geschmacksfrage. Wir stellen einfach beide Erklärungen gleichwertig nebeneinander und lassen die Schüler entscheiden.“ Die Idee, um die es geht: Bestimmte Strukturen seien so komplex, dass ein bewusster Designer sie geplant haben müsse. Welche Prüffrage trifft den Kern, ob die Idee als gleichwertige wissenschaftliche Alternative in den Lehrplan gehört?","options":["Lässt sich die Idee prüfen: Sagt sie etwas voraus, das sich beobachten oder widerlegen lässt, und wurden ihre prüfbaren Teilbehauptungen bereits getestet?","Wie viele Menschen in der Region halten die Idee für plausibel, und wie stark ist der Rückhalt in der Elternschaft?","Lässt sich die Idee mit dem Weltbild vereinbaren, das viele Schüler von zu Hause mitbringen, ohne dass sich jemand ausgegrenzt fühlt?","Wird die Idee von einer ernst zu nehmenden Bewegung mit klaren Zielen vertreten, die sich öffentlich für sie einsetzt?"],"correctIndex":0,"explanation":"Ob etwas gleichwertige Wissenschaft ist, entscheidet nicht die Beliebtheit, die Vereinbarkeit mit Weltbildern oder die Organisiertheit der Befürworter, sondern die Prüfbarkeit. Eine Hypothese, die jeden Befund als weiteren Beleg deutet, ist nicht falsifizierbar, und die Beweislast liegt bei dem, der sie vorbringt. Prüfbar ist beim Designer-Argument nur die Teilbehauptung, bestimmte Strukturen seien „irreduzibel komplex“, also ohne jedes einzelne Teil nutzlos – und sie wurde geprüft: Beim bakteriellen Flagellum entspricht ein Teil der Bauteile denen des Typ-III-Sekretionssystems, das für sich allein voll funktionsfähig ist. Ein US-Bundesgericht urteilte 2005 im Fall Dover: Intelligent Design sei keine Wissenschaft und lasse sich von seinen kreationistischen Wurzeln nicht trennen; der Schulbezirk durfte es deshalb nicht im Biologieunterricht vorstellen lassen. Maßgeblich ist, ob die Idee prüfbar und damit wissenschaftlich ist – nicht, wie beliebt sie ist, wie gut sie zu Weltbildern passt oder wie gut ihre Befürworter organisiert sind.","coreRule":"⚡ Ob eine Idee als Wissenschaft gleichwertig neben anderen steht, entscheidet ihre Prüfbarkeit – nicht Beliebtheit, Weltbild-Verträglichkeit oder Lautstärke ihrer Vertreter.","beleg":"Werkstück F.1.7 (Anwendung & aktuelle Bedeutung, Wissenschaftspolitik; Der Kipppunkt); Fn. gl-f-kitzmiller (Kitzmiller v. Dover, 20.12.2005, S. 28 f., 64 und 136)","status":"entwurf","scenario":"","kurz":"Gleichwertige Wissenschaft setzt Prüfbarkeit voraus: Eine Idee muss etwas voraussagen, das sich beobachten und widerlegen ließe, und solchen Tests standhalten. Beliebtheit, Verträglichkeit mit Weltbildern oder gut organisierte Befürworter ersetzen das nicht.","prueffrage":"Woran sollen die Schüler nach dem Vorschlag des Redners erkennen, welche der beiden Erklärungen zutrifft?","rueckmeldung":[{"option":1,"text":"Verbreitung und Elternrückhalt lassen sich leicht messen und können politisch zählen. Über den wissenschaftlichen Status sagen sie aber nichts, denn viele Menschen können etwas plausibel finden, das sich nicht prüfen lässt."},{"option":2,"text":"Rücksicht auf das Weltbild der Schüler ist ein berechtigtes pädagogisches Anliegen. Es beantwortet aber nicht, ob die Idee wissenschaftlich prüfbar ist, und nur das entscheidet über eine gleichwertige Stellung im Lehrplan."},{"option":3,"text":"Eine gut organisierte Bewegung zeigt Engagement, aber keine Prüfbarkeit. Wie viele sich wie laut für eine Idee einsetzen, sagt nichts darüber, ob sie etwas Überprüfbares voraussagt und Tests besteht."}],"familie":"wissenschaft-abgrenzen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Kitzmiller v. Dover Area School District, Memorandum Opinion vom 20.12.2005","oeffentlich":true,"url":"https://www.pamd.uscourts.gov/sites/pamd/files/opinions/04v2688d.pdf","seite":"S. 64, 76–77, 136","abruf":"2026-10-12"},{"typ":"url","kurz":"Thornton, S.: Karl Popper, Stanford Encyclopedia of Philosophy (Abschn. 2–3, Falsifizierbarkeit)","oeffentlich":true,"url":"https://plato.stanford.edu/entries/popper/","abruf":"2026-10-12"}],"thema":"Zusammenleben"},{"id":"qx-f-035","clusterId":"F","werkstueckRef":"F.1.7","stufe":4,"question":"Eine Verteidigerin einer Theorie sagt: „Findet man in den Gesteinsschichten eine Zwischenform, ist das ein Beleg für meine Theorie; findet man keine, ist es ebenfalls ein Beleg.“ Wo liegt das methodische Problem?","options":["Die Theorie ist zu einfach: Ein belastbares Modell muss möglichst viele verschiedene Ursachen heranziehen.","Die Theorie ist zu kompliziert: Sparsamkeit verlangt, ganz ohne unbewiesene Annahmen auszukommen.","Die Aussage ist ein Zirkelschluss, weil die Gesteinsschichten nur existieren, wenn die Theorie bereits stimmt.","Die Theorie ist mit jedem möglichen Befund vereinbar, sagt nichts voraus und kann deshalb nicht scheitern."],"correctIndex":3,"explanation":"Eine Theorie, die sowohl den Fund als auch das Ausbleiben des Funds als Bestätigung verbucht, schließt keinen denkbaren Befund aus. Damit kann nichts sie widerlegen, und gerade deshalb prüft nichts sie. Wissenschaftliche Modelle sagen dagegen etwas voraus, das auch scheitern könnte: „Wenn die Theorie stimmt, dürfen wir X nicht finden.“ Wer jeden Ausgang als Treffer wertet, erklärt scheinbar alles, in Wahrheit aber nichts. Das Gegenmittel ist die Frage: „Welcher Befund würde dich umstimmen?“ Gibt es keinen, ist die Behauptung nicht prüfbar.","coreRule":"⚡ Wer jeden Befund erklären kann, erklärt nichts: Ein prüfbares Modell muss etwas ausschließen.","beleg":"Werkstück F.1.7 (Kontext & Tiefe, Punkt 3: Beweislast und Falsifizierbarkeit; Red Flags)","status":"entwurf","scenario":"","kurz":"Wer Fund und Nicht-Fund gleichermaßen als Bestätigung wertet, schließt keinen denkbaren Befund aus. Dann kann nichts die Theorie widerlegen, und sie erklärt scheinbar alles, in Wahrheit aber nichts, weil sie keine überprüfbare Voraussage macht.","prueffrage":"Was weißt du nach ihrer Aussage über die Gesteinsschichten, das du vorher noch nicht wusstest?","rueckmeldung":[{"option":0,"text":"Ein Modell wirkt gründlich, wenn es viele Ursachen einbezieht. Je mehr es aber im Nachhinein erklären kann, desto weniger legt es sich fest. Das Problem liegt nicht in zu wenig Ursachen, sondern darin, dass kein Befund die Theorie ausschließt."},{"option":1,"text":"Sparsamkeit ist ein gutes Prinzip, heißt aber, unnötige Annahmen zu vermeiden, nicht jede. Ganz ohne unbewiesene Annahmen kommt keine Theorie aus. Der Mangel liegt nicht in der Kompliziertheit, sondern darin, dass die Theorie nie scheitern kann."},{"option":2,"text":"Die Aussage wirkt geschlossen, weil ihr jeder Befund recht gibt. Die Gesteinsschichten gibt es aber unabhängig von der Theorie, ein Kreis in der Begründung liegt also nicht vor. Der Fehler ist die fehlende Möglichkeit zu scheitern."}],"familie":"immunisierung-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: Karl Popper (Abschn. 2 „Backdrop to Popper's Thought“, Abschn. 3 „The Problem of Demarcation“)","oeffentlich":true,"url":"https://plato.stanford.edu/entries/popper/","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft"},{"id":"qx-f-036","clusterId":"F","werkstueckRef":"F.2.1","stufe":1,"question":"Welche Prüfung zeigt am besten, ob die Aussage wirklich etwas Besonderes über deine Freundin verrät?","scenario":"Eine Freundin liest dir aus ihrem Tageshoroskop vor: „Du hast ein kreatives Potenzial, das noch nicht voll ausgeschöpft ist.“ Sie ist begeistert: „Das trifft genau auf mich zu! Das kann doch kein Zufall sein.“ Du willst herausfinden, ob die Aussage wirklich etwas über sie verrät.","options":["Fragen, ob dieselbe Aussage auch auf andere Menschen zutreffen würde, etwa auf ihre Kollegen und Nachbarn.","Abwarten, ob sich in den nächsten Tagen ein Ereignis zeigt, das zu der Aussage passt.","Nachsehen, wie viele andere Leserinnen und Leser die Aussage ebenfalls als treffend bewerten.","Die Aussage danach beurteilen, wie stimmig sie sich für deine Freundin selbst anfühlt."],"correctIndex":0,"explanation":"Eine Aussage verrät nur dann etwas über eine bestimmte Person, wenn sie auf diese Person besser passt als auf andere. „Du hast ein kreatives Potenzial, das noch nicht voll ausgeschöpft ist“ ist eine typische Barnum-Aussage: vage, schmeichelhaft und universell genug, dass jeder sich darin wiedererkennt. Solche Sätze fühlen sich persönlich an, sind es aber nicht. Das Gefühl der Treffsicherheit ist deshalb kein Beleg. Auch das Abwarten auf passende Ereignisse hilft nicht, weil bei so vagen Sätzen fast immer etwas passt (Bestätigungsfehler). Dass viele andere Leserinnen und Leser die Aussage ebenfalls treffend finden, ist ohne Kontrollvergleich kein Beleg für einen Personenbezug; es spricht eher dafür, dass die Aussage auf alle passt. Entscheidend ist, ob sie auch auf andere zutrifft.","coreRule":"⚡ Passt eine Aussage auf alle, sagt sie über niemanden etwas: Prüfe, ob sie auch auf andere zutreffen würde.","beleg":"Werkstück F.2.1 (Die Anatomie der Täuschung: Barnum-Effekt, B.10)","status":"entwurf","kurz":"Eine Aussage verrät nur dann etwas über jemanden, wenn sie auf diese Person besser passt als auf andere. Der Satz ist so vage und schmeichelhaft, dass er fast jedem passt; das Gefühl, getroffen zu sein, belegt deshalb nichts.","prueffrage":"Wer in deinem Bekanntenkreis würde von sich sagen, sein kreatives Potenzial sei schon voll ausgeschöpft?","rueckmeldung":[{"option":1,"text":"Abwarten wirkt wie ein Test an der Wirklichkeit. Bei einem so vagen Satz passt aber fast jedes Ereignis irgendwie dazu, und man merkt sich vor allem die Treffer. Ohne Vergleich mit anderen sagt das wenig über deine Freundin."},{"option":2,"text":"Viel Zustimmung klingt nach einem guten Zeichen. Ohne Kontrollvergleich spricht sie aber eher dafür, dass der Satz auf fast alle passt, und nicht dafür, dass er etwas über deine Freundin verrät."},{"option":3,"text":"Das Gefühl, genau gemeint zu sein, ist echt und doch kein Maßstab. Vage, schmeichelhafte Sätze erzeugen es bei fast allen Leserinnen und Lesern, ob sie zutreffen oder nicht."}],"familie":"passt-auf-jeden","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Carroll, R. T.: The Skeptic's Dictionary, Art. „Forer effect“","oeffentlich":true,"url":"https://skepdic.com/forer.html","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Forer, B. R. (1949): The fallacy of personal validation: a classroom demonstration of gullibility. Journal of Abnormal and Social Psychology 44(1), S. 118 ff.","oeffentlich":false}],"thema":"Psychologie"},{"id":"qx-f-037","clusterId":"F","werkstueckRef":"F.2.1","stufe":2,"question":"Ein Astrologe behauptet: „Die Schwerkraft der Planeten prägt den Charakter eines Menschen bei der Geburt.“ Welcher Einwand trifft diese Behauptung am stärksten?","options":["Ein Körper im selben Raum, etwa der Geburtshelfer, zieht das Neugeborene ähnlich stark oder stärker an als der Mars. Wäre Schwerkraft der Mechanismus, bestimmte der Geburtshelfer das Horoskop mit.","Die Schwerkraft der Planeten wirkt so stark auf den Körper, dass jeder die Gezeiten bei sich selbst spüren müsste. Da das niemand tut, kann sie keinen Einfluss haben.","Die Schwerkraft wirkt nur auf andere Himmelskörper und nicht auf Lebewesen. Deshalb kann sie bei der Geburt eines Menschen keine Rolle spielen.","Die Schwerkraft des Mars ist messbar, ändert sich aber so schnell, dass sie nie zweimal dasselbe Horoskop ergibt. Deshalb kann sie keinen festen Charakter prägen."],"correctIndex":0,"explanation":"Der Einwand prüft, ob die behauptete Ursache überhaupt ausreicht: Die Anziehung des Geburtshelfers neben der Mutter liegt je nach Marsstellung und Abstand in derselben Größenordnung wie die des Planeten oder deutlich darüber, und seine Gezeitenwirkung übertrifft die des Mars um viele Größenordnungen. Wäre Schwerkraft der Mechanismus, müsste das Horoskop also mindestens ebenso vom Geburtshelfer abhängen wie vom Planeten. Das ist offensichtlich nicht gemeint, also taugt die Schwerkraft nicht als Erklärung. Die anderen Einwände sind selbst fehlerhaft: Der Gezeiten-Einwand dreht das Argument um, denn das Problem ist nicht die Stärke der Planetenschwerkraft, sondern ihre Schwäche gegenüber nahen Körpern; und ob sich eine Wirkung schnell ändert, sagt nichts darüber, ob sie stark genug wäre. Gravitation wirkt zudem auf alle Massen, Lebewesen eingeschlossen.","coreRule":"⚡ Eine behauptete Ursache muss stärker sein als naheliegende Alternativen im selben Raum. Sonst taugt sie nicht als Erklärung.","beleg":"Werkstück F.2.1 (Die Konfrontation mit der Realität: Verletzung der Physik)","status":"entwurf","scenario":"","quote":"","quoteLabel":"","kurz":"Der Einwand misst die behauptete Ursache an ihrer Stärke: Die Anziehung des Geburtshelfers liegt in derselben Größenordnung wie die des Mars oder darüber, seine Gezeitenwirkung ist sogar weit größer. Wäre Schwerkraft der Mechanismus, müsste er das Horoskop mitbestimmen.","prueffrage":"Wovon hängt ab, wie stark ein Körper ein Neugeborenes anzieht, und wie ändert sich das mit der Entfernung?","rueckmeldung":[{"option":1,"text":"Der Einwand setzt voraus, die Planetenschwerkraft sei stark genug für spürbare Gezeiten im Körper. Das ist sie nicht: Ihre Wirkung auf einen Menschen ist winzig, und nahe Körper wie der Geburtshelfer erreichen oder übertreffen sie."},{"option":2,"text":"Dass der Mars auf ein Neugeborenes verschwindend wenig wirkt, trifft zu, daher wirkt der Satz plausibel. Gravitation wirkt aber auf alle Massen, auch auf Lebewesen. Der Einwand muss bei der Stärke ansetzen, nicht bei Wirkungslosigkeit."},{"option":3,"text":"Dass sich Planetenstellungen verändern, stimmt, entscheidet aber nicht über die Behauptung. Ob eine Wirkung veränderlich ist, sagt nichts darüber, ob sie stark genug wäre, einen Charakter zu prägen, und gerade daran scheitert sie."}],"familie":"sparsamste-erklaerung","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Universe Today: „Debunking Astrology: Mars Can't Influence You“","oeffentlich":true,"url":"https://universetoday.com/articles/debunking-astrology-mars-cant-influence-you","abruf":"2026-10-12"}],"thema":"Natur und Klima"},{"id":"qx-f-038","clusterId":"F","werkstueckRef":"F.2.1","stufe":3,"question":"Du kritisierst: „Wegen der Präzession passt dein Sternzeichen nicht mehr zu dem Sternbild, in dem die Sonne bei deiner Geburt tatsächlich stand.“ Ein Astrologe entgegnet: „Mein Tierkreis richtet sich bewusst nach den Jahreszeiten, gezählt ab dem Frühlingsanfang, nicht nach den Sternbildern.“ Wie bewertest du diese Antwort?","options":["Sie beantwortet den Einwand, aber dann deutet die Astrologie streng genommen nicht mehr die Sterne, sondern den Kalender.","Sie widerlegt die Kritik vollständig, denn damit hat die Astrologie eine astronomisch korrekte Grundlage.","Sie ist ein Widerspruch in sich, denn ein Tierkreis nach Jahreszeiten kann nicht von der Position der Sterne abweichen.","Sie ist belanglos, denn die Verschiebung der Sternbilder wurde durch die neu entdeckten Planeten längst ausgeglichen."],"correctIndex":0,"explanation":"Die Verteidigung ist in sich stimmig: Ein tropischer Tierkreis wird von Frühlingspunkt zu Frühlingspunkt gezählt und ist damit an die Jahreszeiten gebunden, nicht an die Sternbilder. Der Einwand der Präzession trifft ihn deshalb nicht. Aber die Antwort hat einen Preis: Wenn sich die Zeichen nach dem Kalender richten, ordnet die Astrologie Menschen nach dem Datum und nicht nach der Stellung der Himmelskörper. Damit fällt auch die Behauptung, die Sterne selbst hätten einen Einfluss. Eine Verteidigung, die den ursprünglichen Gegenstand aufgibt, hat den Streitpunkt nicht gewonnen, sondern verlagert.","coreRule":"⚡ Wer den Himmel gegen den Kalender tauscht, hat die Sterne aus der Astrologie gestrichen.","beleg":"Werkstück F.2.1 (Verletzung der Astronomie); Fn. gl-f-tropisch (Carroll 2003, Skeptic's Dictionary, Art. astrology)","status":"entwurf","scenario":"Du diskutierst mit einem Astrologen über die Verschiebung der Sternbilder seit der Antike.","quote":"","quoteLabel":"","kurz":"Der Einwand der Präzession trifft den Astrologen tatsächlich nicht, denn sein Tierkreis ist an die Jahreszeiten gebunden. Damit ordnet er aber nach dem Datum statt nach den Sternen und verlagert den Streitpunkt, statt ihn zu gewinnen.","prueffrage":"Welches Zeichen hätte nach diesem Tierkreis jemand, der heute am selben Kalendertag geboren wird wie jemand vor 2000 Jahren?","rueckmeldung":[{"option":1,"text":"Der Präzessionseinwand trifft einen jahreszeitlich gezählten Tierkreis tatsächlich nicht. Widerlegt ist die Kritik damit aber nicht, denn die Zeichen hängen nun am Kalender statt an den Sternen, und ein Einfluss der Sterne ist so nicht begründet."},{"option":2,"text":"Ein Tierkreis, der nach dem Frühlingspunkt gezählt wird, kann von den Sternbildern abweichen, und genau das behauptet der Astrologe. Die Antwort ist in sich stimmig; der Haken liegt woanders, nämlich in dem, was sie aufgibt."},{"option":3,"text":"Die Verschiebung kommt von der Kreiselbewegung der Erdachse, nicht von neu entdeckten Planeten, die sie also gar nicht ausgleichen könnten. Belanglos ist die Antwort auch nicht, denn sie ändert, worüber der Streit überhaupt geführt wird."}],"familie":"mechanismus-verlangen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Carroll, R. T.: The Skeptic's Dictionary, Art. „astrology“","oeffentlich":true,"url":"https://skepdic.com/astrology.html","abruf":"2026-10-12"}],"thema":"Natur und Klima"},{"id":"qx-f-039","clusterId":"F","werkstueckRef":"F.2.1","stufe":4,"question":"Welche Testanordnung prüft die Behauptung der Astrologin am fairsten?","options":["Die Astrologin darf ihre Kunden vor der Deutung ausführlich befragen und ordnet danach Horoskop und Charakterbild zu.","Die Astrologin ordnet Horoskope und Persönlichkeitsprofile zu, und sie selbst entscheidet danach, welche Zuordnungen als Treffer zählen.","Die Astrologin deutet Horoskope von Menschen, die bereits wissen, was ihr Sternzeichen angeblich über sie aussagt, und diese Menschen bewerten, ob die Deutung stimmt.","Die Astrologin ordnet Horoskope den passenden Persönlichkeitsprofilen zu, und weder sie noch die Testleitung wissen währenddessen, welche Zuordnung richtig ist."],"correctIndex":3,"explanation":"Ein fairer Test muss ausschließen, dass etwas anderes als das Horoskop die Treffer erzeugt. Wer die Menschen vorher befragt, liest den Charakter aus den Antworten statt aus den Sternen. Wer die Treffer selbst bewertet, begünstigt den Bestätigungsfehler; wer Betroffene bewerten lässt, die sich gern wiedererkennen, nutzt den Barnum-Effekt: Vage Aussagen passen fast immer. Im Doppelblindtest kennt niemand die Lösung, sodass Erwartung und Vorwissen ausscheiden und nur zählt, ob mehr als der Zufall herauskommt. Genau so ein Test fand statt: Carlson ließ Astrologen Horoskope den passenden Persönlichkeitsprofilen zuordnen, und die Trefferquote betrug 0,34 bei einer Zufallsquote von 0,33. Ein anderer Test mit „Zeitzwillingen“ (gut 2.000 Londoner, geboren im März 1958) zeigte ebenfalls keine Ähnlichkeit über den Zufall hinaus: Sie ähnelten ihren Zeitzwillingen in Intelligenz, Verhalten und Körpermerkmalen nicht stärker als beliebigen anderen Menschen.","coreRule":"⚡ Fair testen heißt blind testen: Wer Vorwissen oder Bewertung in der Hand hat, misst seine Erwartung, nicht die Behauptung.","beleg":"Werkstück F.2.1 (Das Zwillings-Problem); Fn. gl-f-astrotests (Carlson 1985, Nature 318, S. 419--425; Dean, Kelly 2003)","status":"entwurf","scenario":"Eine Astrologin behauptet: „Ich erkenne den Charakter eines Menschen an seinem Horoskop, auch wenn ich ihn nie getroffen habe.“ Ein Skeptiker will das prüfen, ohne dass das Ergebnis durch Erwartungen, Vorwissen oder Wohlwollen verzerrt wird. Er schlägt vier Testanordnungen vor.","kurz":"Fair ist der Test, wenn niemand die Lösung kennt: Dann können weder Erwartung noch Vorwissen Treffer erzeugen, und nur das Ergebnis über dem Zufall zählt. Sonst prüfst du nicht das Horoskop, sondern Befragung, Wohlwollen oder Selbstbild.","prueffrage":"Woher könnte in jeder der vier Anordnungen ein Treffer kommen, wenn Horoskope gar nichts über den Charakter verraten?","rueckmeldung":[{"option":0,"text":"Eine Befragung liefert Information, nur stammt sie dann aus den Antworten der Kunden und nicht aus dem Horoskop. Geprüft würde so nicht, ob sich ein Charakter aus den Sternen erkennen lässt, wie die Astrologin es behauptet."},{"option":1,"text":"Horoskope Profilen zuzuordnen ist ein brauchbares Format. Wenn die Astrologin aber selbst entscheidet, was als Treffer zählt, begünstigt das den Bestätigungsfehler: Bei großzügiger Auslegung wird fast jede Zuordnung irgendwie passend."},{"option":2,"text":"Menschen kennen sich selbst, deshalb wirkt ihr Urteil verlässlich. Wer aber die erwartete Aussage seines Sternzeichens schon kennt und sich gern wiedererkennt, findet vage Deutungen stimmig; das ist der Barnum-Effekt."}],"familie":"fair-testen","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Carlson, S. (1985): A double-blind test of astrology. Nature 318, S. 419–425","oeffentlich":false,"doi":"10.1038/318419a0"},{"typ":"url","kurz":"Dean, G.; Kelly, I. W. (2003): Is Astrology Relevant to Consciousness and Psi? (Webfassung)","oeffentlich":true,"url":"https://www.astrology-and-science.com/D-psia2.htm","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft"},{"id":"qx-f-040","clusterId":"F","werkstueckRef":"F.2.2","stufe":1,"question":"Welche Frage prüft die Behauptung „Je stärker verdünnt und geschüttelt, desto stärker die Wirkung“ am besten auf Plausibilität?","options":["Wie viel von der Ausgangssubstanz steckt bei dieser Verdünnung noch im Fläschchen, und wodurch soll dann eine Wirkung entstehen?","Wie lange wird das Mittel schon verkauft, und wie viele Bekannte schwören bis heute darauf?","Wie teuer ist das Mittel im Vergleich zu anderen Präparaten, und wie hochwertig wirkt die Verpackung?","Wie gut hat er sich nach der Einnahme gefühlt, und wie lange hat dieses Gefühl danach angehalten?"],"correctIndex":0,"explanation":"Eine Wirkbehauptung prüft man zuerst an ihrem Mechanismus: Soll eine Substanz wirken, muss sie in der Lösung auch vorhanden sein. Bei C30 beträgt der Verdünnungsfaktor 10^60; statistisch ist kein einziges Molekül der Ausgangssubstanz mehr zu erwarten, schon ab etwa C12 ist die Avogadro-Grenze überschritten. Außerdem beruht die Pharmakologie auf der Dosis-Wirkungs-Beziehung: Mehr Wirkstoff bewirkt mehr Wirkung (bis zu einem Sättigungs- oder Giftigkeitspunkt), nicht weniger. „Mehr Verdünnung, mehr Wirkung“ widerspricht dem und kommt ohne plausiblen Mechanismus aus. Dagegen sagen Dauer der Verwendung, Beliebtheit und Preis nichts über die Wirksamkeit. Auch das gute Gefühl nach der Einnahme beweist nichts, denn viele Beschwerden klingen von selbst ab, und Erwartung und Zuwendung können Placebo-Effekte auslösen.","coreRule":"⚡ Prüfe bei jeder Wirkbehauptung zuerst den Mechanismus: Ist der behauptete Wirkstoff überhaupt vorhanden, und passt die Behauptung zur Dosis-Wirkungs-Beziehung?","beleg":"Werkstück F.2.2 (Die Kern-Behauptung); Fn. gl-f-9 (Hahnemann 1796, Hufelands Journal Bd. 2, S. 433)","status":"entwurf","scenario":"Ein Bekannter schwärmt von seinem Globuli-Fläschchen mit der Aufschrift C30. Er sagt: „Je mehr das Mittel verdünnt und geschüttelt wird, desto stärker wirkt es.“","kurz":"Eine Wirkung braucht einen Mechanismus: Bei C30 ist statistisch kein Molekül des Ausgangsstoffs mehr zu erwarten. Und mehr Verdünnung widerspricht der Dosis-Wirkungs-Beziehung, nach der mehr Wirkstoff bis zu einer Grenze mehr Wirkung bringt, nicht weniger.","prueffrage":"Was würde mit der Wirkung einer Kopfschmerztablette geschehen, wenn man sie immer weiter mit Wasser verdünnt?","rueckmeldung":[{"option":1,"text":"Lange Verkaufsdauer und viele überzeugte Bekannte wirken wie Bewährung. Sie zeigen aber nur, dass das Mittel gekauft und geschätzt wird, nicht, dass es wirkt, und sie sagen nichts darüber, wie eine Wirkung zustande kommen soll."},{"option":2,"text":"Preis und Verpackung lassen sich leicht vergleichen und geben dem Mittel einen Anschein von Wert. Ob es wirkt, hängt davon aber nicht ab, und zur Frage, ob die Behauptung überhaupt plausibel ist, tragen sie nichts bei."},{"option":3,"text":"Sein Wohlbefinden ist real und verständlicherweise überzeugend. Als Beleg für das Mittel taugt es aber nicht: Viele Beschwerden klingen von selbst ab, und Erwartung und Zuwendung können schon allein ein gutes Gefühl auslösen."}],"familie":"verduennung-nachrechnen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"apotheken.de (Deutscher Apotheker Verlag): „Grundlagen der Homöopathie“ (nach Renz-Polster/Escher, Gesundheit heute)","oeffentlich":true,"url":"https://www.apotheken.de/sondertext/33c22-potenzierung","abruf":"2026-10-12"},{"typ":"doi","kurz":"Rademacher, P. (2013): Die Mär vom Wasser mit Gedächtnis. Chemie in unserer Zeit 47(1), S. 24–31","oeffentlich":false,"doi":"10.1002/ciuz.201300580"}],"thema":"Gesundheit"},{"id":"qx-f-041","clusterId":"F","werkstueckRef":"F.2.2","stufe":2,"question":"Was kannst du der Freundin aus chemischer Sicht zum Inhalt des Fläschchens sagen?","scenario":"Eine Freundin schwärmt von ihren Globuli: „Auf dem Fläschchen steht C30, das sind hochwirksame Spuren des Heilstoffs, nur eben sehr fein dosiert.“ Du erinnerst dich: Eine Verdünnung um den Faktor 10 hoch 60 ist weit jenseits der Grenze, ab der in einer Lösung statistisch kein einziges Molekül des Ausgangsstoffs mehr zu erwarten ist (Avogadro-Konstante, Größenordnung C12).","options":["Es sind noch winzige, kaum messbare Spuren der Ursubstanz enthalten, weil bei jeder Verdünnung ein kleiner Rest im Wasser zurückbleibt.","Es ist genau ein Molekül der Ursubstanz enthalten, weil die Bezeichnung C30 für ein Verhältnis von einem Teil auf dreißig Teile steht.","Es ist statistisch kein Molekül der Ursubstanz mehr enthalten, weil die Verdünnung weit über die Grenze hinausgeht, ab der ein Molekül je Fläschchen zu erwarten wäre.","Es ist mehr Wirkstoff enthalten als bei einer Verdünnung um C12, weil die Konzentration beim Schütteln mit jedem Schritt wieder ansteigt."],"correctIndex":2,"explanation":"Eine C30-Verdünnung bedeutet einen Verdünnungsfaktor von 100^30 = 10^60, nicht „eins zu dreißig“. Die Avogadro-Grenze liegt bei D24 bzw. C12: Ab dort ist statistisch kein Molekül der Ausgangssubstanz mehr zu erwarten (rechnerisch 0,6 Moleküle je Mol Endprodukt). C30 liegt weit jenseits dieser Grenze. Niedrigpotenzen wie D6 bis D12 enthalten noch Spuren des Ausgangsstoffs, Hochpotenzen wie C30 statistisch keines mehr. Dass die Konzentration beim Verdünnen und Schütteln wieder ansteigt, widerspricht der Arithmetik: Potenzieren bedeutet schrittweises Verdünnen, nicht Aufkonzentrieren. Chemisch ist das Fläschchen Zucker und Wasser (Rademacher 2013).","coreRule":"⚡ Ab etwa C12 ist statistisch kein Wirkstoffmolekül mehr zu erwarten: Rechne die Verdünnung in Teilchen um, bevor du von „Spuren“ sprichst.","beleg":"Werkstück F.2.2 (Verletzung der Chemie); Fn. gl-f-tiefpotenzen (Rademacher 2013, S. 25--26); Fn. gl-f-10","status":"entwurf","kurz":"Eine C30-Verdünnung heißt 100^30 = 10^60, weit jenseits der Grenze von etwa C12, ab der statistisch kein einziges Molekül des Ausgangsstoffs mehr zu erwarten ist. „Hochwirksam“ klingt nach Stärke, bedeutet hier aber rechnerisch: nichts mehr drin.","prueffrage":"Welche Zahl steht hinter „C30“, und wie viele Moleküle des Ausgangsstoffs ergäbe das in einem Fläschchen?","rueckmeldung":[{"option":0,"text":"Bei Niedrigpotenzen wie D6 bis D12 bleiben tatsächlich noch Spuren zurück. Bei C30 wurde aber dreißigmal hintereinander hundertfach verdünnt; der „kleine Rest“ schrumpft dabei jedes Mal und liegt rechnerisch weit unter einem Molekül."},{"option":1,"text":"Die Bezeichnung klingt nach „eins zu dreißig“, steht aber für dreißig Verdünnungsschritte von je 1 zu 100, zusammen 1 zu 10^60. Selbst aus einem ganzen Mol Ausgangsstoff bliebe rechnerisch weit weniger als ein Molekül übrig."},{"option":3,"text":"Beim Schütteln wird nur durchmischt, nichts aufkonzentriert. Jeder Schritt verdünnt weiter, deshalb enthält C30 weniger Ausgangsstoff als C12, nicht mehr; „potenziert“ heißt hier schrittweise verdünnt, nicht verstärkt."}],"familie":"verduennung-nachrechnen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"apotheken.de (Deutscher Apotheker Verlag): „Grundlagen der Homöopathie“","oeffentlich":true,"url":"https://www.apotheken.de/sondertext/33c22-potenzierung","abruf":"2026-10-12"},{"typ":"doi","kurz":"Rademacher, P. (2013): Die Mär vom Wasser mit Gedächtnis. Chemie in unserer Zeit 47(1), S. 24–31","oeffentlich":false,"doi":"10.1002/ciuz.201300580"}],"thema":"Gesundheit"},{"id":"qx-f-042","clusterId":"F","werkstueckRef":"F.2.2","stufe":3,"question":"Was folgt aus diesem Muster am ehesten?","options":["Der Nutzen zeigt sich nur in den weniger sauberen Studien. Das spricht dafür, dass die positiven Ergebnisse auf Verzerrung beruhen und nicht auf einer echten Wirkung.","Die Studien widersprechen sich, ohne dass ein Muster erkennbar wäre. Über einen möglichen Nutzen lässt sich daher kaum etwas sagen.","Die sauberen Studien sind zu streng und verfehlen den Nutzen. Deshalb sind die positiven Studien die aussagekräftigeren.","Der Nutzen ist klein, aber real. Er lässt sich lediglich nicht vom Placebo-Effekt trennen und bleibt deshalb unsichtbar."],"correctIndex":0,"explanation":"Entscheidend ist das Muster: Die Studien mit geringem Verzerrungsrisiko finden keinen Nutzen, positive Ergebnisse stammen ausschließlich aus Studien mit unklarem oder hohem Risiko. Genau das erwartet man, wenn es keine echte Wirkung gibt. Positive Ergebnisse entstehen dann durch Verzerrung im Studienaufbau, etwa durch fehlende Verblindung oder unsaubere Zuteilung, oder durch Zufall. Gäbe es eine echte Wirkung, müsste sie sich auch in den sauber durchgeführten Studien zeigen. Von „keinem erkennbaren Muster“ kann keine Rede sein, denn die Ergebnisse ordnen sich klar nach der Studienqualität. Auch der Verweis auf einen „kleinen, aber realen“ Effekt trägt nicht, weil ein Effekt, der bei sauberer Messung nicht auftaucht, sich nicht belegen lässt. Dieser Befund ist ein Beispiel dafür, wie man bei einem Evidenzkörper nicht nur zählt, wie viele Studien positiv ausfallen, sondern auch fragt, wie belastbar sie sind. Er gilt für diese Altersgruppe und diese Beschwerden und ersetzt keine ärztliche Beratung.","coreRule":"⚡ Wenn der Nutzen mit der Studienqualität verschwindet, spricht das gegen eine echte Wirkung.","beleg":"Werkstück F.2.2 (Abschluss-Diagnose); Fn. gl-f-homoeopathie-evidenz (Hawke u. a. 2022, Cochrane CD005974)","status":"entwurf","scenario":"Eine Übersichtsarbeit fasst elf Studien mit insgesamt 1.813 Kindern zusammen, die ein homöopathisches Mittel gegen akute Atemwegsinfekte testen. Die Autoren sortieren die Studien danach, wie anfällig ihr Aufbau für Verzerrungen ist (z. B. fehlende Verblindung oder unsaubere Zuteilung der Kinder auf die Gruppen). Dabei zeigt sich ein Muster: Alle Studien mit sauberem Aufbau finden keinen Nutzen. Positive Ergebnisse stammen ausschließlich aus Studien mit unklarem oder hohem Verzerrungsrisiko.","kurz":"Wenn nur die unsauber gebauten Studien Nutzen zeigen und die sauberen keinen, spricht das für Verzerrung statt Wirkung. Der naheliegende Fehler ist, nur zu zählen, wie viele Studien positiv ausfallen, statt zu fragen, wie belastbar sie sind.","prueffrage":"Wie fallen die Ergebnisse aus, wenn du die Studien nach der Sauberkeit ihres Aufbaus ordnest, statt sie nur zu zählen?","rueckmeldung":[{"option":1,"text":"Auf den ersten Blick fallen die Studien tatsächlich nicht einheitlich aus. Ordnet man sie aber nach der Qualität ihres Aufbaus, zeigt sich ein klares Muster. Von „kaum etwas sagen“ kann also keine Rede sein."},{"option":2,"text":"Strenge Bedingungen klingen nach einer Hürde, an der ein echter Nutzen scheitern könnte. Sauberer Aufbau macht Ergebnisse aber belastbarer: Die positiven Befunde stammen gerade aus den Studien, in denen Verzerrung am ehesten mitspielt."},{"option":3,"text":"Ein sehr kleiner Effekt kann schwer zu messen sein. Hier fehlt er aber ausgerechnet dort, wo sauber gemessen wurde, und der Placebo-Effekt lässt sich durch Verblindung und Kontrollgruppen gerade abtrennen. Ein Nutzen lässt sich so nicht belegen."}],"familie":"studie-genau-lesen","fertigkeit":"F4","quellen":[{"typ":"doi","kurz":"Hawke, K.; King, D.; van Driel, M. L.; McGuire, T. M. (2022): Homeopathic medicinal products for preventing and treating acute respiratory tract infections in children. Cochrane Database of Systematic Reviews, CD005974.pub6 (frei in PMC9746041)","oeffentlich":true,"doi":"10.1002/14651858.CD005974.pub6","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC9746041/","abruf":"2026-10-12"}],"thema":"Gesundheit"},{"id":"qx-f-043","clusterId":"F","werkstueckRef":"F.2.2","stufe":4,"question":"Was ist an der Argumentation des Verkäufers der rhetorische Kniff?","scenario":"Ein Verkäufer sagt: „Dieses C200-Globuli heilt deine Lungenentzündung.“ Eine Ärztin wendet ein, dass in C200-Globuli kein einziges Molekül des Wirkstoffs mehr enthalten ist und es keinen Wirksamkeitsnachweis gibt. Der Verkäufer antwortet: „Naja, Homöopathie ist eben ganzheitlich und regt die Selbstheilungskräfte an.“","options":["Er begründet die Wirkung der Globuli mit der Wirkung der Globuli und setzt damit voraus, was er zeigen will.","Er unterstellt der Ärztin eine Behauptung, die sie nie aufgestellt hat, und widerlegt dann diese.","Er zieht sich unter Kritik von der kühnen Heilbehauptung auf eine bescheidene, kaum widerlegbare Aussage zurück.","Er greift die Person der Ärztin an, statt auf ihre sachlichen Einwände einzugehen."],"correctIndex":2,"explanation":"Zuerst steht eine mutige, überprüfbare Behauptung im Raum: Die Globuli heilen eine Lungenentzündung. Sobald Kritik kommt, wechselt der Verkäufer zu einer weichen Aussage („ganzheitlich“, „regt Selbstheilungskräfte an“), die so vage ist, dass sie sich kaum widerlegen lässt. Die Kritik der Ärztin zielte aber auf die erste Behauptung, und die bleibt unbeantwortet. Ein Zirkelschluss liegt nicht vor, denn er begründet nichts mit sich selbst. Ein Strohmann scheidet aus, weil er der Ärztin nichts Falsches in den Mund legt. Ein Angriff auf die Person fehlt ebenfalls. Entscheidend ist der Rückzug von der kühnen auf die bescheidene Behauptung, die man auch „Motte-and-Bailey“ nennt: Hinter dem Rückzug steht die Hoffnung, dass das Publikum später wieder die große Behauptung im Kopf hat.","coreRule":"⚡ Erst die große Behauptung, bei Gegenwind der Rückzug auf eine bescheidene, kaum angreifbare Aussage.","beleg":"Werkstück F.2.2 (Die Anatomie der Täuschung: Motte-and-Bailey)","status":"entwurf","kurz":"Aus der kühnen, prüfbaren Heilbehauptung wird unter Kritik eine vage Aussage, die kaum zu widerlegen ist. Der Einwand der Ärztin zielte auf die erste Behauptung, und genau die bleibt unbeantwortet.","prueffrage":"Auf welche Behauptung bezog sich der Einwand der Ärztin, und beantwortet die Reaktion des Verkäufers genau diese?","rueckmeldung":[{"option":0,"text":"„Ganzheitlich“ und „Selbstheilungskräfte“ klingen, als würde die Wirkung nur mit anderen Worten wiederholt. Der Verkäufer begründet aber nichts mit sich selbst, er weicht auf eine vagere Aussage aus; eine Begründung, die im Kreis läuft, fehlt."},{"option":1,"text":"Ein Strohmann braucht eine verzerrte Fassung dessen, was die andere Seite gesagt hat. Die Ärztin wird aber weder falsch wiedergegeben noch widerlegt. Ihr Einwand wird schlicht übergangen."},{"option":3,"text":"Den Einwand zu übergehen, ist noch kein Angriff auf die Person. Der Verkäufer wertet die Ärztin weder ab noch greift er ihre Kompetenz oder ihre Motive an. Er wechselt das Thema und lässt die Sachfrage offen."}],"familie":"rueckzug-auf-harmloses","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Shackel, N. (2014): „Motte and Bailey Doctrines“. Practical Ethics, Oxford Uehiro Centre, 05.09.2014","oeffentlich":true,"url":"https://blog.uehiro.ox.ac.uk/2014/09/motte-and-bailey-doctrines/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Shackel, N. (2005): The Vacuity of Postmodernist Methodology. Metaphilosophy 36(3)","oeffentlich":false}],"thema":"Gesundheit"},{"id":"qx-f-044","clusterId":"F","werkstueckRef":"F.2.3","stufe":1,"question":"Ein Forscherteam will ein Tier aufspüren, dessen Existenz bisher unbelegt ist. Welches Vorhaben ist ein seriöser Versuch der Entdeckung und keine bloße Monsterjagd?","options":["Ein Team untersucht in einem kaum erforschten Waldgebiet Hinweise auf ein unbekanntes Tier und will das Tier selbst oder eindeutiges Probenmaterial beschaffen.","Ein Team sucht in einem gut erforschten Gebiet nach einem riesigen Wesen, von dem mehrere Augenzeugen berichten, und sammelt dort unscharfe Fotos und Fußspuren.","Ein Team sucht an einem vielbesuchten, gut kartierten See nach einem Wesen aus einer alten Legende und wertet jedes unerklärte Geräusch als Hinweis darauf.","Ein Team sucht in einem dicht besiedelten, gut erforschten Gebiet nach einem großen Tier, das seit Jahrzehnten keine eindeutige Spur hinterlassen hat, und stellt dafür Wärmebildkameras auf."],"correctIndex":0,"explanation":"Dass Gorilla, Okapi und Riesenkalmar einst als Legenden galten, zeigt nur, dass die Welt früher weniger erforscht war. Es sagt nichts darüber, ob ein bestimmtes Tier heute existiert. Entscheidend sind zwei Fragen: Wie plausibel ist die Behauptung nach dem bekannten biologischen Wissen, und wie gut sind die Beweise? Ein Vorhaben ist seriös, wenn es in wirklich unerforschtem Gebiet nach einem Tier mit plausiblen Hinweisen sucht und handfeste, prüfbare Belege anstrebt, etwa einen Kadaver, DNA oder klare Filmaufnahmen. In gut erforschten Gebieten ist eine unbemerkte, überlebensfähige Population eines großen Tieres ohne jede eindeutige Spur äußerst unwahrscheinlich. Die Wahrscheinlichkeit sinkt weiter, wenn man sich auf Augenzeugen, unscharfe Fotos und die Deutung jedes unerklärten Geräuschs stützt.","coreRule":"⚡ Nicht die Seltsamkeit des Tieres, sondern Plausibilität und Beweisqualität trennen Suche von Jagd.","beleg":"Werkstück F.2.3 (Die Konfrontation mit der Realität: Die legitime Grenzwissenschaft); Fn. gl-f-okapi, gl-f-kalmar","status":"entwurf","scenario":"Vier Teams planen Expeditionen. Alle berufen sich darauf, dass Gorilla, Okapi und Riesenkalmar einst als Legenden galten und später doch wissenschaftlich beschrieben wurden. Du sollst einschätzen, welches der Vorhaben auf dieser Grundlage tatsächlich eine Entdeckung erwarten lässt.","kurz":"Dass Gorilla und Okapi einst Legenden waren, zeigt nur, dass manche Gebiete wenig erforscht waren, nicht, dass jedes Legendentier existiert. Seriös ist die Suche, wo noch kaum jemand geforscht hat und prüfbare Belege wie Kadaver oder DNA das Ziel sind.","prueffrage":"Welche Spuren müsste ein großes Tier über Jahrzehnte hinterlassen, und wo hätte man sie längst finden müssen?","rueckmeldung":[{"option":1,"text":"Mehrere Augenzeugen klingen nach einem soliden Anfang. Ein riesiges Tier in einem gut erforschten Gebiet wäre aber sehr wahrscheinlich längst eindeutig nachgewiesen, und unscharfe Fotos oder Fußspuren lassen sich vielfach deuten."},{"option":2,"text":"Am See wirkt die Suche mit offenen Ohren gründlich. Wer aber jedes unerklärte Geräusch als Hinweis wertet, kann nicht mehr enttäuscht werden: Alles gilt als Bestätigung, nichts als Gegenbeleg, und das Gebiet ist zudem gut kartiert und viel besucht."},{"option":3,"text":"Wärmebildkameras klingen nach moderner, nachprüfbarer Technik. Das Gebiet ist aber dicht besiedelt und gut erforscht, seit Jahrzehnten fehlt jede eindeutige Spur. Ein unbemerktes großes Tier ist dort äußerst unwahrscheinlich, Technik hin oder her."}],"familie":"wissenschaft-abgrenzen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Tetrapod Zoology (tetzoo.com): „The Discovery of the Okapi, Part 1“ (2023)","oeffentlich":true,"url":"https://tetzoo.com/blog/2023/4/11/the-discovery-of-the-okapi-part-1","abruf":"2026-10-12"},{"typ":"doi","kurz":"Sykes, B. C. u. a. (2014): Genetic analysis of hair samples attributed to yeti, bigfoot and other anomalous primates. Proc. R. Soc. B 281, 20140161","oeffentlich":true,"doi":"10.1098/rspb.2014.0161","abruf":"2026-10-12"},{"typ":"url","kurz":"Traill, L. W. u. a. (2007): Minimum viable population size (Autorenfassung)","oeffentlich":true,"doi":"10.1016/j.biocon.2007.06.011","url":"https://conservationbytes.com/wp-content/uploads/2011/03/traill-et-al-2007-biol-conserv.pdf","abruf":"2026-10-12"}],"thema":"Natur und Klima"},{"id":"qx-f-045","clusterId":"F","werkstueckRef":"F.2.3","stufe":2,"question":"Jemand behauptet, im Loch Ness lebe eine Population riesiger Reptilien, die sich dort seit Generationen hält. Welche Überlegung spricht am stärksten dagegen?","options":["Räuber wiegen zusammen meist höchstens ein Zehntel ihrer Beute; auf eine überlebensfähige Gruppe verteilt, wäre jedes Tier viel zu klein.","Reptilien können im kalten Wasser nicht jagen; schon im ersten Winter würden sie erfrieren und der See wäre kein möglicher Lebensraum.","Sonarzählungen sind in tiefen Seen grundsätzlich unzuverlässig; deshalb bleibt die Futterfrage unentscheidbar und jede Rechnung offen.","Große Tiere fressen täglich so viel, wie der See an Fisch enthält; sie hätten den Fischbestand schon nach wenigen Tagen leergefressen."],"correctIndex":0,"explanation":"Die Behauptung lässt sich mit einer einfachen Bilanz prüfen: Akustische Schätzungen (Shine 1993) und Probennahmen ergaben rund 17 bis 24 Tonnen Fisch im freien Wasser des Sees. Nach einer ökologischen Faustregel macht die Masse aller Räuber zusammen davon meist höchstens etwa ein Zehntel aus, also rund zwei Tonnen. Eine Art braucht aber eine Mindestzahl von Tieren, um nicht auszusterben; bei etwa zehn Tieren käme jedes auf höchstens rund 200 Kilogramm Körpermasse, viel zu wenig für riesige Reptilien. Die übrigen Antworten ersetzen die Rechnung durch Behauptungen: ein Erfrieren im ersten Winter, eine pauschal unzuverlässige Messung oder einen erfundenen Tagesverbrauch des ganzen Fischbestands. Einschränkung: Die Zahl gilt nur für das freie Wasser, Uferzone, Bodenfische und Wanderfische sind nicht erfasst; sie ist eine Größenordnung, kein exakter Wert.","coreRule":"⚡ Prüfe Existenzbehauptungen mit einer Bilanz: Reicht die Nahrung für eine überlebensfähige Population?","beleg":"Werkstück F.2.3 (Verletzung der Ökologie & des Energiebedarfs); Fn. gl-f-nessie (Shine 1993, S. 271 f.; auch Loxton, Prothero 2013, S. 158 f.)","status":"entwurf","scenario":"In einem Gespräch über Loch Ness sagt jemand: „Der See ist riesig und tief, da kann sich locker eine Gruppe großer Reptilien verstecken.“ Du weißt: Im freien Wasser des Sees schwimmen nach Sonarzählungen und Probennahmen nur rund 17 bis 24 Tonnen Fisch.","quote":"","quoteLabel":"","kurz":"Bei 17 bis 24 Tonnen Fisch wiegen alle Räuber zusammen nach einer ökologischen Faustregel höchstens ein Zehntel davon, rund zwei Tonnen; auf zehn Tiere verteilt, je rund 200 Kilogramm, viel zu wenig für riesige Reptilien. Größe und Tiefe des Sees sagen über die Nahrung nichts.","prueffrage":"Welche Zahl über den See ist bekannt, und was lässt sich mit ihr nachrechnen?","rueckmeldung":[{"option":1,"text":"Kälte ist für viele Reptilien tatsächlich ein Problem, deshalb wirkt das Argument plausibel. „Können nicht jagen“ und „erfrieren im ersten Winter“ sind aber pauschale Behauptungen ohne Rechnung; tragfähiger ist die Nahrungsbilanz."},{"option":2,"text":"Die Zahl ist tatsächlich nur eine Größenordnung und gilt allein für das freie Wasser. Daraus folgt aber nicht, dass sie wertlos wäre: Auch eine grobe Schätzung lässt sich verwenden, während „unzuverlässig“ die Prüfung bloß verweigert."},{"option":3,"text":"Nahrung ist hier tatsächlich der entscheidende Punkt. Die Angabe, die Tiere fräßen täglich den ganzen Fischbestand, ist aber eine erfundene Größe ohne Rechnung und liegt weit über dem, was die Bilanz hergibt."}],"familie":"population-und-spuren","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Shine, A. J. (1993): Postscript: Surgeon or Sturgeon? Scottish Naturalist 105, S. 271–282 (Webfassung des Loch Ness Project)","oeffentlich":true,"url":"https://lochnessproject.org/ARCHIVE%20ROOM/papershtml/loch_ness_surgeon_sturgeon.htm","abruf":"2026-10-12"}],"thema":"Natur und Klima"},{"id":"qx-f-046","clusterId":"F","werkstueckRef":"F.2.3","stufe":3,"question":"Ein Forscherteam sammelt Haarproben, die Yeti, Bigfoot und ähnlichen Wesen zugeschrieben wurden, und analysiert sie genetisch. Von den Proben mit auswertbarer DNA stammt keine einzige von einem unbekannten Primaten; gefunden werden unter anderem Bär, Pferd, Kuh, Hund, Wolf, Kojote und ein Mensch. Ein Freund sagt: „Das ist der Beweis, dass es diese Wesen nicht gibt.“ Wie ordnest du das Ergebnis richtig ein?","options":["Die Studie widerlegt die Existenz solcher Wesen endgültig, denn eine Genanalyse ist der stärkste Beweis, den es überhaupt gibt.","Die Studie lässt die Existenz offen, denn eine Suche ohne Fund beweist keine Nichtexistenz, liefert aber auch keinen Beleg für die Behauptung.","Die Studie bestätigt einen unbekannten Primaten, denn Proben mit auswertbarer DNA reichen für einen sicheren Nachweis aus.","Die Studie sagt gar nichts aus, denn Haare enthalten grundsätzlich keine DNA, die sich auswerten ließe."],"correctIndex":1,"explanation":"Von den Proben mit auswertbarer DNA stammte keine von einem unbekannten Primaten. Das Ergebnis zeigt: Die untersuchten Haare, die Yetis oder Bigfoots zugeschrieben wurden, stammten von bekannten Tieren und einem Menschen. Eine endgültige Widerlegung ist das nicht, denn ein einzelnes Nichtfinden kann nie beweisen, dass etwas nirgends existiert; die Autoren der Studie sagten selbst, sie könne die Existenz unbekannter Primaten weder widerlegen noch belegen. Umgekehrt trägt die Behauptung die Beweislast, und bisher fehlt jeder tragfähige Beleg. Wer „kein Fund“ als „Beweis des Gegenteils“ liest, macht denselben Fehler wie jemand, der „nicht widerlegt“ als „bewiesen“ liest. Dass die Haare nicht auswertbar gewesen wären, stimmt ebenfalls nicht: Immerhin 30 Proben lieferten auswertbare DNA.","coreRule":"⚡ Gezielt gesucht, nichts gefunden: Das ist kein Beweis der Nichtexistenz, aber ein weiterer Mangel an Belegen für die Behauptung.","beleg":"Werkstück F.2.3 (Verletzung der Populationsbiologie); Fn. gl-f-sykes (Sykes u. a. 2014, Proc. R. Soc. B 281, S. 1--3)","status":"entwurf","scenario":"","kurz":"Eine Suche ohne Fund beweist nicht, dass etwas nirgends existiert, und liefert zugleich keinen Beleg für die Behauptung. Der naheliegende Fehler ist, „nicht gefunden“ als „widerlegt“ zu lesen.","prueffrage":"Was genau wurde untersucht, und was fand sich in den Proben mit auswertbarer DNA?","rueckmeldung":[{"option":0,"text":"Eine Genanalyse ist ein starkes Verfahren, sagt aber nur etwas über die untersuchten Proben. Dass keine von einem unbekannten Primaten stammt, schließt nicht aus, dass es irgendwo einen gibt; die Autoren selbst sprechen nicht von Widerlegung."},{"option":2,"text":"Auswertbare DNA ist nur die Voraussetzung dafür, eine Probe einer Art zuordnen zu können, kein Nachweis eines neuen Wesens. Hier ergab die Zuordnung ausschließlich bekannte Tiere und einen Menschen, also gerade keinen unbekannten Primaten."},{"option":3,"text":"Haare enthalten sehr wohl DNA: Immerhin 30 Proben lieferten auswertbare Ergebnisse. Nicht jede Probe war brauchbar, aber die auswertbaren zeigen etwas Handfestes, nämlich dass sie von bekannten Tieren und einem Menschen stammten."}],"familie":"unwissen-ist-kein-beleg","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Sykes, B. C.; Mullis, R. A.; Hagenmuller, C.; Melton, T. W.; Sartori, M. (2014): Genetic analysis of hair samples attributed to yeti, bigfoot and other anomalous primates. Proc. R. Soc. B 281(1789), 20140161 (CC BY, PMC4100498)","oeffentlich":true,"doi":"10.1098/rspb.2014.0161","abruf":"2026-10-12"}],"thema":"Natur und Klima"},{"id":"qx-f-047","clusterId":"F","werkstueckRef":"F.2.3","stufe":4,"question":"Ein Bigfoot-Fan sagt: „Der Gorilla galt lange als Mythos und existiert doch. Also kann es auch Bigfoot geben.“ Welche Antwort trifft den Denkfehler am besten?","options":["Der Gorilla-Fall zeigt nur, dass Entdeckungen möglich sind. Für das jetzt behauptete Tier liefert er keinen einzigen Beleg.","Der Gorilla-Fall zeigt, dass jede Legende einen wahren Kern hat. Bigfoot wird deshalb eines Tages gefunden werden.","Der Gorilla-Fall ist belanglos, weil bisher ungesichtete Tiere immer Fantasiegebilde sind. Entdeckungen gibt es nicht mehr.","Der Gorilla-Fall gilt nur für Landtiere, weil Meerestiere wie der Riesenkalmar einen strengeren Maßstab brauchen. Bigfoot bleibt offen."],"correctIndex":0,"explanation":"Der Fan schließt von „es gab Fälle, in denen eine Legende wahr war“ auf „also ist diese Legende wahr“. Das ist kein Beleg, sondern ein Präzedenzfall: Er zeigt nur, dass Entdeckungen möglich sind. Die Welt war damals unerforschter, und für das Okapi (1901 anhand von Fellstreifen beschrieben) und den Riesenkalmar (1857 anhand von Funden beschrieben) folgten handfeste Belege. Für Bigfoot fehlen solche Belege; gezielte DNA-Analysen angeblicher Haarproben ergaben 2014 nur bekannte Tiere, darunter Bären, Pferde, Kühe, Hunde und einen Menschen. Dazu kommt: Eine verborgene Population riesiger Primaten bräuchte Tausende Tiere, die in einer von Satelliten und Smartphones kartierten Welt keine eindeutigen Spuren hinterlassen. Dass früher manches unerforscht war, macht die Behauptung heute nicht wahrscheinlicher. Die Annahme, Entdeckungen gebe es nicht mehr, wäre allerdings ebenso falsch: Legitime Grenzwissenschaft sucht weiter, entscheidend ist die Qualität der Beweise für das konkrete Tier.","coreRule":"⚡ „Früher galt es auch als Mythos“ ersetzt keinen Beleg für das jetzt behauptete Tier.","beleg":"Werkstück F.2.3 (Abschluss-Diagnose des Pathologen)","status":"entwurf","scenario":"","kurz":"Der Gorilla-Fall zeigt nur, dass Entdeckungen möglich sind. Bei Gorilla, Okapi und Riesenkalmar gab es am Ende handfeste Funde, bei Bigfoot fehlen sie; der Fehler ist der Schluss von „mancher Mythos stimmte“ auf „dieser stimmt“.","prueffrage":"Was hat Fachleute am Ende vom Gorilla überzeugt, und gibt es für Bigfoot etwas Vergleichbares?","rueckmeldung":[{"option":1,"text":"Dass einige Legenden einen wahren Kern hatten, stimmt. Daraus folgt aber nicht, dass jede einen hat, und noch weniger, dass Bigfoot gefunden werden wird. Viele Legenden bleiben reine Erfindung."},{"option":2,"text":"Als Beleg für Bigfoot taugt der Gorilla-Fall tatsächlich nicht. Das Gegenteil trägt aber ebenso wenig: Neue Tierarten werden weiterhin entdeckt, und entscheidend ist, wie gut die Belege für das konkrete Tier sind."},{"option":3,"text":"Ob Land oder Meer, der Maßstab bleibt gleich: die Qualität der Belege. Beim Riesenkalmar gab es Funde, bei Bigfoot fehlen sie, und DNA-Proben ergaben nur bekannte Tiere. Offen ist die Frage nur insofern, als sie nicht logisch ausgeschlossen ist."}],"familie":"ablehnung-ist-kein-beleg","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Tetrapod Zoology (tetzoo.com): „The Discovery of the Okapi, Part 1“ (2023)","oeffentlich":true,"url":"https://tetzoo.com/blog/2023/4/11/the-discovery-of-the-okapi-part-1","abruf":"2026-10-12"},{"typ":"doi","kurz":"Kubodera, T.; Mori, K. (2005): First-ever observations of a live giant squid in the wild. Proc. R. Soc. B 272(1581), S. 2583–2586 (PMC1559985)","oeffentlich":true,"doi":"10.1098/rspb.2005.3158","abruf":"2026-10-12"},{"typ":"doi","kurz":"Sykes, B. C. u. a. (2014): Genetic analysis of hair samples attributed to yeti, bigfoot and other anomalous primates. Proc. R. Soc. B 281, 20140161","oeffentlich":true,"doi":"10.1098/rspb.2014.0161","abruf":"2026-10-12"}],"thema":"Natur und Klima"},{"id":"qx-f-048","clusterId":"F","werkstueckRef":"F.2.4","stufe":1,"question":"Eine Werbung für ein neues Buch lautet: „Millionen Leser können sich nicht irren – dieses Buch beweist, dass Außerirdische die Pyramiden gebaut haben!“ Was ist an dieser Argumentation fehlerhaft?","options":["Sie folgert aus der großen Verbreitung eines Buches, dass seine Behauptung belegt ist, obwohl Verkaufszahlen nichts über die Beweislage aussagen.","Sie verlangt, dass die Behauptung schon deshalb richtig sein muss, weil bisher niemand den Beweis erbracht hat, dass die Pyramiden von Menschen gebaut wurden.","Sie stützt sich auf ein einziges Buch als Quelle; würden mehrere Bücher dieselbe These vertreten, wäre die Behauptung damit belegt.","Sie schließt aus einem sehr alten Bauwerk, dass die damaligen Menschen es nicht errichtet haben können, weil ihnen die nötige Technik gefehlt habe."],"correctIndex":0,"explanation":"Verkaufszahlen messen Neugier, Marketing und Unterhaltungswert, nicht Wahrheit. Erich von Däniken etwa trug die Alien-Idee 1968 mit „Erinnerungen an die Zukunft“ zu einem Millionenpublikum (die englische Ausgabe verkaufte sich über sieben Millionen Mal), obwohl die Idee älter war und dadurch nicht besser belegt wurde. Ob eine Behauptung stimmt, entscheiden Belege und Methoden, nicht die Zahl derer, die sie gekauft, gehört oder geglaubt haben. Prüfe deshalb immer: Welche Beweise werden vorgelegt, und nicht: Wie viele glauben es?","coreRule":"⚡ Bekannt gemacht ist nicht bewiesen: Die Popularität einer Idee ist kein Beleg.","beleg":"Werkstück F.2.4 (Die Autopsie-Akte); Fn. gl-f-daeniken (Inselmann 2026, Skeptiker 1/2026, S. 25 und 27)","status":"entwurf","scenario":"","kurz":"Millionen Käufer zeigen nur, dass ein Buch Neugier weckt und sich gut verkauft, nicht dass seine These stimmt. Der Fehler liegt im Schluss von „viele glauben es“ auf „es ist belegt“: Ob etwas stimmt, entscheiden Belege und Methoden.","prueffrage":"Welche Belege nennt die Werbung selbst, und was davon sagt etwas über die Pyramiden?","rueckmeldung":[{"option":1,"text":"Die Beweislast so umzudrehen, wäre tatsächlich ein klassischer Fehlschluss. Die Werbung tut das aber nicht, sie beruft sich auf die Leserzahl. Außerdem ist der Bau der Pyramiden durch Menschen gut belegt."},{"option":2,"text":"Die Zahl der Quellen ist nicht der Kern: Auch viele Bücher mit derselben These belegen nichts, solange keines Beweise vorlegt. Die Werbung macht einen anderen Fehler, sie beruft sich auf die Zahl der Leser statt auf Belege."},{"option":3,"text":"Das „Es fehlte die Technik“-Argument kommt in Alien-Theorien oft vor, steht aber nicht in dieser Werbung, und es stimmt auch nicht: Die Ägypter besaßen die nötigen Werkzeuge und Organisation. Diese Werbung setzt auf Verkaufszahlen."}],"familie":"mehrheit-ist-kein-beleg","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Internet Encyclopedia of Philosophy: Fallacies, Art. „Appeal to the People“/„Bandwagon“","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"url","kurz":"Associated Press via NBC News (11.01.2026): „Erich von Däniken, Swiss writer who spawned alien archaeology, dies at 90“","oeffentlich":true,"url":"https://www.nbcnews.com/news/obituaries/erich-von-daniken-swiss-writer-spawned-alien-archaeology-dies-90-rcna253448","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Inselmann, L. (2026): Zurück zu den Sternen. Ein skeptischer Nachruf auf Erich von Däniken. Skeptiker 1/2026, S. 25–35","oeffentlich":false,"seite":"S. 27"}],"thema":"Netz und Medien"},{"id":"qx-f-049","clusterId":"F","werkstueckRef":"F.2.4","stufe":2,"question":"Welche Frage prüft die Deutung des Sprechers am besten?","scenario":"In einer Dokumentation wird eine Höhlenmalerei gezeigt: eine stilisierte Figur mit großem Kopfschmuck. Der Sprecher sagt: „Das ist ein Wesen im Raumanzug, kein Zweifel.“ Erhalten sind weder Beschriftungen noch Beigaben, die die Figur erklären.","options":["Wie sieht die Figur aus, wenn man sie mit heutigen Raumanzügen vergleicht, und wie ähnlich ist sie ihnen?","Welche Kopfbedeckungen und rituellen Gewänder gab es in der Kultur, die das Bild gemalt hat, und passt die Figur dazu?","Wie viele Menschen glauben heute, dass die Figur einen Raumanzug trägt, und wie überzeugt sind sie?","Welche Erklärung klingt für ein modernes Publikum am spannendsten, und welche lässt sich am besten erzählen?"],"correctIndex":1,"explanation":"Der Sprecher liest ein sehr altes Bild durch die Brille der Gegenwart: Weil wir Raumanzüge kennen, sehen wir sie auch dort, wo ein Kopfschmuck zu sehen ist. Das ist Präsentismus. Die Deutung gewinnt nicht dadurch an Gewicht, dass sie dem heutigen Auge naheliegt. Entscheidend ist, was für die Entstehungszeit und den kulturellen Rahmen des Bildes belegt ist. In vielen frühen Kulturen gehören Kopfschmuck und Masken zu Ritualen, und eine Figur mit auffälligem Kopfschmuck passt deshalb wahrscheinlich zu einer Person in ritueller Kleidung, etwa einem Schamanen. Die beste Prüffrage fragt daher nach dem Kontext des Bildes und nicht nach heutigen Vergleichen, Meinungen oder Wirkung.","coreRule":"⚡ Wer ein altes Bild deuten will, fragt zuerst nach dem Kontext seiner Zeit, nicht nach der Ähnlichkeit zu heutiger Technik.","beleg":"Werkstück F.2.4 (Verletzung der Kunstgeschichte & Religionswissenschaft)","status":"entwurf","quote":"","quoteLabel":"","kurz":"Entscheidend ist, was für die Entstehungszeit und den kulturellen Rahmen des Bildes belegt ist. Wer den Kopfschmuck durch die Brille heutiger Raumanzüge liest, sieht, was er kennt; in vielen frühen Kulturen gehörten Kopfschmuck und Masken dagegen zu Ritualen.","prueffrage":"Was ist von dem Bild selbst erhalten, und was fügt der Sprecher aus eigenem Wissen hinzu?","rueckmeldung":[{"option":0,"text":"Ein Vergleich mit heutigen Anzügen zeigt höchstens, dass die Figur zur Deutung passen könnte. Er sagt nichts darüber, was der Maler meinte, denn der Maßstab bleibt unsere Gegenwart statt seiner Zeit."},{"option":2,"text":"Wie viele Menschen eine Deutung überzeugend finden, sagt etwas über ihre Verbreitung, nicht über ihre Richtigkeit. Eine Deutung wird nicht dadurch besser, dass viele sie teilen oder sie dem heutigen Auge naheliegt."},{"option":3,"text":"Eine Erklärung kann spannend und gut erzählbar sein und trotzdem falsch liegen. Das misst die Wirkung auf ein Publikum, nicht, was für das Bild und seine Entstehungszeit belegt ist."}],"familie":"aus-ihrer-lage-urteilen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Colavito, J.: „Faking Ancient Art in Uzbekistan“ (jasoncolavito.com)","oeffentlich":true,"url":"https://www.jasoncolavito.com/faking-ancient-art-in-uzbekistan.html","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft"},{"id":"qx-f-050","clusterId":"F","werkstueckRef":"F.2.4","stufe":3,"question":"Eine Doku-Reihe fragt in jeder Folge neu: „Was, wenn die Götter in Wahrheit Astronauten waren?“ Eine Zuschauerin sagt: „Die behaupten ja gar nichts, die fragen nur. Da kann man ihnen nichts vorwerfen.“ Was ist an dieser Verteidigung fehlerhaft?","options":["Wer nur fragt, legt eine Antwort nahe, ohne sie zu behaupten, und umgeht so die Pflicht, sie zu belegen.","Eine offene Frage lässt jedem Zuschauer die Prüfung selbst und ist deshalb die sauberste Form einer Hypothese.","Wer nichts behauptet, kann auch nichts Falsches sagen, und deshalb bleibt eine Frage immer frei von Fehlschlüssen.","Eine Frage verlagert die Beweislast auf die Kritiker, weil diese das Gegenteil zeigen müssen, um sie zu entkräften."],"correctIndex":0,"explanation":"Eine Suggestivfrage wie „Was, wenn die Götter in Wahrheit Astronauten waren?“ stellt keine beweisbare Behauptung auf, legt aber eine bestimmte Antwort nahe. Das erzeugt ein Gefühl des Mysteriums, und weil nichts Konkretes behauptet wird, muss auch nichts belegt werden. Die Beweislast liegt jedoch bei dem, der eine außergewöhnliche Deutung nahelegt, nicht bei denen, die sie bezweifeln. Wer nur fragt, entzieht sich der Prüfung und bekommt trotzdem die Wirkung einer Behauptung. Ein Test: Formuliere die Frage als Aussage um („Die Götter waren Astronauten“). Wenn du dann Belege verlangen würdest, gilt das auch für die Frageform.","coreRule":"⚡ Wer nur fragt, scheint nichts zu behaupten und umgeht so die Beweislast: Das ist die Wirkung der Suggestivfrage.","beleg":"Werkstück F.2.4 (Die Anatomie der Täuschung: „Ich stelle ja nur Fragen“)","status":"entwurf","scenario":"","kurz":"Eine Suggestivfrage behauptet nichts Konkretes und legt trotzdem eine bestimmte Antwort nahe. So entsteht die Wirkung einer Behauptung, ohne dass jemand Belege liefern muss. Der Fehler liegt darin, dass die Frageform vor der Prüfung schützt.","prueffrage":"Welchen Eindruck hinterlässt die Frage bei dir, und was bliebe von ihr übrig, wenn du sie als bloße Aussage lesen würdest?","rueckmeldung":[{"option":1,"text":"Eine echte Hypothese ist so formuliert, dass man sie prüfen kann. Die Frage hier lenkt dagegen auf eine bestimmte Antwort, ohne sich festzulegen, und entgeht damit genau der Prüfung, die eine Hypothese braucht."},{"option":2,"text":"Wer nichts behauptet, sagt in der Tat nichts Falsches. Doch die Suggestivfrage erzielt die Wirkung einer Behauptung und umgeht den Beleg. Deshalb bleibt sie keineswegs immer frei von Fehlschlüssen."},{"option":3,"text":"Wer eine Frage nicht widerlegen kann, scheint im Nachteil. Die Beweislast trägt aber, wer eine außergewöhnliche Deutung nahelegt; Kritiker müssen das Gegenteil nicht zeigen, um die Deutung anzuzweifeln."}],"familie":"beweislast-klaeren","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Internet Encyclopedia of Philosophy: Fallacies, Art. „Loaded Question“, „Complex Question“ und „Burden of Proof“","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Netz und Medien"},{"id":"qx-f-051","clusterId":"F","werkstueckRef":"F.3.1","stufe":1,"question":"Der Heilpraktiker sagt: „Krebs ist keine Fehlfunktion des Körpers, sondern ein sinnvolles Programm, das durch einen seelischen Schock ausgelöst wird. Eine Chemotherapie stört diesen Heilungsprozess und ist die eigentliche Todesursache.“ Welcher Einwand trifft den Kern dieser Behauptung am besten?","options":["Krebs entsteht aus mutierten körpereigenen Zellen, die unkontrolliert wachsen und ohne Behandlung zum Tod führen können.","Krebs entsteht vor allem durch ein geschwächtes Immunsystem, das sich mit Stärkungsmitteln wieder aufbauen lässt.","Krebs entsteht durch Giftstoffe, die sich im Körper ansammeln und durch eine Entgiftungskur wieder ausgeschieden werden.","Krebs entsteht allein durch erbliche Veranlagung, sodass seelische Erlebnisse und Behandlungen daran nichts ändern können."],"correctIndex":0,"explanation":"Die Behauptung deutet eine zerstörerische Krankheit in einen „sinnvollen“ Vorgang um, ohne einen zellbiologischen Mechanismus anzugeben. Krebs ist unkontrolliertes Wachstum mutierter körpereigener Zellen, das Gewebe zerstört und den Organismus ohne Behandlung töten kann. Dass ein Tumor „Sinn“ hätte, ist eine Zuschreibung, kein Befund. Dazu kommt: Wird die Behandlung für den Tod verantwortlich gemacht, kann die Aussage nie scheitern. Wer geheilt wird, bestätigt sie; wer stirbt, hat den „Konflikt nicht gelöst“, einen „Folgekonflikt“ erlitten oder wurde durch die „panikmachende Schulmedizin“ getötet. Eine Aussage, die durch kein denkbares Ergebnis widerlegt werden kann, sagt nichts über die Welt aus.","coreRule":"⚡ Wer eine tödliche Krankheit zum „sinnvollen Programm“ erklärt, braucht einen prüfbaren Mechanismus; ohne ihn ist es eine Umdeutung, keine Erklärung.","beleg":"Werkstück F.3.1 (Die Kern-Behauptung; Verletzung der Onkologie & Zellbiologie; Falsifizierbarkeit)","status":"entwurf","scenario":"Eine Bekannte erzählt dir, ihr Onkel habe eine Krebsdiagnose bekommen. Er wolle die Operation absagen, weil ihm ein Heilpraktiker eine ungewöhnliche Erklärung gegeben habe.","kurz":"Der Einwand benennt, was Krebs tatsächlich ist: unkontrolliert wachsende, mutierte körpereigene Zellen, die ohne Behandlung töten können. Der „Sinn“ des Tumors wird nur behauptet, ein Mechanismus fehlt, und die Aussage kann durch keinen Ausgang scheitern.","prueffrage":"Woran sterben Menschen mit Krebs, die nie eine Chemotherapie bekommen haben?","rueckmeldung":[{"option":1,"text":"Das Immunsystem spielt bei der Krebsabwehr tatsächlich eine Rolle. Als Hauptursache taugt es aber nicht: Krebs geht auf Mutationen in Körperzellen zurück, und dass Stärkungsmittel ihn heilen, ist nicht belegt."},{"option":2,"text":"Einzelne Schadstoffe wie Tabakrauch erhöhen das Krebsrisiko, das stimmt. Sie schädigen aber das Erbgut von Zellen, und diese wachsen weiter, auch wenn der Stoff längst fort ist; eine Entgiftungskur heilt keinen Krebs."},{"option":3,"text":"Erbliche Veranlagung spielt bei manchen Krebsarten tatsächlich eine Rolle, doch nur ein kleiner Teil der Fälle ist überwiegend erblich. Dass Behandlungen nichts ändern, stimmt nicht: Viele Krebserkrankungen werden geheilt oder gebremst."}],"familie":"mechanismus-verlangen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"National Cancer Institute: „What Is Cancer?“","oeffentlich":true,"url":"https://www.cancer.gov/about-cancer/understanding/what-is-cancer","abruf":"2026-10-12"},{"typ":"url","kurz":"AG Prävention und Integrative Onkologie (PRiO) in der Deutschen Krebsgesellschaft: Stellungnahme „Germanische Neue Medizin® nach Dr. Hamer“, Stand 30.04.2026","oeffentlich":true,"url":"https://prio-dkg.de/stellungnahmen/germanische-neue-medizin/","abruf":"2026-10-12"},{"typ":"url","kurz":"Psiram: Art. „Germanische Neue Medizin“","oeffentlich":true,"url":"https://www.psiram.com/de/index.php/Germanische_Neue_Medizin","abruf":"2026-10-12"}],"thema":"Gesundheit"},{"id":"qx-f-052","clusterId":"F","werkstueckRef":"F.3.1","stufe":2,"question":"Was ist an dieser Argumentation der entscheidende Fehler?","options":["Jedes denkbare Ergebnis wird zugunsten der Lehre gedeutet, daher kann nichts sie widerlegen und sie ist nicht prüfbar.","Nur gute Ausgänge werden als Beleg gezählt, schlechte werden ausgeblendet, daher fehlt eine Erklärung für die Todesfälle.","Gesundung und Tod werden dem Zufall zugeschrieben, daher gibt es keinen erkennbaren Zusammenhang mit der Behandlung.","Seelische Konflikte lassen sich nicht messen, daher muss man der Lehre bis zum Beweis des Gegenteils vertrauen."],"correctIndex":0,"explanation":"Eine Aussage ist nur dann prüfbar, wenn es ein denkbares Ergebnis gibt, das sie widerlegen würde. Hier wird jeder Ausgang eingebaut: Heilung bestätigt die Lehre, Tod wird dem Patienten („Konflikt nicht gelöst“, „Folgekonflikt“) oder der Schulmedizin („von der Schulmedizin getötet“) angelastet. Ein solches System kann nie scheitern, und gerade deshalb sagt es nichts darüber, ob es stimmt. Im Ernstfall ist das gefährlich, denn bei ernsten Erkrankungen wie Krebs bedeutet der Verzicht auf wirksame Behandlung ein hohes Todesrisiko. Wer prüfen will, fragt: „Welches Ergebnis würde dich überzeugen, dass die Lehre falsch ist?“ Kommt darauf keine Antwort, ist die Lehre keine Erkenntnis, sondern ein Glaubenssystem.","coreRule":"⚡ Wenn jeder Ausgang die Lehre bestätigt, ist sie nicht prüfbar, und im Ernstfall gefährlich.","beleg":"Werkstück F.3.1 (Die Konfrontation mit der Realität: Falsifizierbarkeit)","status":"entwurf","scenario":"Ein Bekannter will einer todkranken Verwandten eine „Konflikt-Heillehre“ empfehlen und verteidigt sie so: „Wenn jemand nach der Behandlung gesund wird, beweist das die Lehre. Stirbt jemand, hat er seinen Konflikt nicht gelöst, einen Folgekonflikt erlitten oder wurde von der Schulmedizin getötet. Die Lehre irrt also nie.“","kurz":"Eine Lehre, die Heilung wie Tod zu ihren Gunsten deutet, kann nie scheitern, und darum sagt ihr scheinbarer Erfolg nichts darüber, ob sie stimmt. Der Fehler liegt darin, jeden Ausgang als Bestätigung zu zählen, obwohl keiner die Lehre widerlegen könnte.","prueffrage":"Wie erklärt die Argumentation die Todesfälle, und wem gibt sie dabei jeweils die Schuld?","rueckmeldung":[{"option":1,"text":"Dass nur gute Ausgänge zählen, trifft so nicht zu: Die Todesfälle werden hier ja erklärt, nur eben immer zugunsten der Lehre. Gerade diese Umdeutung macht die Lehre unwiderlegbar, nicht ein Weglassen von Fällen."},{"option":2,"text":"Hier wird nichts dem Zufall zugeschrieben. Im Gegenteil: Gesundung wie Tod werden als Folge der Lehre gedeutet. Der Mangel liegt darin, dass kein denkbarer Ausgang diesen Zusammenhang je infrage stellen könnte."},{"option":3,"text":"Dass sich seelische Konflikte schwer messen lassen, macht die Lehre nicht wahrscheinlicher. Wer eine Wirkung behauptet, muss auch sagen, was sie widerlegen würde. Bei einer schweren Erkrankung ist blindes Vertrauen zudem riskant."}],"familie":"immunisierung-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: Karl Popper (Abschn. 2)","oeffentlich":true,"url":"https://plato.stanford.edu/entries/popper/","abruf":"2026-10-12"},{"typ":"url","kurz":"Psiram: Art. „Germanische Neue Medizin“","oeffentlich":true,"url":"https://www.psiram.com/de/index.php/Germanische_Neue_Medizin","abruf":"2026-10-12"},{"typ":"url","kurz":"AG PRiO in der Deutschen Krebsgesellschaft: Stellungnahme „Germanische Neue Medizin® nach Dr. Hamer“, Stand 30.04.2026","oeffentlich":true,"url":"https://prio-dkg.de/stellungnahmen/germanische-neue-medizin/","abruf":"2026-10-12"}],"thema":"Gesundheit"},{"id":"qx-f-053","clusterId":"F","werkstueckRef":"F.3.1","stufe":3,"question":"Was sind die Ringe, und was folgt daraus für die Behauptung des Heilers?","options":["Sie sind echte Veränderungen im Gehirn, die keinen Rückschluss auf den Ort des Tumors erlauben, und damit ist die Behauptung widerlegt.","Sie sind echte Veränderungen im Gehirn, deren Deutung unter Fachleuten offen ist, und damit bleibt die Behauptung eine ernst zu nehmende Möglichkeit.","Sie sind Zeichen früherer Entzündungen im Gehirn, die der Heiler fälschlich als Konfliktspuren deutet, und damit ist die Behauptung widerlegt.","Sie sind Artefakte der Aufnahmetechnik, die das CT-Gerät selbst erzeugt, und damit trägt ihr bloßes Sichtbarsein die Behauptung nicht."],"correctIndex":3,"explanation":"Dass etwas auf einem Bild sichtbar ist, heißt noch nicht, dass es eine Eigenschaft des Patienten abbildet. Bildgebende Verfahren können selbst Strukturen erzeugen, die es im Körper gar nicht gibt. Bei diesen Ringen ist das der Fall: Radiologen kennen sie seit Langem als Ringartefakte, die die Computertomographie selbst erzeugt und die keine medizinische Bedeutung haben (so beschreibt es etwa Prang 2014). Wer aus ihnen Konflikttyp und Tumorort ablesen will, schließt aus einem Fehler der Technik auf eine Eigenschaft des Patienten. Die richtige Prüffrage lautet deshalb, ob die Struktur überhaupt eine Eigenschaft des Patienten zeigt oder eine des Messgeräts, und nicht, ob sie echt aussieht. Die anderen Antworten erfinden Befunde im Gehirn (Veränderungen, frühere Entzündungen) oder behaupten eine offene Deutung, während die Ringe von der CT-Technik selbst erzeugt werden und keine medizinische Bedeutung haben.","coreRule":"⚡ Was auf dem Bild wie ein Befund aussieht, kann ein Artefakt der Technik sein.","beleg":"Werkstück F.3.1 (Verletzung der Neurologie); Fn. gl-f-hamerherde (Prang 2014, Kap. „Germanische Neue Medizin“)","status":"entwurf","scenario":"Ein Heiler behauptet, er könne auf Gehirn-CT-Bildern an ringförmigen Strukturen („Herden“) erkennen, welchen seelischen Konflikt ein Patient hatte und wo im Körper sein Tumor sitzt. Als Beleg zeigt er dir mehrere Bilder, auf denen solche Ringe deutlich zu sehen sind. Die Ringe selbst sind unstrittig vorhanden.","kurz":"Dass etwas auf einem Bild sichtbar ist, zeigt noch nicht, dass es zum Patienten gehört. Die Ringe erzeugt die CT-Technik selbst, als Ringartefakte ohne medizinische Bedeutung, daher lässt sich aus ihnen weder Konflikt noch Tumorort ablesen.","prueffrage":"Wofür halten Fachleute, die täglich CT-Bilder auswerten, solche Ringe?","rueckmeldung":[{"option":0,"text":"Dass die Ringe nichts über den Tumorort verraten, ist richtig. Sie sind aber keine Veränderungen im Gehirn, sondern entstehen durch die Aufnahmetechnik. Eine Behauptung ist außerdem nicht schon deshalb widerlegt, weil ihr Beleg nicht trägt."},{"option":1,"text":"Ein deutlich sichtbarer Befund wirkt, als müsse er etwas bedeuten, und eine offene Fachfrage klingt vorsichtig. Hier gibt es aber keine: Die Ringe stammen vom CT-Gerät selbst und gelten unter Radiologen seit Langem als bedeutungslos."},{"option":2,"text":"Die Ringe wirken wie Spuren im Gehirn, weil man Strukturen auf Bildern gern als Befund liest. Sie entstehen aber durch die CT-Technik: Der Heiler deutet sie falsch, doch der Grund liegt im Gerät, nicht in früheren Entzündungen."}],"familie":"bild-und-video-pruefen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Dawes, L.; Ismail, M.; Murphy, A. u. a.: „Ring artifact“. Radiopaedia.org (rID 1988)","oeffentlich":true,"url":"https://radiopaedia.org/articles/ring-artifact","abruf":"2026-10-12"},{"typ":"url","kurz":"Psiram: Art. „Germanische Neue Medizin“ (Abschnitt Hamer-Herde)","oeffentlich":true,"url":"https://www.psiram.com/de/index.php/Germanische_Neue_Medizin","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Prang, M. (2014): Alternativmedizin: Was sie leistet. Wann sie schadet. München: C. H. Beck, Kap. „Germanische Neue Medizin“","oeffentlich":false}],"thema":"Gesundheit"},{"id":"qx-f-054","clusterId":"F","werkstueckRef":"F.3.1","stufe":4,"question":"Ein Anbieter wirbt für die „5 Biologischen Naturgesetze“ und versichert: „Mit der Germanischen Neuen Medizin hat das nichts zu tun.“ Auf Nachfrage zählt er als „Gesetze“ dieselben Behauptungen auf wie die Germanische Neue Medizin: Jede Krankheit gehe auf einen seelischen Schock-Konflikt zurück, Tumore seien „sinnvolle Programme“, Chemotherapie störe die Heilung. Was folgt daraus für die Beurteilung des Angebots?","options":["Die Lehre ist inhaltlich dieselbe geblieben, denn dieselben Behauptungen unter neuem Namen sind weiterhin dieselbe Lehre mit denselben Problemen.","Die Lehre gilt als überholt, denn eine umbenannte Variante hat die früheren Fehler offenbar schon korrigiert und verbessert.","Die Lehre muss nun neu und unabhängig bewertet werden, denn ein neuer Name verlangt auch eine neue wissenschaftliche Begründung.","Die Lehre ist kein Problem mehr, denn der Gründer ist tot und eine Lehre ohne ihren Gründer wird kaum noch verbreitet."],"correctIndex":0,"explanation":"Ob eine Behauptung stimmt, hängt von ihrem Inhalt und ihren Belegen ab, nicht von ihrem Etikett. Wer dieselben Kernthesen unter neuem Namen anbietet, bietet dieselbe Lehre an. Hamers Lehre wird seit seinem Tod (2017) unter mehreren Namen weitergeführt, etwa als „5 Biologische Naturgesetze“ oder in der „Meta-Medizin“, die Hamers fünf „Gesetze“ übernimmt. Die Bezeichnung „5 Biologische Naturgesetze“ vermeidet dabei gerade den belasteten Begriff „Germanisch“. Die Lehre wurde also weitergeführt, nicht korrigiert: Die Kernthesen bleiben dieselben, also bleiben auch die Probleme. Auch dass der Gründer gestorben ist, ändert nichts an Verbreitung und Gefahr: Die Lehre kursiert weiter über Messenger und soziale Medien. Der richtige Prüfschritt ist deshalb, die Inhalte mit der bekannten Lehre zu vergleichen und nach unabhängigen Belegen zu fragen, nicht dem Namen zu glauben.","coreRule":"⚡ Prüfe die Lehre, nicht das Etikett: Umbenennen ersetzt keine Belege.","beleg":"Werkstück F.3.1 (Die Autopsie-Akte); Fn. gl-f-14 (Psiram; Apotheken Umschau, abgerufen 23.09.2026)","status":"entwurf","scenario":"Du stößt in einer Messenger-Gruppe auf einen Anbieter, der „5 Biologische Naturgesetze“ als neue Heilmethode bewirbt. Der Name klingt neutral. Auf die Frage nach dem Ursprung sagt er nur, mit der Germanischen Neuen Medizin habe das nichts zu tun.","kurz":"Ein neuer Name ändert die Behauptungen nicht: Entscheidend sind Inhalt und Belege. Wer dieselben Kernthesen unter anderem Etikett anbietet, bietet dieselbe Lehre an, mit denselben Problemen, nicht eine verbesserte oder neue.","prueffrage":"Welche Behauptungen stehen hinter dem Namen, und wo hast du sie schon einmal gelesen?","rueckmeldung":[{"option":1,"text":"Dass sich der Name geändert hat, wirkt wie ein Neuanfang. Geändert hat sich aber nur das Etikett: Die Kernthesen sind dieselben geblieben, also wurde nichts korrigiert, sondern nur der belastete Begriff „Germanisch“ vermieden."},{"option":2,"text":"Daran stimmt: Eine Behauptung braucht Belege, egal wie sie heißt. Aber es ist keine neue Lehre, denn die Kernthesen sind dieselben. Für sie gelten damit auch die bekannten Probleme, und die Prüfung beginnt nicht bei null."},{"option":3,"text":"Der Tod des Gründers lässt eine Lehre leicht erledigt wirken. Sie wird aber unter neuen Namen weitergeführt und kursiert weiter über Messenger und soziale Medien, wie hier in der Gruppe. Verbreitung und Gefahr bestehen damit fort."}],"familie":"wertende-woerter-abziehen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Psiram: Art. „Germanische Neue Medizin“ (Synonyme „fünf biologische Naturgesetze (5bn/5BN)“, „Germanische Heilkunde“)","oeffentlich":true,"url":"https://www.psiram.com/de/index.php/Germanische_Neue_Medizin","abruf":"2026-10-12"},{"typ":"url","kurz":"Psiram: Art. „Metamedizin“","oeffentlich":true,"url":"https://www.psiram.com/de/index.php/Metamedizin","abruf":"2026-10-12"}],"thema":"Gesundheit"},{"id":"qx-f-055","clusterId":"F","werkstueckRef":"F.4.1","stufe":1,"question":"Eine Freundin erzählt: „Ich glaube an Karma und Reinkarnation, lege aber auch meine Tarotkarten, trage Heilsteine, meditiere zum ‚inneren Kind‘ und glaube an die Kraft der Schwingungen. Eine feste Gemeinschaft oder verbindliche Regeln brauche ich nicht.“ Welche Schlussfolgerung zieht man daraus am sinnvollsten?","options":["Ihre Weltanschauung ist eine selbst zusammengestellte Mischung aus Versatzstücken verschiedener Quellen.","Ihre Weltanschauung ist eine feste Lehre mit verbindlichen Dogmen, die von einer zentralen Organisation vorgegeben wird.","Ihre Weltanschauung ist ein geschlossenes System, das alle Fragen beantwortet und keine eigene Auswahl zulässt.","Ihre Weltanschauung ist das Ergebnis einer systematischen Prüfung, bei der nur die bestätigten Teile übrig blieben."],"correctIndex":0,"explanation":"Karma und Reinkarnation stammen aus indischen Religionen wie Hinduismus und Buddhismus, das „innere Kind“ aus der Psychologie, Kristallheilung (Heilsteine) gehört zu den Pseudowissenschaften. Die Freundin kombiniert solche Versatzstücke nach eigenem Geschmack, ohne feste Dogmen, ohne Gemeinschaft und ohne verbindliche Regeln – ein Baukasten, aus dem man sich wie in einem Supermarkt bedient. Die Elemente werden dabei häufig aus ihrem ursprünglichen Zusammenhang gelöst: Karma etwa gehört in diesen Religionen in einen strengen ethischen Zusammenhang, der hier wegfällt. Von einer systematischen Prüfung erzählt sie nichts; in solchen selbst zusammengestellten Weltanschauungen gilt oft das eigene Erleben als Maßstab, nicht überprüfbare Evidenz. Dass sich etwas stimmig anfühlt, ist aber kein Test, ob es stimmt.","coreRule":"⚡ Wer sich seine Weltanschauung aus Fertigteilen zusammenbaut, entscheidet nach Gefühl und Geschmack. Dass die Teile zusammenpassen, heißt nicht, dass sie stimmen.","beleg":"Werkstück F.4.1 (Die Anatomie der Lehre: Das Baukasten-Prinzip)","status":"entwurf","scenario":"","kurz":"Die Freundin kombiniert Elemente aus indischen Religionen, Psychologie und Esoterik nach eigenem Geschmack, ohne Dogmen, Gemeinschaft oder Regeln. Das ist ein selbst gebauter Baukasten; dass sich etwas stimmig anfühlt, ist noch keine Prüfung, ob es stimmt.","prueffrage":"Was sagt die Freundin über Regeln und Gemeinschaft, und was verbindet Tarot, Heilsteine und Karma miteinander?","rueckmeldung":[{"option":1,"text":"Eine Weltanschauung wirkt schnell wie eine feste Lehre mit Regeln und einer Instanz dahinter. Die Freundin sagt aber ausdrücklich, dass sie weder feste Gemeinschaft noch verbindliche Regeln braucht; niemand gibt ihr etwas vor."},{"option":2,"text":"Ein Gemisch aus vielen Praktiken kann sich anfühlen, als hätte es auf alles eine Antwort. Entscheidend ist aber, dass sie die Teile selbst auswählt und kombiniert. Ein geschlossenes System ohne eigene Auswahl ist das Gegenteil davon."},{"option":3,"text":"Wer vieles ausprobiert und behält, was sich bewährt, wirkt wie jemand, der geprüft hat. Von einer Prüfung erzählt die Freundin aber nichts, und für Heilsteine fehlt jeder Wirksamkeitsnachweis."}],"familie":"immunisierung-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Universität Münster, Exzellenzcluster Religion und Politik (2012): Pressemitteilung „Wenn Familien zweimal Weihnachten feiern – Mehr als ein Fünftel der Deutschen pflegen Patchwork-Religiosität“ (Christel Gärtner)","oeffentlich":true,"url":"https://www.uni-muenster.de/imperia/md/content/religion_und_politik/aktuelles/2012/12_2012/pm_patchwork-religiositaet.pdf","abruf":"2026-10-12"},{"typ":"url","kurz":"Hansson, S. O. (2008/2025): „Science and Pseudo-Science“, Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","seite":"Abschnitt 1, 4.3","abruf":"2026-10-12"}],"thema":"Psychologie"},{"id":"qx-f-056","clusterId":"F","werkstueckRef":"F.4.1","stufe":2,"question":"Ein Verkäufer entgegnet auf Kritik an seinen Heilsteinen: „Das ist nur deine materialistische Sichtweise, du bist für höhere Wahrheiten nicht offen.“ Was bewirkt diese Antwort für die Prüfbarkeit seiner Behauptung?","scenario":"Du äußerst an einem Stand auf einer Esoterikmesse Zweifel an der Wirkung von Heilsteinen.","options":["Sie widerlegt die Kritik, weil sie einen Gegenbeweis anführt, den Skeptiker bisher nicht kannten.","Sie macht die Behauptung unangreifbar, weil jede Kritik als mangelnde Offenheit abgetan werden kann.","Sie macht die Behauptung prüfbar, weil sie den Skeptiker einlädt, die höhere Ebene selbst zu untersuchen.","Sie klärt den Streit, weil sie ausdrücklich nur den Bereich des Glaubens betrifft und nichts behauptet."],"correctIndex":1,"explanation":"Der Verkäufer behauptet, Heilsteine wirkten. Auf die Kritik antwortet er nicht mit einem Beleg, sondern mit einem Urteil über den Kritiker: Wer zweifelt, sei „nicht offen“. So lässt sich jede wissenschaftliche Kritik abwehren; die Behauptung wird unangreifbar und unfalsifizierbar. Entscheidend ist hier nur der Mechanismus: Kritik wird durch Immunisierung statt durch Belege beantwortet.","coreRule":"⚡ Wenn nur das eigene Gefühl zählt, kann kein Gegenbeweis zählen.","beleg":"Werkstück F.4.1 (Die epistemologische Grundlage: Absolute Subjektivität)","status":"entwurf","kurz":"Der Verkäufer antwortet mit einem Urteil über den Kritiker statt mit einem Beleg: Wer zweifelt, sei „nicht offen“. So lässt sich jede Kritik abwehren, und die Behauptung wird unwiderlegbar. Der Vorwurf wirkt wie ein Argument, ersetzt aber die Prüfung.","prueffrage":"Worüber spricht der Verkäufer in seiner Antwort: über die Steine oder über die Person, die zweifelt?","rueckmeldung":[{"option":0,"text":"Die Antwort klingt selbstsicher, als stünde ein Wissen dahinter, das Skeptikern fehlt. Tatsächlich führt der Verkäufer aber keinen Beleg an, sondern spricht nur über den Kritiker. Ohne Gegenbeweis ist nichts widerlegt."},{"option":2,"text":"Hier klingt „Offenheit“ nach Prüfung. Eine echte Einladung zum Untersuchen würde aber Methode und Kriterien nennen, an denen sich ein Misserfolg erkennen ließe. Davon fehlt jede Spur, der Zweifel wird nur als mangelnde Offenheit abgetan."},{"option":3,"text":"Dass es um Glauben gehe, klingt nach einem friedlichen Ausweg. Die Behauptung über die Heilsteine betrifft aber die Wirklichkeit, nicht bloß den Glauben, und seine Entgegnung klärt den Streit nicht, sondern entzieht sie der Kritik."}],"familie":"immunisierung-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Hansson, S. O. (2008/2025): „Science and Pseudo-Science“, Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","seite":"Abschnitt 1, 4.3, 5.1","abruf":"2026-10-12"}],"thema":"Gesundheit"},{"id":"qx-f-057","clusterId":"F","werkstueckRef":"F.4.1","stufe":3,"question":"Eine Bekannte erzählt dir, ihre Schwester habe ihre Krebstherapie abgebrochen und setze nun nur noch auf Energiearbeit und Kristalle. Die Bekannte meint: „Esoterik ist doch eine harmlose Quelle von Trost, jeder darf glauben, was er will.“ Was ist an dieser Einschätzung für den vorliegenden Fall am ehesten falsch?","options":["Sie übersieht, dass der Schaden entsteht, wenn ein Heilversprechen eine wirksame Behandlung ersetzt, nicht schon durch den Trost selbst.","Sie übersieht, dass Trost grundsätzlich unwirksam ist und deshalb nie einen Nutzen für Menschen haben kann.","Sie übersieht, dass jede Glaubenspraxis mit vielen Anhängern automatisch schädlich für die Gesellschaft ist.","Sie übersieht, dass der Verkauf von Kristallen und Kursen allein schon beweist, dass die Absicht betrügerisch ist."],"correctIndex":0,"explanation":"Trost und Inspiration können für viele Menschen harmlos sein. Problematisch wird es dort, wo ein unbelegtes Heilversprechen eine nachweislich wirksame Behandlung verdrängt: Dann steht die Gesundheit auf dem Spiel, und die Berufung auf „jeder darf glauben, was er will“ geht am Kern vorbei. Ähnlich bedenklich ist es, wenn die ständige Selbst-Fokussierung („Du erschaffst deine eigene Realität“) dazu führt, dass Verantwortung für andere aus dem Blick gerät. Weder die bloße Zahl der Anhänger noch die Tatsache, dass Produkte verkauft werden, macht eine Praxis schon gefährlich; entscheidend sind die Folgen für konkrete Menschen. Und dass Trost an sich keinen Wert hätte, ist eine unbegründete Übertreibung.","coreRule":"⚡ Gefährlich wird eine Weltanschauung nicht durch ihren Trost, sondern dort, wo sie wirksame Behandlung ersetzt oder Mitmenschen aus dem Blick verliert.","beleg":"Werkstück F.4.1 (Abschluss-Diagnose des Pathologen)","status":"entwurf","scenario":"","kurz":"Trost und Glaube können harmlos sein. Gefährlich wird es, wenn ein unbelegtes Heilversprechen eine wirksame Behandlung verdrängt, denn dann steht die Gesundheit auf dem Spiel. „Jeder darf glauben, was er will“ geht an diesem Kern vorbei.","prueffrage":"Was hat die Schwester konkret aufgegeben, und was kann das bei einer Krebserkrankung bedeuten?","rueckmeldung":[{"option":1,"text":"Dass Trost eine Krebserkrankung nicht behandelt, stimmt. Daraus folgt aber nicht, dass er für Menschen nie nützlich wäre. Trost kann für viele durchaus wertvoll sein, der Einwand ist also zu absolut gefasst."},{"option":2,"text":"Wenn viele Menschen etwas glauben, wirkt das leicht bedeutsam oder bedenklich. Die Zahl der Anhänger sagt aber nichts darüber, ob eine Praxis schadet. Entscheidend sind die Folgen für konkrete Menschen, nicht die Verbreitung."},{"option":3,"text":"Geschäftsinteressen sind ein Anlass, genauer hinzusehen. Dass Kristalle und Kurse verkauft werden, beweist aber weder eine betrügerische Absicht noch Gefährlichkeit. Hier liegt das Problem im verdrängten Behandlungsweg, nicht im Verkauf."}],"familie":"ergaenzen-oder-ersetzen","fertigkeit":"F4","quellen":[{"typ":"doi","kurz":"Johnson, S. B.; Park, H. S.; Gross, C. P.; Yu, J. B. (2018): „Use of Alternative Medicine for Cancer and Its Impact on Survival“, J Natl Cancer Inst 110(1), S. 121–124 (Abstract öffentlich, PMID 28922780)","oeffentlich":true,"doi":"10.1093/jnci/djx145","abruf":"2026-10-12"},{"typ":"doi","kurz":"Asser, S. M.; Swan, R. (1998): „Child fatalities from religion-motivated medical neglect“, Pediatrics 101(4), S. 625–629 (Abstract öffentlich, PMID 9521945)","oeffentlich":true,"doi":"10.1542/peds.101.4.625","abruf":"2026-10-12"}],"thema":"Gesundheit"},{"id":"qx-f-058","clusterId":"F","werkstueckRef":"F.4.1","stufe":4,"question":"Ein Freund erklärt: „Ich glaube an Astrologie, Kristallheilung, Reinkarnation und an die Kraft positiven Denkens. Das passt alles zusammen, weil für mich zählt, was sich richtig anfühlt.“ Warum kann ein solches Weltbild praktisch jede unbelegte Behauptung problemlos aufnehmen?","options":["Weil jede neue Behauptung zuvor sorgfältig geprüft wird und nur die bestätigten in sein Weltbild gelangen.","Weil sein Weltbild ein festes Lehrgebäude besitzt, aus dem sich jede dieser Praktiken logisch ableiten lässt.","Weil die einzelnen Bausteine sich gegenseitig verdrängen, sodass am Ende nur ein einheitliches Glaubenssystem übrig bleibt.","Weil sein Weltbild keine feste Lehre und keinen Prüfmaßstab außer dem eigenen Gefühl kennt und deshalb alles einbauen kann."],"correctIndex":3,"explanation":"Ein Weltbild, das sich aus frei gewählten Bausteinen zusammensetzt und als einzigen Maßstab das eigene Gefühl akzeptiert, kennt kein Kriterium, das etwas ausschließen könnte. Wo nichts geprüft wird, kann auch nichts durchfallen: Astrologie, Kristallheilung und Reinkarnation lassen sich daher widerspruchslos nebeneinander einbauen, auch wenn keine davon belegt ist. Hinzu kommt: Kritik lässt sich mit Sätzen wie „Das ist nur deine materialistische Sichtweise“ abwehren, das System ist also nicht widerlegbar (unfalsifizierbar). Ein festes Lehrgebäude hätte dagegen Regeln, die manches ausschließen würden. Die Esoterik ersetzt überprüfbare Evidenz durch subjektive innere Erfahrung und macht sich dadurch immun gegen Kritik.","coreRule":"⚡ Wo nur das eigene Gefühl zählt, kann jedes Modul rein, auch das unbelegte: Ein Weltbild, das nichts ausschließt, belegt nichts.","beleg":"Werkstück F.4.1 (Die Esoterik als Wurzel und Nährboden; Abschluss-Diagnose des Pathologen)","status":"entwurf","scenario":"Gespräch mit einem Freund über sein persönliches Weltbild.","kurz":"Wo allein das eigene Gefühl zählt, gibt es keine feste Lehre und kein Kriterium, das etwas ausschließen könnte. Darum fällt nichts durch: Dass alles „zusammenpasst“, zeigt nur, dass nichts geprüft wird, nicht, dass etwas belegt ist.","prueffrage":"Hat der Freund je eine Überzeugung wieder aufgegeben, und was hätte ihn dazu bringen können?","rueckmeldung":[{"option":0,"text":"Offenheit für vieles könnte mit gründlicher Auswahl einhergehen. Der Freund sagt aber selbst, dass nur zählt, was sich richtig anfühlt. Ein Gefühl prüft nichts, deshalb fällt auch nichts durch."},{"option":1,"text":"Dass die Bausteine so gut zusammenpassen, wirkt wie ein durchdachtes System. Es gibt aber keine Lehre, aus der sich eine Praxis ableiten ließe, nur frei gewählte Elemente nebeneinander. Ein echtes Lehrgebäude würde manches ausschließen."},{"option":2,"text":"Man erwartet, dass sich Überzeugungen gegenseitig einschränken und ein einheitliches System entsteht. Hier verdrängt aber nichts etwas anderes: Alle Bausteine stehen nebeneinander, weil kein Maßstab etwas aussortiert."}],"familie":"immunisierung-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Hansson, S. O. (2008/2025): „Science and Pseudo-Science“, Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","seite":"Abschnitt 1, 4.3","abruf":"2026-10-12"},{"typ":"url","kurz":"Universität Münster, Exzellenzcluster Religion und Politik (2012): Pressemitteilung zur Patchwork-Religiosität (Christel Gärtner)","oeffentlich":true,"url":"https://www.uni-muenster.de/imperia/md/content/religion_und_politik/aktuelles/2012/12_2012/pm_patchwork-religiositaet.pdf","abruf":"2026-10-12"}],"thema":"Psychologie"},{"id":"qx-f-059","clusterId":"F","werkstueckRef":"F.4.2","stufe":1,"question":"Auf welche Art von Rechtfertigung stützt sich deine Freundin damit?","options":["Auf Autorität: Die Behauptung gilt als wahr, weil eine Schrift und eine Lehrinstanz sie bestätigen, nicht weil sie geprüft wurde.","Auf Experiment: Die Behauptung wurde unter kontrollierten Bedingungen getestet und hat sich dabei bewährt.","Auf Mehrheit: Die Behauptung gilt als wahr, weil die meisten Menschen auf der Welt sie unabhängig voneinander für richtig halten.","Auf persönliche Erfahrung: Die Behauptung gilt als wahr, weil sie selbst sie erlebt und für sich überprüft hat."],"correctIndex":0,"explanation":"Wer sich auf eine heilige Schrift und eine Lehrinstanz beruft, stützt sich auf Autorität: Die Wahrheit wird in diesem Rahmen nicht durch empirische Experimente entdeckt, sondern durch göttliche Offenbarung empfangen. Über Fragen von Sinn und Ethik hat die Wissenschaft nicht zu entscheiden. Bei überprüfbaren Tatsachenbehauptungen wie dem Alter der Erde betreten Glaubenslehren dagegen das Feld empirischer Prüfung, und Konflikte mit den Befunden sind deshalb angelegt. Dass eine Schrift und eine Gemeinde etwas lehren, ersetzt keine Prüfung.","coreRule":"⚡ Autorität ist keine Prüfung: Eine Aussage gilt nicht schon deshalb als belegt, weil eine Schrift oder Institution sie verkündet.","beleg":"Werkstück F.4.2 (Die epistemologische Grundlage: Offenbarung vs. Realität)","status":"entwurf","scenario":"Du diskutierst mit einer Freundin über die Frage, ob die Erde nur 6.000 Jahre alt ist. Sie entgegnet: „Ich glaube das, weil es in unserer heiligen Schrift steht und unsere Gemeinde es seit Jahrhunderten so lehrt.“","quote":"","quoteLabel":"","kurz":"Die Freundin beruft sich auf Schrift und Gemeindelehre, also auf Autorität. Eine Lehre ersetzt aber keine Prüfung, so alt sie auch ist, besonders bei Tatsachenfragen wie dem Alter der Erde.","prueffrage":"Was hat die Freundin selbst beobachtet oder gemessen, und was hat sie von anderen übernommen?","rueckmeldung":[{"option":1,"text":"Ein Experiment würde etwas Überprüfbares voraussetzen, das irgendwo kontrolliert getestet wurde. Genannt werden aber nur Schrift und Gemeindelehre. Beim Alter der Erde gibt es zwar empirische Befunde, doch auf die stützt sie sich nicht."},{"option":2,"text":"Eine lange Tradition kann nach breiter Zustimmung klingen. Gemeint ist aber nur die eigene Gemeinde, nicht die Mehrheit der Menschen, und deren Lehre wird weitergegeben, nicht von vielen unabhängig gewonnen."},{"option":3,"text":"Ihr Glaube kann sich für sie persönlich echt anfühlen. Als Grund nennt sie aber Schrift und Lehre, kein eigenes Erlebnis oder eine eigene Prüfung. Das Alter der Erde lässt sich ohnehin nicht durch bloßes Erleben überprüfen."}],"familie":"autoritaet-pruefen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"„Religion and Science“, Stanford Encyclopedia of Philosophy (2017, rev. 2022)","oeffentlich":true,"url":"https://plato.stanford.edu/entries/religion-science/","seite":"Abschnitt 1.3, 2.1, 3.1","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft"},{"id":"qx-f-060","clusterId":"F","werkstueckRef":"F.4.2","stufe":3,"question":"Worin liegt der entscheidende Unterschied zwischen dem Gespräch, das du als gefährlich einstufen würdest, und den harmlosen?","options":["Gefährlich ist D, weil dort eine überprüfbare Behauptung gegen Belege abgeschirmt und Zweifel als Sünde gebrandmarkt wird.","Gefährlich ist B, weil feste Schriften und eine verbindliche Auslegung durch die Gemeinde das Nachfragen stark erschweren.","Gefährlich ist C, weil große Reichweite und viel Einfluss in einer Stadt eine Gemeinschaft oft zur Bedrohung machen.","Gefährlich ist A, weil Aussagen über Sinn und Lebensführung der Wissenschaft entzogen sind und sich nicht prüfen lassen."],"correctIndex":0,"explanation":"Entscheidend ist, ob eine Aussage prüfbar ist und trotzdem gegen Belege geschützt wird. Ob Gebet eine medizinische Behandlung ersetzt, ist eine überprüfbare Behauptung über die Welt, und ein Irrtum kann hier das Leben des Kindes gefährden. Wird diese Frage zusätzlich mit „Sünde“ belegt, ist Zweifel nicht mehr erlaubt. Sinn, Trost und Gemeinschaft (A) sind keine Tatsachenbehauptungen, über die Belege entscheiden könnten, und feste Schriften (B) oder Einfluss (C) schirmen für sich genommen noch keine prüfbare Behauptung ab. Gefährlich wird es dort, wo prüfbare Behauptungen gegen Belege immunisiert werden, Zweifel als Sünde sanktioniert wird oder Ausgrenzung, Zwang oder Gewalt gerechtfertigt werden.","coreRule":"⚡ Sinn und Moral sind nicht das Problem; prüfbare Behauptungen, die Belege abwehren, sind es.","beleg":"Werkstück F.4.2 (Der Kipppunkt; Red Flags)","status":"entwurf","scenario":"Vier Gespräche über Glauben:\\n\\nA: Eine Frau sagt: „Mein Glaube gibt meinem Leben Sinn und der Gemeinde Halt.“\\nB: Ein Mann sagt: „Meine Religion hat feste Schriften, und unsere Gemeinde legt sie verbindlich aus.“\\nC: Eine Gemeinde unterstützt ihre Mitglieder stark und hat dadurch großen Einfluss in ihrer Stadt.\\nD: Ein Vater sagt: „Unser Sohn braucht keine Antibiotika, Beten heilt ihn. Wer daran zweifelt, versündigt sich.“","kurz":"Entscheidend ist, ob eine prüfbare Behauptung gegen Belege geschützt wird. Ob Beten Antibiotika ersetzt, lässt sich klären; wer Zweifel dazu als Sünde brandmarkt, verbietet die Prüfung. Sinn, Halt und Gemeinschaft stellen gar keine solche Behauptung auf.","prueffrage":"Was stünde in jedem der vier Gespräche auf dem Spiel, wenn sich die Beteiligten irren?","rueckmeldung":[{"option":1,"text":"Feste Schriften und verbindliche Auslegung können Nachfragen erschweren, das ist ein berechtigter Gedanke. Für sich genommen schützen sie aber noch keine prüfbare Behauptung gegen Belege und bestrafen keinen Zweifel; das fehlt in Gespräch B."},{"option":2,"text":"Große Reichweite und viel Einfluss wirken schnell bedrohlich. Sie sagen aber nichts darüber, ob etwas gegen Belege abgeschirmt wird; hier unterstützt die Gemeinde zunächst ihre Mitglieder, und Größe allein ist kein Gefahrenzeichen."},{"option":3,"text":"Dass Sinn und Lebensführung sich nicht wissenschaftlich prüfen lassen, stimmt. Genau deshalb steht dort nichts im Konflikt mit Belegen: Es wird keine Tatsache behauptet, über die Daten entscheiden könnten, also auch nichts gegen Belege geschützt."}],"familie":"immunisierung-erkennen","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Asser, S. M.; Swan, R. (1998): „Child fatalities from religion-motivated medical neglect“, Pediatrics 101(4), S. 625–629 (Abstract öffentlich, PMID 9521945)","oeffentlich":true,"doi":"10.1542/peds.101.4.625","abruf":"2026-10-12"},{"typ":"url","kurz":"Hansson, S. O. (2008/2025): „Science and Pseudo-Science“, Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","seite":"Abschnitt 1","abruf":"2026-10-12"}],"thema":"Zusammenleben"},{"id":"qx-f-061","clusterId":"F","werkstueckRef":"F.4.2","stufe":2,"question":"Welche Entgegnung auf diesen Satz ist am stärksten?","options":["Religiöse Menschen handeln im Alltag nachweislich etwas moralischer; trotzdem lässt sich Moral auch säkular begründen.","Nichtreligiöse Menschen handeln im Alltag nachweislich etwas moralischer; trotzdem lässt sich Moral auch säkular begründen.","Eine große Alltagsstudie fand keinen Unterschied im selbst berichteten moralischen Handeln beider Gruppen; zudem lässt sich Moral säkular begründen.","Moralisches Handeln im Alltag lässt sich nicht erfassen oder vergleichen; trotzdem lässt sich Moral auch säkular begründen."],"correctIndex":2,"explanation":"Die Behauptung unterstellt zweierlei: dass es ohne Religion an Moral mangelt und dass es ohne sie keinen verlässlichen Maßstab gibt. Empirisch befragten Hofmann u. a. (2014, Science) 1.252 Teilnehmende wiederholt im Alltag; religiöse und nichtreligiöse Menschen unterschieden sich nicht in Häufigkeit und Qualität selbst berichteter moralischer und unmoralischer Handlungen. Begründen lässt sich Moral auch säkular, etwa über Empathie, Vernunft und den Gesellschaftsvertrag, und selbst die Naturrechtstradition des Thomas von Aquin hält Moralgrundsätze für mit der Vernunft erkennbar. Ein Vorsprung einer der beiden Gruppen ist damit nicht belegt, und dass sich Alltagsmoral gar nicht erfassen lasse, trifft nicht zu, auch wenn Selbstauskünfte ihre Grenzen haben. Wer eine Behauptung prüfen will, fragt also: Was würde sie im Alltag vorhersagen, und stimmt das?","coreRule":"⚡ Wer behauptet, etwas sei die Voraussetzung für Moral, muss zeigen, dass es ohne sie weniger Moral gibt.","beleg":"Werkstück F.4.2 (Ethik und funktionierendes Zusammenleben); Fn. gl-f-hofmann (Hofmann u. a. 2014, Science 345, S. 1340--1343); Fn. gl-f-naturrecht","status":"entwurf","scenario":"Im Gespräch über Werte und Erziehung fällt der Satz: „Ohne Religion gibt es keinen verlässlichen Maßstab für Moral.“ Du willst die Behauptung prüfen, statt sie nur zu glauben oder abzulehnen.","kurz":"Die Behauptung lässt sich prüfen: Eine große Alltagsstudie fand keinen Unterschied in den selbst berichteten moralischen Handlungen religiöser und nichtreligiöser Menschen, und Moral lässt sich auch säkular begründen. Beides spricht gegen den „fehlenden Maßstab“.","prueffrage":"Was müsste man im Alltag religiöser und nichtreligiöser Menschen beobachten, wenn die Behauptung stimmt?","rueckmeldung":[{"option":0,"text":"Der zweite Teil stimmt: Moral lässt sich auch säkular begründen. Ein Vorsprung der Religiösen im Alltag ist aber nicht belegt; eine große Alltagsstudie fand in den selbst berichteten Handlungen beider Gruppen keinen Unterschied."},{"option":1,"text":"Dass sich Moral säkular begründen lässt, stimmt. Ein Vorsprung der Nichtreligiösen ist aber ebenso unbelegt wie die Ausgangsbehauptung, denn die Alltagsdaten zeigen keinen Unterschied zwischen den Gruppen."},{"option":3,"text":"Der Einwand klingt methodisch sorgfältig. Alltagsmoral lässt sich aber erfassen und vergleichen, etwa durch wiederholte Befragungen im Alltag, auch wenn Selbstauskünfte Grenzen haben. Die säkulare Begründung stimmt, ist aber nur die halbe Entgegnung."}],"familie":"beweislast-klaeren","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Hofmann, W.; Wisneski, D. C.; Brandt, M. J.; Skitka, L. J. (2014): „Morality in everyday life“, Science 345(6202), S. 1340–1343 (Abstract öffentlich, PMID 25214626)","oeffentlich":true,"doi":"10.1126/science.1251560","abruf":"2026-10-12"},{"typ":"url","kurz":"Murphy, M. (2002/2025): „The Natural Law Tradition in Ethics“, Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/natural-law-ethics/","seite":"Abschnitt 1.2","abruf":"2026-10-12"}],"thema":"Zusammenleben"},{"id":"qx-f-062","clusterId":"F","werkstueckRef":"F.4.2","stufe":4,"question":"In einem Vortrag heißt es: „Im Mittelalter glaubten alle an eine flache Erde, und die Kirche bekämpfte die Wissenschaft von jeher.“ Welche Einschätzung trifft zu?","options":["Die flache Erde ist eine Legende des 19. Jahrhunderts, der „ewige Krieg“ ist übertrieben, echte Einzelkonflikte gab es dennoch.","Beides stimmt im Kern: Die Kirche lehrte die flache Erde und verurteilte deshalb Kopernikus und Galilei als Ketzer.","Beides ist erfunden: Zwischen Kirche und Wissenschaft gab es nie einen nennenswerten Konflikt, auch nicht um Galilei.","Die flache Erde ist belegt, der Konflikt dagegen erfunden: Kirche und Wissenschaft arbeiteten stets harmonisch zusammen."],"correctIndex":0,"explanation":"Gelehrte des Mittelalters wussten, dass die Erde eine Kugel ist. Die Legende von der flachen Erde stammt aus dem 19. Jahrhundert, als Kirchenkritiker sie als Waffe im angeblichen Krieg zwischen Wissenschaft und Religion nutzten. Dass dieser Krieg „ewig“ gewesen sei, ist ebenfalls überzeichnet. Echte Konflikte gab es trotzdem: 1616 kam das Buch des Kopernikus auf den Index (er selbst war schon 1543 gestorben und wurde nie verurteilt), Galilei wurde 1633 verurteilt, und kreationistische Strömungen in manchen Religionsgemeinschaften bestreiten bis heute die Evolutionslehre. Die Streitfälle betrafen also das Weltbild und die Evolution, nicht die Kugelgestalt der Erde.","coreRule":"⚡ Der Konflikt war real, aber nicht ewig und nicht um die Kugelgestalt der Erde.","beleg":"Werkstück F.4.2 (Die epistemologische Grundlage); Fn. gl-f-flacheerde (Garwood 2008; Leisman 2019); Fn. gl-f-konflikt (Numbers 2009, S. 1 und 6)","status":"entwurf","kurz":"Die flache Erde im Mittelalter ist eine Legende des 19. Jahrhunderts, und der „ewige Krieg“ ist überzeichnet. Echte Streitfälle gab es trotzdem, etwa um Kopernikus und Galilei, und solche Zuspitzungen verführen dazu, Pauschalurteile zu übernehmen.","prueffrage":"Was schrieben Gelehrte des Mittelalters selbst über die Gestalt der Erde, und welche Streitfälle zwischen Kirche und Forschung sind mit Anlass und Datum überliefert?","rueckmeldung":[{"option":1,"text":"Die Konflikte sind real: Das Buch des längst toten Kopernikus kam 1616 auf den Index, Galilei wurde 1633 verurteilt. Sie betrafen aber das Weltbild, nicht die Erdform: Gelehrte des Mittelalters wussten, dass die Erde eine Kugel ist."},{"option":2,"text":"Die flache Erde ist tatsächlich eine Legende, und der „ewige Krieg“ ist überzeichnet. Ein „nie“ geht aber zu weit: Die Indizierung des Kopernikus 1616, Galileis Verurteilung 1633 und der Streit um den Kreationismus sind echte Konflikte."},{"option":3,"text":"Dass der angebliche Dauerkrieg übertrieben ist, stimmt. Die flache Erde ist aber gerade nicht belegt, und „stets harmonisch“ blendet echte Konflikte wie den Fall Galilei aus."}],"familie":"lehrgeschichte-pruefen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Russell, J. B. (1997): „The Myth of the Flat Earth“, Vortrag, American Scientific Affiliation","oeffentlich":true,"url":"https://www.asa3.org/ASA/topics/history/1997Russell.html","abruf":"2026-10-12"},{"typ":"url","kurz":"Miller, D. M. (2005/2025): „Galileo Galilei“, Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/galileo/","seite":"Abschnitt 2 und 5","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Numbers, R. L. (Hg.) (2009): Galileo Goes to Jail and Other Myths about Science and Religion. Harvard University Press (Einleitung S. 1, 6; Cormack, Myth 3, S. 28–34)","oeffentlich":false}],"thema":"Geschichte und Wissenschaft"},{"id":"qx-f-063","clusterId":"F","werkstueckRef":"F.4.3","stufe":1,"question":"Welche Frage prüft diese Behauptung am besten?","options":["Welche realen Ängste ihrer Entstehungszeit bündeln Zombiefilme, und was in Geschichte und Erzählung spricht dafür?","Wie viele Zuschauer haben Zombiefilme im Kino gesehen, und wie hoch waren ihre Einspielergebnisse?","Welche reale Tierart hat früher Menschen bedroht und könnte als Vorbild für den Zombie gedient haben?","Welche Regierung hat die Filme vermutlich in Auftrag gegeben, um die Bevölkerung gezielt zu verängstigen?"],"correctIndex":0,"explanation":"Die Frage macht die Deutung prüfbar: Welche Ängste und Spannungen ihrer Entstehungszeit bündeln Zombiefilme, und was spricht dafür oder dagegen? Der moderne Zombie lässt sich etwa als Bild für die Angst vor dem Verlust der Individualität lesen, in einer Masse, die nur noch konsumiert oder sich ansteckt. Das ist eine Lesart, kein Nachweis, aber sie nimmt die Zufallsbehauptung ernst und lässt sich an Geschichte und Erzählung überprüfen. Zuschauerzahlen zeigen dagegen nur, dass Filme ankommen, nicht warum, und ein reales Vorbild erklärt nicht, warum das Motiv gerade dann Konjunktur hat; einen Mythos allein auf reale Ereignisse zurückzuführen (Euhemerismus), greift meist zu kurz. Ein Auftraggeber wird ohne jeden Beleg unterstellt; diese Frage spekuliert über Absichten, statt den Gehalt der Behauptung zu prüfen.","coreRule":"⚡ Zeig mir dein Monster, und ich sage dir, wovor sich deine Zeit fürchtet.","beleg":"Werkstück F.4.3 (Kernidee; Die Autopsie der drei Archetypen; Red Flags)","status":"entwurf","scenario":"Eine Podcast-Hörerin sagt: „Zombiefilme sind doch nur Unterhaltung. Dass sie gerade in Zeiten von Massenkonsum und Pandemien so beliebt sind, ist Zufall.“","kurz":"Die Behauptung wird prüfbar, wenn man fragt, welche Ängste ihrer Entstehungszeit Zombiefilme bündeln und was in Geschichte und Erzählung dafür spricht. Das ist eine Lesart, kein Nachweis. „Nur Unterhaltung“ oder „Zufall“ ist damit nicht belegt, sondern bleibt offen.","prueffrage":"Gab es auch Jahrzehnte, in denen Zombiefilme beliebt waren, ohne dass Massenkonsum oder Seuchen die Menschen beschäftigten?","rueckmeldung":[{"option":1,"text":"Zuschauer- und Einspielzahlen zeigen, dass Filme ankommen. Warum Zombiefilme gerade dann Konjunktur haben, erklären sie nicht, und ob Ängste der Zeit darin stecken, bleibt unberührt."},{"option":2,"text":"Ein reales Vorbild kann ein Monster durchaus mitprägen. Als Antwort reicht das aber nicht: Einen Mythos allein auf reale Vorbilder zurückzuführen, greift meist zu kurz, und ob das Motiv gerade in solchen Zeiten Konjunktur hat, bleibt ungeprüft."},{"option":3,"text":"Die Frage nach einem Auftraggeber wirkt kritisch, weil sie nach Interessen fragt. Hier wird jedoch ohne jeden Beleg eine Absicht unterstellt, statt zu prüfen, ob die Filme Ängste ihrer Entstehungszeit aufgreifen."}],"familie":"schluss-pruefen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Grupe, D. (2014): „Faszination Zombie“, Schwäbische Zeitung (schwaebische.de), mit Aussagen von Gudrun Rath, Universität Konstanz","oeffentlich":true,"url":"https://www.schwaebische.de/panorama/faszination-zombie-762677","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Ackermann, H.-W.; Gauthier, J. (1991): „The Ways and Nature of the Zombi“, Journal of American Folklore 104(414), S. 466–494","oeffentlich":false,"seite":"S. 467, 489"}],"thema":"Geschichte und Wissenschaft"},{"id":"qx-f-064","clusterId":"F","werkstueckRef":"F.4.3","stufe":2,"question":"Ein Vortrag sagt: „Die Vampirlegende zeigt die Angst der Bauern vor dem adeligen Ausbeuter, siehe die Fälle von 1725 und 1732.“ Was ist an dieser Begründung fehlerhaft?","options":["Die Fälle von 1725 und 1732 betrafen Adelige, die ihre Untertanen aussaugten; die Deutung ist daher durch sie gedeckt.","Der Vampir stand in jeder Epoche allein für Seuchen und nie für gesellschaftliche Ausbeutung; die Deutung ist daher grundsätzlich falsch.","Die Fälle von 1725 und 1732 betrafen tote Dorfbewohner; der adelige Vampir ist erst eine spätere literarische Erfindung.","Die Fälle von 1725 und 1732 sind erfunden; aus dieser Zeit gibt es keine Berichte über Vampire oder Wiedergänger."],"correctIndex":2,"explanation":"Die Belege tragen die Deutung nicht: Die Fälle von 1725 (Plogojowitz) und 1732 (Paole) sind durch zeitgenössische amtliche Berichte gut belegt, betrafen aber tote Dorfbewohner, die als Wiedergänger galten, keine Adeligen. Den adeligen Verführer erfand John Polidori erst 1819 mit „The Vampyre“, Bram Stoker gab ihm 1897 seine endgültige Gestalt. Die Deutung als Bild für Ausbeutung passt also auf die Literaturfigur, nicht auf die Fälle, die der Vortrag als Beleg anführt. Seuchenangst und tabuisierte Sexualität sind weitere Hintergründe des Vampirmotivs.","coreRule":"⚡ Prüfe, ob der angeführte Beleg die Deutung wirklich trägt: Die Metapher vom adeligen Parasiten passt zum literarischen Vampir, nicht zu den Fällen des 18. Jahrhunderts.","beleg":"Werkstück F.4.3 („Der Vampir (Der adelige Parasit)“); Fn. gl-f-vampir-adel (Flückinger 1732; Bunson 2000; Bane 2010; Bräunlein 2015; Bohn 2008)","status":"entwurf","kurz":"Die angeführten Fälle betrafen tote Dorfbewohner, keine Adeligen; der adelige Vampir kam erst 1819 in der Literatur auf. Wer eine Deutung durch Fälle belegt, muss prüfen, ob diese Fälle überhaupt zur Deutung passen.","prueffrage":"Wer genau waren die Betroffenen in den Fällen von 1725 und 1732, und was berichten die damaligen Akten über sie?","rueckmeldung":[{"option":0,"text":"Solange man die Fälle nicht nachschlägt, wirkt die Deutung gedeckt. In den Fällen von 1725 und 1732 ging es aber um tote Dorfbewohner, nicht um Adelige, die ihre Untertanen aussaugten."},{"option":1,"text":"Seuchenangst ist tatsächlich ein wichtiger Hintergrund des Vampirmotivs, aber nicht der einzige. Die Ausbeutungsdeutung ist nicht grundsätzlich falsch: Sie passt auf die adelige Literaturfigur, nur nicht auf die angeführten Fälle."},{"option":3,"text":"Zweifel an alten Quellen sind oft berechtigt. Über beide Fälle gibt es aber zeitgenössische amtliche Berichte. Der Fehler der Begründung liegt woanders: Die Betroffenen waren tote Dorfbewohner, keine Adeligen."}],"familie":"schluss-pruefen","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Bräunlein, P. J. (2015): „Furchterregende Randzonen der Aufklärung: Skandalon Vampirismus“, Zeitschrift für Anomalistik 15, S. 55–87 (Repositorium Univ. Tübingen)","oeffentlich":true,"doi":"10.15496/publikation-39362","seite":"S. 61, 63","abruf":"2026-10-12"},{"typ":"doi","kurz":"Schneider, N. (2024): „Virale Monster: Spuren infektiöser Krankheiten im Vampirismus & die Konstruktion ansteckender Identität“, Thewis 11, S. 92–113","oeffentlich":true,"doi":"10.21248/thewis.11.2024.139","seite":"S. 97, 99","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft"},{"id":"qx-f-065","clusterId":"F","werkstueckRef":"F.4.3","stufe":3,"question":"Eine Schlagzeile behauptet: „Wissenschaftler haben das Rätsel gelöst: Vampire gab es nie, es waren Menschen mit Porphyrie!“ Wie solltest du diese Aussage einordnen?","options":["Als zu starke Behauptung: Eine Krankheit kann zu einem Mythos beigetragen haben, aber eine Ähnlichkeit einzelner Symptome beweist noch nicht, dass sie ihn vollständig erklärt.","Als belegt, weil Blässe, Lichtempfindlichkeit und rötliche Zähne bei Porphyrie vorkommen und damit alle Merkmale des Vampirs abgedeckt sind.","Als widerlegt, weil Porphyrie eine seltene Krankheit ist und seltene Krankheiten niemals Einfluss auf Volksglauben haben können.","Als sicher richtig, weil medizinische Erklärungen übernatürlichen Deutungen grundsätzlich überlegen sind und deshalb keiner weiteren Prüfung bedürfen."],"correctIndex":0,"explanation":"Die Schlagzeile schließt von einer Ähnlichkeit einzelner Symptome auf eine vollständige Erklärung. Das trägt nicht: Die Porphyrie-These ist in der Fachwelt umstritten. Winkler und Anderson bezeichnen sie als eher Gerücht denn als wissenschaftliche Theorie, ihr Urheber Dolphin habe sie nie veröffentlicht. Für Blutdurst bei Porphyriekranken oder eine Linderung durch Bluttrinken gibt es keinen Beleg. Der Vampir des Volksglaubens ging zudem auch bei Tageslicht um, die Lichtscheu kam erst später durch Filme wie „Nosferatu“ (1922) ins Vampirbild. Dasselbe gilt für die Tollwut-These: Auch dort wird Tollwut nur als einer von mehreren möglichen Beiträgen zu Werwolf- und Vampirlegenden verstanden. Eine medizinische Parallele kann ein Echo sein. Ob sie eine Erklärung ist, zeigt erst ein Beleg dafür, dass die Krankheit die Geschichte tatsächlich hervorgebracht hat. Wer Ähnlichkeit mit Ursache gleichsetzt, ersetzt die Prüfung durch eine passende Geschichte.","coreRule":"⚡ Eine Ähnlichkeit ist ein Hinweis, kein Beweis: Medizinische Parallelen liefern ein Echo, nicht automatisch die ganze Erklärung.","beleg":"Werkstück F.4.3 (Das medizinische Echo); Fn. gl-f-11 (Gómez-Alonso 1998; Wasik, Murphy 2012); Fn. gl-f-12 (Winkler, Anderson 1990)","status":"entwurf","scenario":"","kurz":"Eine Krankheit kann zu einem Mythos beigetragen haben, doch die Ähnlichkeit einzelner Symptome erklärt ihn noch nicht. Der Fehler: aus „passt zusammen“ eine Ursache zu machen, ohne zu prüfen, ob die Krankheit die Geschichte wirklich hervorgebracht hat.","prueffrage":"Welche Merkmale des Vampirs im alten Volksglauben passen zu den Symptomen, und für welche gibt es überhaupt einen Beleg?","rueckmeldung":[{"option":1,"text":"Einzelne Symptome kommen bei Porphyrie tatsächlich vor, daher wirkt die Erklärung stimmig. „Alle Merkmale“ sind damit aber nicht abgedeckt: Für Blutdurst gibt es keinen Beleg, und die Lichtscheu kam erst durch Filme wie „Nosferatu“ ins Vampirbild."},{"option":2,"text":"Die Skepsis gegenüber der Schlagzeile ist berechtigt, die Begründung aber zu absolut. Auch seltene Krankheiten können zu einer Legende beitragen; unbelegt heißt nicht widerlegt. Entscheidend ist, ob es einen Beleg für den Zusammenhang gibt."},{"option":3,"text":"Medizinische Deutungen wirken nüchterner und daher überzeugender als übernatürliche. Auch sie müssen aber belegt werden, und hier fehlt der Beleg: Die Porphyrie-These ist umstritten, ihr Urheber hat sie nie wissenschaftlich veröffentlicht."}],"familie":"schluss-pruefen","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Cox, A. M. (1995): „Porphyria and vampirism: another myth in the making“, Postgraduate Medical Journal 71(841), S. 643–644 (PMC2398345)","oeffentlich":true,"doi":"10.1136/pgmj.71.841.643-a","seite":"S. 643 f.","abruf":"2026-10-12"},{"typ":"doi","kurz":"Gómez-Alonso, J. (1998): „Rabies: a possible explanation for the vampire legend“, Neurology 51(3), S. 856–859 (Abstract öffentlich)","oeffentlich":true,"doi":"10.1212/wnl.51.3.856"},{"typ":"literatur","kurz":"Winkler, M. G.; Anderson, K. E. (1990): „Vampires, Porphyria, and the Media: Medicalization of a Myth“, Perspectives in Biology and Medicine 33(4), S. 598–611, DOI 10.1353/pbm.1990.0051","oeffentlich":false,"seite":"S. 598, 600, 606"}],"thema":"Geschichte und Wissenschaft"},{"id":"qx-f-066","clusterId":"F","werkstueckRef":"F.4.3","stufe":4,"question":"Was ist an dieser Sprache problematisch, und woran erkennst du es?","scenario":"Ein Redner nennt eine Minderheit eine „Seuche“ und „Bestien“, vor denen man das Land schützen müsse.","options":["Die Bilder werden auf reale Menschen angewendet: Eine ganze Gruppe wird zum Monster erklärt und damit zur Zielscheibe, gegen die Hass und Gewalt gerechtfertigt erscheinen.","Die Bilder sind zu drastisch: Hätte der Redner seine Ängste nüchterner formuliert, wäre die Rede ein unproblematischer Beitrag zur Debatte gewesen.","Die Bilder sind unbelegt: Solange der Redner keine Zahlen zu Seuchen und Gefahren nennt, lässt sich die Rede nicht beurteilen.","Die Bilder sind veraltet: Moderne Gesellschaften verarbeiten ihre Ängste inzwischen über andere Metaphern, sodass Monster-Sprache heute wirkungslos bleibt."],"correctIndex":0,"explanation":"In Geschichten sind Monster Spiegel von Ängsten: Man projiziert die Furcht in eine erfundene Figur, bekämpft sie und erlebt eine symbolische Entlastung. Dabei trifft die Gewalt niemanden. Hier läuft es umgekehrt: Das Monster-Bild wird auf reale Menschen gelegt. Wer als „Bestie“ oder „Seuche“ gilt, wird entmenschlicht, und gegen eine Seuche darf man alles tun. So lenkt Propaganda reale Ängste auf ein Feindbild. Es geht also nicht um Tonfall oder Zahlen, sondern um die Funktion der Sprache: Sie macht Menschen zu Zielscheiben. Selbst mit Statistiken oder in sachlicherem Ton bliebe diese Wirkung bestehen. Veraltet sind solche Bilder auch nicht: Sie werden bis heute gegen Gruppen eingesetzt, und die Geschichte zeigt, dass entmenschlichende Propaganda Gewalt vorbereiten kann.","coreRule":"⚡ Monster in der Fiktion sind Spiegel; Monster-Sprache über Menschen ist Entmenschlichung.","beleg":"Werkstück F.4.3 (Anwendung & Relevanz: Im Verständnis von Propaganda; Der Kipppunkt)","status":"entwurf","quote":"","quoteLabel":"","kurz":"Problematisch ist die Funktion der Sprache, nicht ihr Ton: Das Monster-Bild trifft reale Menschen, die als „Seuche“ entmenschlicht werden, und gegen eine Seuche scheint alles erlaubt. Der Denkfehler ist, an Tonfall oder Zahlen zu messen, was die Sprache bewirkt.","prueffrage":"Was bliebe von der Forderung des Redners übrig, wenn er dieselbe Gruppe in ruhigem Ton und mit Zahlen beschriebe?","rueckmeldung":[{"option":1,"text":"Drastische Bilder fallen sofort auf, deshalb wirkt der Ton wie das Problem. Entscheidend ist aber, was die Sprache mit den Betroffenen macht: Auch in nüchterner Form bliebe eine Gruppe als Gefahr gebrandmarkt."},{"option":2,"text":"Belege einzufordern ist grundsätzlich sinnvoll, und Behauptungen über Gefahren lassen sich prüfen. Die Rede lässt sich hier aber schon beurteilen: Auch mit Zahlen bliebe die entmenschlichende Wirkung bestehen."},{"option":3,"text":"Dass sich Ängste neue Bilder suchen, kommt vor. Doch Wörter wie „Seuche“ und „Bestien“ werden bis heute gegen Gruppen benutzt, wie diese Rede zeigt, und ihre entmenschlichende Wirkung hängt nicht davon ab, ob das Bild alt ist."}],"familie":"wir-und-die-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"United States Holocaust Memorial Museum: „Nazi Propaganda“, Holocaust Encyclopedia","oeffentlich":true,"url":"https://encyclopedia.ushmm.org/content/en/article/nazi-propaganda","abruf":"2026-10-12"},{"typ":"doi","kurz":"Over, H. (2021): „Seven Challenges for the Dehumanization Hypothesis“, Perspectives on Psychological Science 16(1), S. 3–13 (PMC7809340)","oeffentlich":true,"doi":"10.1177/1745691620902133","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Haslam, N. (2006): „Dehumanization: An Integrative Review“, Personality and Social Psychology Review 10(3), S. 252–264, DOI 10.1207/s15327957pspr1003_4","oeffentlich":false}],"thema":"Zusammenleben"}]`);export{t as n,n as t};